window.HB_TR["acts"]["ks"]=["1. اے تھیوفیلس، یُس سٲری یُس حضرت عیسیٰ علیہ السلامن کرُن تہٕ ہیچھناوُن شروع کورمُت،\n2. ییمہِ دۅہہٕ سُہ تُلنہٕ آو، تمہِ پتہٕ اوس تٔمۍ روح القدس سٕندِ ذریعہٕ رسولن حکم دِژمُت یِم تٔمۍ ژٲرمٕتۍ ٲسۍ۔\n3.\\tیٔمِس سٍتـ̡ ہٲوِن پننِس جذبہٕ پَتہٕ واریہو ناقص ثبوتو سٍتـ̡ زندٕ، یِمن مُتلق ژتٲجی دۅہہٕ وُچھنہٕ آمُت، تہٕ خدایہ سٕنزِ بادشٲہی سٍتـ̡ کتھ کٔرِتھ:\n4.\\tتہٕ یِمن سٍتـ̡ جمع سپدِتھ دِیُت تِمن حُکُم زِ تِم گژھن نہٕ یروشلم پى۪ٹھٕ نیرُن، بٔلکہِ گژھن مٲلہِ سٕندِس وعدس پیٛارُن، یُس ژے میانہِ مُتلق بوزمُت چُھ۔ {آسن...: یا، یکوٹہ کھٮ۪ن}\n5. یوحنا سٕندِ خٲطرٕ آو پٔزۍ پٲٹھـ̡ آبہٕ سٍتـ̡ بپتسمہ د مگر یِیہِ نہٕ واریاہ دۅہہٕ پتہٕ روح القدس سٍتـ̡ بپتسمہ دِنہٕ۔\n6. یێلہِ یێلہِ تِم اَکہٕ وٹہٕ وٲتِتھ، تِمو پرژھ أمِس نِش زِ خداوند، کیا ژٕ کٔرِکھ یێمہِ وِزِ اِسرٲیلِس دُبارٕ بادشٲہی دُبارٕ دِنہٕ؟\n7. تہٕ تٔمۍ ووٚن تِمَن زِ یہِ چُھنہٕ تۅہہِ ہٕندِ خٲطرٕ زِ تِم وقت تہٕ موسمہٕ زانٕن، یُس مٲلہِ پننِس اختیارس مَنٛز دِژمُت چھُ۔\n8. مگر یێمہِ پَتہٕ یێلہِ روح القدس پانس پیٹھ یِنہٕ پتہٕ تہٕ یێلہِ تہٕ یێلہِ تہٕ سارِنٕے یہوداہس مَنٛز تہٕ سامریاہس مَنٛز تہٕ زمینہٕ کِس اندِس حصس مَنٛز تہٕ تێلہِ گٔژھِو میانہِ گواہ ۔ {طاقت...: یا، روح القدس سُند طاقت یُس توے پیٹھ یِوان}\n9.\\tتہٕ ییلہ تٔمۍ یِم کتھ کٔرِتھ، ییٚلہِ تِم وُچھان ٲسۍ، سُہ آو تُلنہٕ۔ تہٕ أکۍ اوٚبرٕ آو سُہ تِہٕنزِ نظرِ نِش نِش۔\n10.\\tتہٕ ییلہ تِم ہیوٚر کھسنہٕ وِزِ اسمانس کُن وُچھان ٲسۍ، وُچھ زٕ نفر سفید پوشن منز تِمن نِش کھڑا ۔\n11.\\tیێمہِ سٍتـ̡ یہ تہِ وونُن زِ اے گلیل ہٕندِس انسانو، اسمانس کُن کیازِ چھِو وُچھان؟ یۅہے عیسیٰ مسیح، یُس توے نِش جنتس مَنٛز تُلِتھ چُھ، یِتھٕ پٲٹھـ̡ یێلہِ ژے سُہ جنتس مَنٛز وُچھمُت چُھ۔\n12. پَتہٕ گٔیہِ تِم زیتون نٲوِتھ پہاڑہٕ پیٹھٕ یروشلم واپس، یُس یروشلم پیٹھٕ سبت دۅہُک سفر چھُ۔\n13. تہٕ ییلہ تِم اژنہٕ آیہ، تِم گٔیہِ أکِس ہیٚرمِس کمرس مَنٛز، یَتھ مَنٛز پطرس، تہٕ یعقوب، تہٕ یوحنا، تہٕ اینڈریو، فلپ، تہٕ تھامس، بارتھولومیو تہٕ میتھیو، یعقوب سُند نیٚچُو، تہٕ شمعون زیلوٹس، تہٕ یہوداہ {یعقوب سُند بوے} روزان ٲسۍ۔\n14.\\tیِم سارِوٕے رودۍ دُعا تہٕ دُعا سٍتـ̡ زنانن سٍتـ̡ تہٕ عیسیٰ سٕنزِ موج مریم تہٕ تٔمۍ سٕندِس باین سٍتـ̡ دُعا تہٕ دُعا سٍتـ̡ اَکہٕ وِزِ سٍتـ̡ جٲری۔\n15.\\tتہٕ تِمن دۅہن ووت پطرس شاگردن منز کھڑا تہٕ وونُن، (ناوَن ہُند تعداد اوس تقریباً ہتھ وُہ۔)\n16.\\tانسانو {تہٕ} بٲے، یہ صحیفہ گژھہِ پورٕ سپدُن، یُس روح القدس داؤد سٕندِ زبانہِ سٍتـ̡ یہوداہ سٕندِس بارس مُتلق کتھ کرمژ، یُس تِمن ہٕندِ خٲطرٕ رہنُمٲیی اوس یُس عیسیٰ مسیح نِش رٔٹِتھ اوس۔\n17.\\tتکیازِ سُہ اوس اسہِ سٍتـ̡ شمار کرنہٕ آمُت، تہٕ اوسُن امہِ وزارتُک حصہٕ حٲصل کورمُت۔\n18.\\tوۅنۍ ہیوٚت أمس نفرن بدکاری ہٕندِس انعامس سٍتۍ اکھ کھیت ہیوٚت۔ تہٕ کلہٕ پیوٚو سُہ ژٔٹِتھ تہٕ تٔمۍ سٕنزِ سارِنٕے أندرِ دٔرۍ۔\n19. تہٕ یِہ اوس یروشلمس مَنٛز سارِنٕے بسکیٖنن ہٕندِس پٲٹھـ̡ زانان۔ یوت تام اتھ میدانس تہنزِ مناسب زبانہِ منز چھہِ Aceldama وننہ یوان، یعنی خونُک میدان۔\n20. تکیازِ یہ چھہ زبور چہِ کتابہِ منز لیکھنہ آمت، تسنز رہائش گاہ گژھہِ ویران تہ کانہہ تہِ انسان گژھہِ نہ اتھ منز روزُن، تہ تسند بشپ گژھہِ بییِس نِش روزُن۔ {بشوپرک: یا، دفتر، یا، چارج}\n21. یِمو لُکھ یِمو سارِوٕے وقتس سٍتـ̡ اسہِ سٍتـ̡ رٔلِتھ روزان چُھہ یێلہِ خداوند عیسیٰ سُند اسہِ مَنٛز اژان تہٕ نٮ۪بر گۆو،\n22. یوحنا سٕندِ بپتسمہ دِنہٕ پیٹھٕ یێمہِ دۅہہٕ یێلہِ سُہ اسہِ نِش تُلنہٕ آو، تێلہِ گژھہِ کٲنسہِ سٍتـ̡ تٔمۍ سٕندِس قیامتُک گواہ بنُن مقرر کرنہٕ یُن۔\n23.\\tتہٕ تِمو کٔر زٕ مُقرر، یوسفَس اوس بارساباس ناو دِنہٕ آمُت، یٔمِس جسٹس تہٕ متھیاس ناو اوس۔\n24.\\tتہٕ تِمو کٔر دُعا تہٕ وونُن، اے خداوند، یُس سارِنٕے انسانن ہٕندِس دِلس زانان چُھ، ہٲو ژے یِمو دۄن منزٕ ژٲرمُت،\n25.\\tیُتھ سُہ گژھہِ اتھ وزارتس تہٕ رسولس منز حصہٕ نِتھ، یێمہِ سٍتـ̡ یہوداہ گٔیہِ پننہِ جایہ گژھُن۔\n26. تہٕ تِمو دِژ پنٕنۍ لاٹ۔ تہٕ لُٹ پیوٚو متھیاسس پیٹھ۔ تہٕ سُہ اوس کاہ رسولن سٍتـ̡ شمار کرنہٕ آمُت۔","1. تہٕ ییلہ پینتیکوسٹُک دۅہ پورٕ پٲٹھۍ، تِم سٲری ٲسۍ اکۍ سٍتـ̡ اَکہِ جایہِ اَکہِ سٍتـ̡\n2.\\tتہٕ اچانک دراو آسمانہٕ منزٕ تیز واو ہٕنز آواز، تہٕ اَمہ سٍتـ̡ بٔرِتھ سٲرۍسٕے گرس ییتہِ تِم بِہتھ ٲسۍ۔\n3.\\tتہٕ تِمن نِش گٔیہِ نار ہٕندۍ پٲٹھۍ، تہٕ یہِ بِہتھ پرٮ۪تھ أکِس پیٹھ۔\n4. تہٕ تِم سارِوٕے گٔیہِ روح القدس سٍتـ̡ بٔرِتھ، تہٕ لوگُکھ باقین زبانن سٍتـ̡ کتھ کرنہٕ، یێلہِ روٝحہِ سٍتـ̡ تِمن ہُند کلام دِیُت۔\n5.\\tتہٕ یروشلمس مَنٛز ٲسۍ یہودی روزان، پریتھ قومہٕ منز۔\n6.\\tوۅنۍ ییلہ یہ نیبر کُن شور آو کرنہٕ، ہجوم گٔے اکوٹہٕ، تہٕ گٔیہ پریشان، تکیازِ پرٮ۪تھ کانہہ انسان اوس تِم پننہِ زبانہِ منز بولان بوزان۔ {اوس...: Gr. آواز ٲس پریشان کٔرمٕژ: یا، ذہنس منز پریشان}\n7.\\tتہٕ تِم سٲری گٔیہِ حٲران تہٕ حٲران تہٕ اَکھ أکِس وَنُن، وُچھِو، یِم سٲری چھِنہٕ گلیلیٲیی بولان چھِ؟\n8.\\tتہٕ کِتھہ کٔنۍ چھہِ أسۍ پریتھ انسان پننہِ زبانہِ منز بوزان، یتھ منز أسۍ زامٕتۍ ٲسۍ؟\n9. پارتھی، تہٕ میڈس، تہٕ ایلامی، تہٕ میسوپوٹیمیاہس منٛز، تہٕ یہوداہ، تہٕ کیپاڈوشیاہس منٛز، پونٹس تہٕ ایشیاہس منٛز روزن وٲلۍ،\n10. فریجیا، تہٕ پامفیلیا، مصرس مَنٛز، تہٕ لیبیا کین حصن مَنٛز، تہٕ رومٕکۍ اجنبی ، یہودی تہٕ مذہب بدلاون والۍ،\n11. کریٹس تہٕ عرب، أسۍ چھِ تِم سانہِ زبانہِ مَنٛز خدایہ سٕندِ حیرت انگیز کامہِ ہٕنز کتھ بوزان۔\n12.\\tتہٕ تِم سٲری گٔیہِ حٲران تہٕ شَکھ گٔیہِ، اَکھ أکِس سٍتـ̡ وَنُن، اَمیُک کیا مطلب چُھ؟\n13.\\tباقیو چھہ ٹھٹھہٕ کران ونان زِ یم نفر چھہِ نوِ شرابس سٍتۍ بٔرِتھ۔\n14. مگر پطرس کٔر کاہَن ہٕندِس سٍتـ̡ تھوٚد تہٕ تِمن وونُن، اے یہوداہٕکۍ لوکو تہٕ یُس یروشلمس مَنٛز روزان چُھ، تہٕ میانہِ کلامَس بوزُن:\n15.\\tتکیازِ یِم چھِنہٕ شرابہٕ، یُتھ زن تۅہہ خیال چُھ، وُچھِتھ چُھ یہِ دۅہُک تریم گھنٹہٕ۔\n16.\\tمگر یۅہے سُہ یُس حضرت یوایلن کُن وننہ اوس آمت۔\n17. تہٕ یہِ سپدِ ٲخری دۅہن منز، خدایہ چُھس ونان زِ بہٕ تراوٕ پننہِ روحہٕ سٍتـ̡ سارِنٕے جسمس پیٹھ۔ تہٕ تُہند نیچو تہٕ کورِ کرن پیشن گوئی، تہٕ تُہند جوان وُچھن خواب، تہٕ تُہند بُزرگ خواب وچھن:\n18.\\tتہٕ پننین خدمتگارن تہٕ پننین خادمن پیٹھ بہٕ کٔرٕ پننہ روح کِس تمن دۅہن منز۔ تہٕ تِم کرِ پیشن گوئی:\n19. تہٕ بہٕ ہاوٕ ہیرِ آسمانس مَنٛز عجائبات تہٕ بۅنہ کنہِ زمینس مَنٛز نشانہٕ۔ خون، تہٕ نار، تہٕ دھوکہٕ ہُند بخار:\n20.\\tخداوند سُند یہ عظیم تہٕ قابل ذکر دۅہ یِنہٕ برونہہ گژھہِ آفتاب انہِ گوٚٹ تہٕ زونہِ خونس مَنٛز۔\n21. تہٕ یێلہِ یُس تہِ خداوند سُند ناو پکار کرِ، سُہ گژھہِ نجات دِنہٕ۔\n22.\\tاے اسرٲیلِیو یِم کلام بوزو۔ عیسیٰ مسیح، یُس یُس خدایہِ سُند معجزو تہٕ عجائب تہٕ نشانو سٍتـ̡ منظوٗر کورمُت، یُس خدایہِ سٍتـ̡ تہٕ تُہۍ تہِ زانان چھِو:\n23. سُہ چُھہ خدایہ سٕندِ مُقرر مشورٕ تہٕ پیشگی علمہٕ سٍتـ̡ نجات دِنہٕ آمُت، تہٕ بدکار اتھو سٍتـ̡ چُھکھ صلیب دِتھ مارنہٕ آمُت:\n24.\\tیُس خداین موتُک دَگ دِتھ زندٕ کورمُت چھُ، تکیازِ یہ اوس نہٕ ممکن زِ سُہ گژھہِ اتھ رٔٹِتھ روزُن۔\n25.\\tتکیازِ داؤد چُھ أمِس مُتلق کتھ کران، میہ وُچھ خداوند سُند ہمیشہ میٲنِس بُتھِس برونہہ کُن، تکیازِ سُہ چُھ میٲنِس دچھنہِ اتھس پیٹھ، یُس بہٕ گژھہِ نہٕ ہُراونہٕ یُن:\n26. تێمہِ کِنۍ گۆو میون دِل خۅش، تہٕ میٲنۍ زبان گٔیہِ خۅش۔ امہ علاوہ تہِ روزِ میون ماز وۅمید منز:\n27. کیازِکہ ژے تراوٕ نہٕ میون روح جہنمس مَنٛز، تہٕ نہ کرٕ ژے پنُن مقدس بد عنوانی وُچھنُک اجازت۔\n28. ژے کٔر میہ زندگی ہٕندِ طریقہٕ سٍتـ̡ زان۔ ژے کٔرِکھ میہ پننہِ شکلہِ سٍتۍ خوشی سٍتۍ بٔرتھ۔\n29.\\tانسانو {تہٕ} بٲے، بہٕ چُھس ژے سٍتـ̡ آزادانہٕ پٲٹھـ̡ مٲلِس ڈیوڈس مُتعلِق کتھ کٔرِتھ، زِ سُہ چُھ موٗدمُت تہٕ دفن گومُت، تہٕ تٔمۍ سُند قبر چُھ از تام اسہِ سٍتـ̡ ۔ {میہ دِیو: یا، بہٕ ہیکہِ}\n30. تێمہِ کِنۍ پیغمبر آسنہٕ کِنۍ، تہٕ یہ زانِتھ زِ خداین اوس أمِس سٍتـ̡ حلف کٔرمُت، یُس مازٕ مطٲبق تٔمۍ سٕندِس کمرُک پھل چُھ، سُہ کرِ مسیح پننِس تختس پیٹھ بِہنہٕ خٲطرٕ تُلان۔\n31. یێمہِ سُند روح اوس نہٕ جہنمس مَنٛز تراونہٕ آمُت، تہٕ نہ اوس تٔمۍ سٕندِس مازس وُچھمُت۔\n32. یێمہِ عیسیٰ مسیح چُھہ خدایہِ سٍتـ̡ تُلمت یێمہِ سٍتـ̡ أسـ̡ سارِوٕے گواہ چِھہِ۔\n33. تێمہِ کِنۍ چُھہ خدایہ سٕندِ دچھنہِ اتھہٕ سٍتـ̡ تہٕ روح القدس سُند وعدٕ حٲصل کٔرِتھ، تێمہِ چُھ یہِ ظٲہر کٔرِتھ، یُس تُہۍ وُنہِ وُچھان تہٕ بوزان چھِو۔\n34.\\tتکیازِ داؤد چُھنہٕ آسمانس مَنٛز کھسُن، مگر سُہ چُھ پانَس ونان زِ خداوند چُھ میٲنِس آغس سٍتـ̡ بِہتھ میانہِ دچھنہِ اتھس پیٹھ،\n35.\\tیوٚت تام نہ بہٕ چانۍ دُشمن پنُن کھۅر بٔنِتھ۔\n36. تێمہِ کِنۍ گژھہِ سارِنٕے اِسرٲیلِس پٲٹھـ̡ زان زِ خداین چُھ سُے عیسیٰ مسیح بنوومُت، یُس تۅہہ مصلوب کورمُت چُھ، خداوند تہٕ مسیح دونوے ۔\n37.\\tیێلہِ ییلہ تِمو یہِ بوٗزِ، تِمو گٔیہِ دِلَس مَنٛز چُھکھ تہٕ وونُکھ پطرس تہٕ باقٕے رسولن، انسانو {تہٕ} بٲے، أسۍ کیا کرو ؟\n38. پطرس ووٚن تِمن توبہٕ تہٕ گۅنہن ہٕنزِ معافی خٲطرٕ کٔرِو عیسیٰ مسیح سٕندِ ناوٕ سٍتـ̡ بپتسمہ دِنہٕ، تہٕ یێلہِ گژھہِ روح القدس سُند تحفہٕ حٲصل کرنہٕ۔\n39. یێلہِ وعدٕ چُھہ تۅہہِ سٍتـ̡ تہٕ تُہٕندِس شُرین سٍتـ̡ تہٕ سارِنٕے دوٗر روزن وٲلِس سٍتـ̡ چُھہ یێلہِ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ سٍتـ̡\n40. تہٕ بییہِ واریاہو لفظو سٍتـ̡ دِژ تٔمۍ گوٲہی تہٕ نصیحت دِژٕن، یێمہِ ناپسندیدٕ نسلہٕ نِش بچٲوِو پنُن پان۔\n41. پَتہٕ یِمو تٔمۍ سُند کلام خوشی سان رٔٹِتھ بپتسمہ دِنہٕ، تہٕ امی دۅہہ گٔیہِ تِمن سٍتـ̡ تقریباً ترے ساس روحہٕ شٲمل کرنہٕ۔\n42. تہٕ تِمو رودۍ رسولن ہٕندِس نظریہس تہٕ رفاقتس منز، روٹی پھُٹراونس منز، تہٕ دعاہس منز ثابت قدمی سان جٲری۔\n43.\\tتہٕ آو پرٮ۪تھ أکِس نفسس سٍتـ̡ خوف تہٕ رسولن ہٕندِ دٔسۍ واریاہ عجائب تہٕ نشانہٕ کرنہٕ۔\n44. تہٕ یِم سٲری ایمان تھاوان ٲسۍ، تہٕ سارِنٕے چیز ٲسۍ ہِشر۔\n45.\\tتہٕ کٕنُن پنُن مال تہٕ سامانہٕ تہٕ کٔرٕن سارنٕے انسانس خٲطرٕ تقسیم۔\n46.\\tتہٕ تِم ٲسۍ دۅہٕ دۅہہٕ أکِس سٍتـ̡ مندرس مَنٛز روزان، تہٕ گَرٕ گَرٕ بٔنِتھ روٹی پھٔٹِتھ، تِم ٲسۍ پنُن ماز خوشی تہٕ کُنہِ دِلہٕ سٍتـ̡ کھٮ۪وان، {پیٹھ...: یا گَرِ منز}\n47.\\tخدایہ سُند حمد کرُن تہٕ سارِنٕے لُکن ہٕندِس سٍتـ̡ احسان حٲصل کرُن۔ تہٕ خداوند اوس کلیساہَس مَنٛز روزانہٕ یُتھ نجات دِنہٕ یُن۔","1. وۅنۍ گٔیہِ پطرس تہٕ یوحنا عبادت کِس وقتس پیٹھ اِکہٕ وٹہٕ مندرس مَنٛز، {نٔوِمِس {گھنٹ} آسنہٕ کِنۍ۔\n2.\\tتہٕ أکِس شخٕص سٕندِس ماجہ ہٕندِس کونہٕ منزٕ لوٚنگہٕ نِنہٕ آمُت، یُس تِمو دۅہہٕ دۅہہٕ مندر کِس دروازس پیٹھ تھوان اوس، یُس مندرس منز اژان اوس تِمن نِش خیرات منگان۔\n3. یُس پطرس تہٕ یوحنا مندرس مَنٛز گژھن وُچھِتھ وُچھِتھ منگُن خیرات۔\n4. تہٕ پطرس اوس یوحنا سٍتـ̡ أمِس کُن نظر ترٲوِتھ وونُن، وُچھِو اسہِ کُن۔\n5.\\tتہٕ تٔمۍ کٔر تِمن کُن توجہ دِنہٕ، یہ وۅمید زِ تِمن ہُند کینہہ میلہِ۔\n6. پطرس ووٚن رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ چُھہ نہٕ میہ کانہہ تہِ۔ مگر یُتھ میہ ژیہ دِژمُت: عیسیٰ مسیح سٕندِ ناوٕ سٍتـ̡ وۅتھُن تہٕ پکُن۔\n7.\\tتہٕ تٔمۍ رٔٹ أمِس دٔچھُن اتھہٕ تھپھ کٔرِتھ تھوٚد تہٕ تُلُن تٔمِس کھورِ تہٕ کھورِ ہٕنزِ أڈجہِ ہٕندِس دٔسۍ مضبوط۔\n8. تہٕ سُہ ووٚتھ تھوٚد تہٕ پکان تہٕ تِمن سٍتـ̡ ژاو مندرس مَنٛز، پکان تہٕ وۄٹھ دِتھ تہٕ خدایہ سٕنز حمد کٔرِتھ۔\n9.\\tتہٕ سارِوٕے لُکھ وُچھ سُہ پکان تہٕ خدایہ سٕنز حمد کران وُچھان:\n10.\\tتہٕ تِمن ٲس پتاہ زِ یہِ اوس سُہ یُس مندر کِس خوبصورت دروازس پیٹھ خیرات خٲطرٕ بِہتھ اوس، تہٕ یُس أمِس سٍتـ̡ سپدیومُت اوس، تِم گٔیہِ حٲران تہٕ حٲران سٍتـ̡ بٔرِتھ۔\n11.\\tیُتھ لوٚنگُر یُس شفا اوس پطرس تہٕ یوحنا رٔٹِتھ، سٲری لُکھ ژٔلِتھ تِمن نِش یُس سُلیمان سُند ناو چُھ، سٮ۪ٹھاہ حٲران گٔیہِ۔\n12. تہٕ ییلہ پطرس وُچھ، تٔمۍ دِژ لُکن جواب، اے اسرائیلٕکۍ لوگ، کیازِ چُھہ اتھ پیٹھ حیران؟ نتہٕ کیازِ چھِو اسہِ کُن یُتھ سنجیدگی سان وچھان، زن پننہِ طاقتہٕ یا پاکیزگی سٍتۍ أسۍ یہِ انسان پکنہٕ خٲطرٕ بنٲومُت؟\n13. ابراہیم تہٕ اسحاق سُند خدا، تہٕ یعقوب سُند خدا، یُس سانین آباؤ اجدادن ہُند خدا، چُھ پننِس نیچوِس عیسیٰ سٕنز حمد کٔرمٕژ۔ یُس تۅہہ دِژ، تہٕ پیلاطس سٕندِس حٲضِرس منز کوٚرُکھ أمِس نِش انکار، ییلہ سُہ أمِس تراونُک عزم اوس کوٚرمُت۔\n14. مگر توے کٔر پاک تہٕ عادلس نِش انکار تہٕ اکھ قاتل یُس پانس دِنہٕ یُن یژھان۔\n15. تہٕ مٲرِن زندگی ہُند شہزادہ، یُس خداین مُردٕ منزٕ زندٕ کورمُت چھُ۔ یمیک اسۍ گواہ چھہِ۔ {پرنس: یا، مصنف}\n16. تہٕ تٔمۍ سٕندِس ناوس پیٹھ ایمان آسنہٕ سٍتـ̡ چُھ أمِس شخٕص مضبوٗط بناومُت، یُس تُہۍ وُچھان تہٕ زانان چھِو: آ، یُس ایمان أمِس سٍتـ̡ چُھہ تۅہہِ سارِنٕے ہٕندِس حضورس سٍتـ̡ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ یێلہِ سٍتـ̡ یێمہِ سٍت\n17.\\tتہٕ وۆن، بھائیو، بہٕ ووت زِ جہالت سٍتـ̡ تہِ کٔرِو تہٕ یِتھٕ پٲٹھۍ چُھہ تُہند حکمران تہِ۔\n18.\\tمگر تِم چیز یِم خداین برونٹھ پننین سارِنٕے پیغمبرن ہٕندِ زبانہِ سٍتـ̡ ہٲومٕتۍ، یێلہِ مسیح گژھہِ مصیبت دِنہٕ، تٔمۍ کٔر تِتھہ پٲٹھـ̡ پورٕ۔\n19. تێمہِ کِنۍ کٔرِو توبہٕ تہٕ بدلاوُن، یێلہِ گژھہِ تُہٕندِ گۅناہ ختم کرنہٕ، یێلہِ تازگی ہُند وقت ییہِ خداوند سٕندِ حٲضِری سٍتـ̡ یِنہٕ۔\n20. تہٕ سُہ سوزِ عیسیٰ مسیح، یُس امہِ برونہہ تہِ تۅہہِ نِش تبلیغ کرنہٕ آمُت اوس:\n21.\\tیُس اسمانس پۯاوُن یُس سارِنٕے چیزن ہٕنزِ بحالی ہٕندِس وقتس تام حٲصل سپدُن، یُس خدایہ دُنیا شروع سپدنہٕ پیٹھٕ پننین سارِنٕے مقدس پیغمبرن ہٕندِ زبانہِ سٍتـ̡ کتھ کرمژ چُھ۔\n22. تکیازِ موسیٰ ین اوس پزۍ پاٹھۍ مٲلن سٍتـ̡ ووٚنمُت، یێلہِ چُھہ تُہند خدا تُہٕندِس بٲے سٍتـ̡ تُہٕندِس خٲطرٕ تُلِتھ تہٕ یێلہِ سٍتـ̡ میانہِ پٲٹھۍ۔ سُہ چُھہ پرٮ۪تھ کُنہِ چیزس مَنٛز بوزُن یُس سُہ تۄہہِ وَننہٕ یِیہِ۔\n23.\\tتہ سپدِ یہ سپدُن، یُس نہ اتھ پیغمبرس بوزِ، سہ گژھہِ لوکن منز ختم سپدُن۔\n24. آ، تہٕ سموئیل سٕندِ سارِنٕے پیغمبرن تہٕ امہ پتہٕ یِنہٕ والیو تہٕ یِمو پَتہٕ یِمن دۅہن ہٕنز پیشن گویی کٔرمٕژ چھِ۔\n25. تُہۍ چھِو پیغمبرن ہٕندِ شُرۍ، تہٕ یُس خداین سانین آباؤ اجدادن سٍتـ̡ کورمُت چھُ، تہٕ تُہٕندِس نسلس مَنٛز گژھن زمینہِ ہٕندِس سارِنٕے رشتہٕ بابرکت سپدٕنـ̡ ۔\n26. گۅڈنچہ لٹہِ خداین دِژ پنُن نیچو عیسیٰ علیہ السلام زندٕ کٔرِتھ تہٕ سُہ سوزُن تۅہہِ سٍتـ̡ برکت دِنہٕ خٲطرٕ، تہٕ یێلہِ چُھہ پرٮ۪تھ أکِس پنہٕ نِس بدکاریو نِش پُھٹاونہٕ خٲطرٕ۔","1.\\tتہٕ یِمو لُکن سٍتـ̡ کتھ کٔرِتھ، پادٕرۍ تہٕ مندرُک سردار تہٕ صدوقین آو تِمن پیٹھ کتھ کرنہٕ، {کپتان: یا، حکمران}\n2. غمگسار گژھُن زِ تِمو ہیچھناوُن لُکن تہٕ عیسیٰ سٕندِ ذریعہٕ دِژ مُردٕ سٕندِ دُبارٕ دِنٕچ تبلیغ۔\n3.\\tتہٕ تِمو تھووُکھ تِمن پیٹھ اتھہٕ، تہٕ تھووُکھ دویمِس دۅہس تام رٔٹِتھ، تکیازِ وُنہِ اوس شام۔\n4.\\tیِمو منزٕ واریاہ یِمو یہِ لفظ بوزمُت اوس، تِمو کٔر پژھ۔ تہٕ نفرن ہُند تعداد اوس تقریباً پانژھ ساس۔\n5. تہٕ پَگہہ سپُد یہِ زِ تِہٕندِ حُکُمران تہٕ بُزرگ تہٕ کاتب\n6.\\tتہٕ ایناس اعلیٰ پادٕر، تہٕ قیافہ، تہٕ یوحنا تہٕ سکندر تہٕ یِم بٔڈۍ پادٕرۍ سٕندِ رشتہٕ دار ٲسۍ، یِمو یکوٹہ یروشلمس مَنٛز جمع گٔیہِ۔\n7.\\tتہٕ ییلہ تِمو یِم درمِیان تھٲوِتھ، تِمو پرژھن، کمہِ طاقتہٕ سٍتـ̡ یا کمہِ ناوٕ سٍتـ̡ چُھہ یہِ کورمُت؟\n8. پطرس روٝحہِ پاک سٍتـ̡ بٔرِتھ وۆنُن تِمن وۆن، اے لوکن ہٕندِس حکمرانو تہٕ اسرٲیلٕکۍ بزرگو،\n9.\\tاگر اسہِ از دۅہہ نامرد انسانس سٍتۍ کرنہٕ آمٕژ نیک کٲم ہُند پرکھہٕ ییہِ، سُہ کمہِ ذریعہٕ چُھ سُہ مکمل سپدان۔\n10. تۅہہ سارِنٕے تہٕ سارِنٕے اسرٲیلِکۍ لُکھ گژھہِ یہ زان زِ عیسیٰ مسیح ناصری سٕندِ ناوٕ سٍتـ̡ یُس یُس تۅہہ مصلوب کٔرِو، یُس خداین مُردٕ پى۪ٹھہٕ زندٕ کورمُت چُھ، {حتیٰ کہ} چُھہ یہِ انسان یێلہِ تہِ تُہٕندِس برونہہ کُن کھڑا چُھ۔\n11.\\tیہ چھہ سہ کنہِ یُس نہ تم معمارن پیٹھ تھوومت اوس، یُس کونہِ ہند سر بنیوو۔\n12. کُنہِ بییِس مَنٛز چُھہ نجات تہٕ یێمہِ سٍتـ̡ چُھہ نہٕ بێیہِ ناو دِنہٕ آمُت، یێمہِ سٍتـ̡ أسـ̡ نجات دِنہٕ یِنـ̡ ۔\n13.\\tوۅنۍ ییلہ تِمو پطرس تہٕ یوحنا سٕنز دِلیری وُچھِتھ تہٕ یہ وُچھِتھ زِ تِم چھِ ناعلم تہٕ جٲہل انسان، تِمو گٔیہِ حٲران۔ تہٕ تِمو ہیوٚت تِمن ہُند علم زِ تِم ٲسۍ عیسیٰ ہس سٍتـ̡ ٲسمٕتۍ۔\n14.\\tتہٕ یُس انسان یُس تِمن سٍتـ̡ کھڑا اوس، وُچھِتھ ہیوٚک نہٕ تِمو اتھ خلاف کینہہ ؤنِتھ۔\n15.\\tمگر ییلہ تِمو تِمن مجلسہٕ منزٕ نیرنُک حُکُم دِیُت، تِمو کٔر پانہٕ أکِس سٍتـ̡ کتھ باتھ،\n16.\\tیہ ونِتھ زِ أسۍ کیا کرو یمن نفرن سٍتۍ؟ یێمہِ سٍتـ̡ چُھہ یِمو سٍتـ̡ یِمن سارِنٕے سٍتـ̡ یِمن ہٕندِس سٍتـ̡ ظٲہر سپدمُت چُھ، یێلہِ چُھہ یِمن سارِنٕے سٍتـ̡ ظٲہر سپدمُ تہٕ أسۍ ہیکو نہٕ انکار کٔرِتھ۔\n17.\\tمگر یہ زِ یہ گژھہِ نہ عوامس منز مزید پھہلِتھ، اسہِ کرو تمن سختی سان دھمکی زِ تم گژھہِ نہ امہ ناوس پیٹھ کٲنسہ تہِ انسانس سیتۍ کتھ کرنہ۔\n18.\\tتہٕ تِمو بُلٲوِتھ تہٕ دِتُکھ حُکُم زِ تِم کٔرِن نہٕ عیسیٰ سٕندِ ناوٕ سٍتـ̡ کتھ کرنہٕ تہٕ ہیچھناوٕنـ̡ ۔\n19. مگر پطرس تہٕ یوحنا دیُت جواب تہٕ وونُن تِمن زِ کیا خدایہِ سٕندِ نظرِ منز چُھہ خدایہِ سٕندِ کھۅتہٕ زیادٕ تۅہہِ سٕنز کتھ بوزُن صحیح۔\n20. تکیازِ أسۍ ہیکو نہٕ تِم کتھ کٔرِتھ یِم أسۍ وُچھمٕتۍ تہٕ بوزمٕتۍ چھِ۔\n21.\\tتێلہِ ییلہ تِمو بییہ تہِ دھمکی دِژ، تِمو ترٲو نہٕ تِمن کِتھہ پٲٹھۍ، لوکن ہٕندِ وجہ سٍتـ̡ یێلہِ سارِنٕے انسانو خدایہِ سُند حمد کٔرِتھ یُس کرنہٕ آمُت اوس۔\n22.\\tتکیازِ أمِس شخٕص اوس ژتٲجی ؤری کھۄتہٕ زیادٕ وٲنسہِ، یٔمِس پیٹھ شفا ہُند یہ معجزہ ہاونہٕ آو۔\n23.\\tتہٕ یلہٕ تراونہٕ پتہٕ گٔیہِ تِم پننِس صحبتس کُن، تہٕ دِتُکھ سُہ سُہ سُہ خبر یُس بٔڈۍ پادٕرۍ تہٕ بزرگو تِمن ووٚنمُت اوس۔\n24. تہٕ ییلہ تمو یہ بوٗز، تِمو تُل اَکہٕ وِزِ خدایہ سٍتـ̡ پنٕنۍ آواز تہٕ وونُن، خداوند، تُہۍ چُھہ خدا، یٔمۍ آسمان، زمین، سمندر، تہٕ تِمن مَنٛز موجود سورُے بنوومُت چُھ:\n25.\\tکُس چُھہ پننہِ خادم داؤد سٕندِ زبانہِ سٍتـ̡ وونُن، کافر کیازِ گۆو غصہٕ تہٕ لوکھ بیکار چیزن ہُند تصور۔\n26.\\tزمینہِ ہٕندِس بادشاہس ووٚتھ، تہٕ حُکُمران گٔیہِ خداوند سٕندِس خٕلافس تہٕ تٔمۍ سٕندِس مسیحس خٕلاف۔\n27. تُہٕندِس مقدس شُرِس عیسیٰ سٕندِس خٕلافس سٍتـ̡ یُس ژے مسح کورمُت چُھ، ہیرودیس تہٕ پونٹیئس پیلاطس دۅشوے گٔیہِ غیر قومن تہٕ اسرٲیلِک لوکن سٍتـ̡ یکجا جمع کرنہٕ۔\n28.\\tیُس تہِ پننہِ اتھہٕ تہٕ تُہٕندِس مشورس برونہہ طے کرُن آسہِ۔\n29. تہٕ وۅنۍ خداوند، تِہٕنزِ دھمکی وُچھِو، تہٕ پَنٕنٮ۪ن خادمن دِیُن دِیُن، یُتھ تِم تُہٕندِس کلامَس سٍتـ̡ کتھ کٔرِتھ،\n30.\\tپَنُن اَتھٕ پٔھلٲوِتھ کٔرِو شفا دِنہٕ خٲطرٕ؛ تہٕ یُس تُہٕندِس پاک شُرِ عیسیٰ سٕندِ ناوٕ سٍتـ̡ گژھن نشانہٕ تہٕ عجائبات کرنہٕ یِن۔\n31.\\tتہٕ ییلہ تِمو دعا کٔر، سُہ جاے آو ہلاونہٕ ییتہِ تِم اَکہٕ وٹہٕ جمع گٔیہِ۔ تہٕ تِم ٲسۍ سٲری روح القدس سٍتـ̡ بٔرِتھ، تہٕ تِمو کٔر خدایہِ سُند کلام دِلیری سان بولان۔\n32.\\tتہٕ یِمن ہٕندِس عقیدس سٍتـ̡ اوس اَکہِ دِلُک تہٕ اَکہِ روحُک تہٕ تِمو منزٕ اوس نہٕ کانہہ تہِ وَنُن یُس أمِس نِش آسہِ۔ مگر یمن منز ٲسۍ سٲری چیز مشترکہ۔\n33. تہٕ دِژ رسولن خداوند عیسیٰ سٕندِ قیامتٕچ گوٲہی دِنہٕ سٍتـ̡ تہٕ یِمن سارِنٕے پى۪ٹھہٕ پى۪ٹھ۔\n34.\\tیِمن منز اوس نہٕ کانہہ تہِ کٔمی: تکیازِ یوتاہ زمینن یا مکانن ہٕندِس مٲلکَس ٲسۍ یِم کٕننہٕ آمٕتۍ ٲسۍ، تہٕ کٕننہٕ آمٕتۍ چیزن ہٕندِ قٕمتھ أنِتھ،\n35.\\tتہٕ تھووُن رسولن ہٕندِس قدمن پیٹھ، تہٕ پرٮ۪تھ أکِس شخصس مُطٲبق آو تٔمِس ضرورت مُطٲبق بٲگراونہٕ۔\n36. تہٕ یوسس، یُس رسولن ہٕندِ طرفہٕ برنباس ناو اوس دِنہٕ آمُت، (یُس تشریح کرنہٕ آمُت چُھ، تسلی ہُند نیٚچُو،) قبرص کِس ملکُک اکھ لاوی، {تہٕ}۔\n37.\\tزمین ہیتھ کٕنُن تہٕ پٲنسہٕ أنِتھ تہٕ تھووُن رسولن ہٕندِس قدمن پیٹھ۔","1.\\tمگر اَننیاس ناوٕکۍ أکِس شخٕصَس کُن سفیرا سٕنزِ خانٛدارِنہِ سٍتـ̡ کُن اکھ چیز،\n2.\\tتہٕ تھووُن قٲمتُک {حصہ}، تہٕ تٔمۍ سٕنزِ زنانہِ تہِ ٲس اتھ سٍتـ̡ خفیہ تہٕ تھووُن اکھ خاص حصہٕ، تہٕ تھووُن رسولن ہٕندِس قدمن پیٹھ۔\n3.\\tمگر پطرس ووٚن انانیاس، شیطانن کیازِ چُھ تُہند دِل روٝحہِ پاک سٕندِس سٍتـ̡ اپُز تھاونہٕ خٲطرٕ تہٕ زمینہِ ہٕندِس قٲمتُک حِصہٕ تھونہٕ خٲطرٕ بٔرِتھ دِژمُت؟ {اپُز کرُن: یا، دھوکہٕ دِنہٕ خٲطرٕ}\n4.\\tییلہ یہ باقی اوس، کیا یہ اوسا نہ تۅہہِ پنُن؟ تہٕ یہ کٕننہٕ پتہٕ، کیا یہ اوس نہٕ تۅہہِ ہٕندِس اختیارس منز؟ ژے کیازِ کور یہ کتھ پننِس دلس منز؟ ژے چُھہ نہٕ انسانن سٍتـ̡ اپُز کٔرمُت، بٔلکہِ خدایہِ سٍتـ̡ ۔\n5.\\tتہٕ انانیاس یِم لفظ بوٗزِتھ پیوٚو تہٕ ترووُن بھوت، تہٕ یِمن سارِنٕے یِمن کتھہٕ بوزنہٕ والٮ۪ن سارِنٕے سٍتـ̡ سٮ۪ٹھاہ خوف۔\n6.\\tتہٕ جوان ووٚتھ، أمِس زخم کٔرِتھ نِتھ دفن کٔرِتھ۔\n7. تہٕ یہ اوس تریہ گھنٹہٕ پتہٕ ییلہ تٔمۍ سٕنزِ خانٛدارِنہِ، یہ ٲس نہٕ خبرے زِ کیا آو کرنہٕ، آیہ۔\n8.\\tتہٕ پطرس دیُت أمِس جواب، مے وَنُن زِ ژے کٕنِہ زمین ییتِس مَنٛز کٕننہٕ؟ تہٕ تٔمۍ ووٚن، آ، واریاہ زیادٕ۔\n9. پطرس ووٚن أمِس زِ کِتھہٕ کٔنۍ چُھہ ژیہ خداوند سٕندِس روحس آزماونہٕ خٲطرٕ رٔلِتھ رضامندی ظاہر کٔرمٕژ۔ وچھ تِمن ہٕندِس قدمس یِمو تُہند خاوند دفن کٔرِتھ چُھہ دروازس پیٹھ، تہٕ نِن ژے نٮ۪بر۔\n10.\\tپَتہٕ پیوٚو سُہ سیوٚد أمۍ سٕندِس قدمن نِش، تہٕ دِژٕن بھوت: تہٕ جوان آیہِ اَژٕن، تہٕ وُچھن أمِس موٗدمُت، تہٕ تٔمۍ سٕندِس خاوندس دفن کٔرِتھ۔\n11.\\tتہٕ سارِنٕے کلیساہَس پى۪ٹھ، تہٕ یِمن ہٕندِس سٍتـ̡ یِم کتھ بوزان ٲسۍ۔\n12. تہٕ رسولن ہٕندِ اتھہٕ سٍتـ̡ گٔیہِ لُکن مَنٛز واریاہ نشانہٕ تہٕ عجائب سپدان۔ (تہٕ یم سٲری ٲسۍ سلیمان سٕندِس برآمدس منز اکۍ سے معاہدس سٍتۍ۔\n13.\\tباقین منز ہیوٚک نہ کانہہ تہِ انسان تمن سیتۍ رٔلتھ مگر لوکو کٔر تمن بڑاونہ۔\n14. تہٕ ایماندار گٔیہِ خداوند سٕندِس سٍتـ̡ زیادٕ شٲمِل، مرد تہٕ زنانہٕ دۄشوٕنی ہٕندِس تعدادس سٍتـ̡ ۔\n15.\\tیُتھ زِ تِمو کٔرِکھ بیمارن سڑکن منز، تہٕ بسترن تہٕ صوفن پیٹھ تھووُن، یُتھ کم از کم پطرس سُند ژھایہ یِمن منز کینژن ہُند سایہ آسہِ۔ {into...: یا، پرتھ سڑکہِ منز}\n16.\\tیِمن ہٕندِس اندۍ پٔکھۍ بٔڈۍ شہرن ہٕندِس بٔڈِس سٍتـ̡ تہٕ یِم ناپاک روحن سٍتـ̡ پریشان گٔیہِ، تہٕ تِم گٔیہِ سارِوٕے أکِس شفا ۔\n17.\\tاَمہِ پَتہٕ ووٚتھ بٔڈۍ پادٕرۍ تہٕ تِم سٲری یِم أمِس سٍتـ̡ ٲسۍ، (یُس صدوقین ہُند فرقہٕ چُھ،) تہٕ گٔیہٕ شرارت سٍتـ̡ بٔرِتھ، {غصہٕ: یا، حسد}\n18.\\tتہٕ تھووُکھ رسولن پیٹھ اتھہٕ، تہٕ تھووُکھ عام جیلس مَنٛز۔\n19.\\tمگر خداوند سٕندِ فرشتن کھولۍ رٲژ قٲدٕکۍ دروازٕ، تہٕ أنِن تِم نیبر، تہٕ وونُن،\n20. گژھِو، کھڑا گژھِو تہٕ مندرس مَنٛز کٔرِو لُکن سٍتـ̡ یَتھ زِنٛدٕگی ہٕندِس سارِنٕے کلامَس سٍتـ̡ کتھ کرنہٕ۔\n21.\\tتہٕ ییلہ تِمو بوٗزِ، تِمو ژاو صُبحس مندرس مَنٛز، تہٕ ہیچھناوُن۔ مگر اعلیٰ پادٕرۍ آو تہٕ تِم یِم أمِس سٍتـ̡ ٲسۍ، تہٕ بُلووُکھ مجلسہٕ تہٕ بنی اسرٲیلِچ سارِنٕے سٮ۪نیٹ، تہٕ سوزُکھ تِم اننہٕ خٲطرٕ قٲد خانس منٛز۔\n22.\\tمگر ییلہ افسر آیہ، تہٕ تِم آو نہٕ جیلس مَنٛز، تِم آیہ واپس تہٕ وونُن،\n23.\\tیہ ونِتھ زِ قٲد خانہٕ وُچھ پزۍ پٲٹھۍ أسۍ پوٗرٕ محفوٗظ سٍتۍ بند تہٕ رٲچھ دار ٲسۍ دروازس برونہہ کنہِ کھڑا مگر ییلہ أسۍ کھولۍ، اسہِ لوٚب نہٕ کانہہ نفر اندر۔\n24.\\tوۅنۍ ییلہ اعلیٰ پادٕرۍ تہٕ مندرٕکۍ کپتان تہٕ سردار پادٕرین یِم کتھ بوز، تِمو گوو تمن پیٹھ شک زِ یہِ کتھ کُن بٔڈِ۔\n25.\\tاَمہ پتہٕ آو اَکھ تہٕ وونُن تِمن وونُن، وُچھِو یِم نفر یِم قٲد کٔرِتھ چھِو، تِم چھِ مندرس مَنٛز کھڑا تہٕ لُکن ہیچھناوان چھِ۔\n26.\\tپتہٕ گوٚو کپتان افسرَن سٍتۍ، تہٕ أنِن تِم بغٲر تشددٕ ورٲے تہٕ تِم ٲسۍ لوٗکَن کھوژان، تِم ٲسۍ لُکن کھوژان، نتہٕ یِمن کٔنہِ کَنہِ کَنہِ لگاونہٕ یِنہٕ۔\n27.\\tتہٕ ییلہ تِم أنِتھ، تِمو کٔر مجلسس برونہہ کُن، تہٕ اعلیٰ پادٕرین پرژھن،\n28.\\tیہ ونِتھ زِ اسہِ اوسُکھ نہٕ سختی سان حُکُم دِژمُت زِ ژے پزِ نہٕ یَتھ ناوٕ سٍتـ̡ پرناوُن؟ تہٕ وُچھو، تہٕ ژے چُھکھ یروشلم پنٕنِس نظریہٕ سٍتـ̡ بٔرِتھ، تہٕ چُھکھ أمِس شخصہٕ سُند خوُن اسہِ پیٹھ اننُک ارادٕ تھاوان۔\n29. پطرس تہٕ باقٕے رسولن دِژ جواب تہٕ وونُن، اسہِ پزِ انسانو بجایہ خدایہِ سٕنز اطاعت کرٕنۍ۔\n30.\\tسانین آباؤ اجدادن ہندِ خداین کٔر عیسیٰ مسیح زندٕ، یُس تۅہہ مارِتھ کُلِس پیٹھ پھانسی دِژمُت۔\n31. خدا چُھ پَنٕنِس دٔچِھنہِ اتھہٕ سٍتـ̡ شہزادٕ تہٕ نجات دِنہٕ وول بٔنِتھ، یێلہِ سٍتـ̡ اسرٲیلِس توبہ تہٕ گۅنہن ہٕنز معافی دِنہٕ خٲطرٕ۔\n32. تہٕ أسۍ چھِ یِمن چیزن ہٕندِ گواہ ۔ تہٕ {یِتھے پٲٹھۍ} روح القدس تہِ، یُس خداین تمن دِژمُت چُھ یُس أمس اطاعت کران چُھ۔\n33.\\tییلہ تِمو بوٗزِ، تِم ژٔٹِتھ ژٔٹِتھ دِل دِنہٕ، تہٕ کٔرٕکھ تِمن مارنُک مشورٕ۔\n34.\\tاَمہِ پَتہٕ وُچھُن مجلسس مَنٛز اَکھ فریسی، یُس جمالیل ناو اوس، یُس شریعت ہُند ڈاکٹر اوس، سارِنٕے لُکن مَنٛز شہرت حٲصِل کٔرِتھ، تہٕ دِتُن حُکُم زِ رسولن ہٕندِ خٲطرٕ تھوڑا جاے تھاوُن۔\n35.\\tتہٕ وونُن تِمَن زِ اے اسرٲیلِیو لوگو، یِمن نفرن ہٕندِس سٍتـ̡ کیا چُھہ یِمن ہٕندِس سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ تہٕ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ یێ\n36.\\tتکیازِ یمن دۅہن برونہہ ووت تھیوڈس پانس کانہہ آسنک فخر کران۔ یمن سٍتۍ واریاہ نفر، تقریباً ژور ہتھ، پانس سٍتۍ رٔلۍ: یُس مارنہٕ آو۔ تہٕ سارِنٕے یِمو أمِس فرمانبردار کٔرۍ، گٔیہٕ منتشر تہٕ گٔیہٕ ختم کرنہٕ۔ {اطاعت کٔرِتھ: یا، پژھہٕ}\n37.\\tأمِس شخٕص سٍتـ̡ گیلیلُک یہوداہ وُتھ، تہٕ أمِس پَتہٕ کٔرِن واریاہ لُکھ پانس پٲٹھۍ، سُہ تہِ موٗد ۔ تہٕ سٲری گٔیہٕ منتشر کرنہٕ۔ {اطاعت کٔرِتھ: یا، پژھہٕ}\n38. تہٕ وۅنۍ چُھس بہٕ ژے ونان، یِمن نفرن نِش گژھ پرہیز تہٕ تِمن تراوُن، تکیازِ یێلہِ یہِ مشورٕ یا یہِ کٲم انسانن ہٕنز آسہِ، تیلہِ گژھہِ یہِ ناکام:\n39. مگر اگر یہ خدایہ سُند آسہِ، تیلہِ ہیکو نہٕ یہ ختم کٔرِتھ۔ یێلہِ گژھہِ تۅہہِ خدایس سٍتـ̡ لڑنہٕ خٲطرٕ تہِ لبنہٕ۔\n40. تہٕ تِمو کٔر أمِس سٍتـ̡ رضامندی تہٕ ییلہ تِمو رسولن بُلٲوِتھ تہٕ مار دِژٕن، تِمو دِژ حُکُم زِ تِم گژھن نہٕ عیسیٰ سٕندِ ناوٕ سٍتـ̡ کتھ کرنہٕ، تہٕ یِمن گژھن یێلہِ گژھن یێلہِ۔\n41.\\tتہٕ تِم گٔیہِ مجلسہٕ نِشہِ نِش خۅش گٔژھِتھ زِ تِم گٔیہِ تٔمۍ سٕندِ ناوٕ خٲطرٕ شرمندگی ہٕندِس لایق ماننہٕ۔\n42. تہٕ روزانہٕ چُھہ مندرس مَنٛز، تہٕ پرٮ۪تھ گرس مَنٛز، تِمو کٔر نہٕ عیسیٰ مسیحس ہیچھناوٕنـ̡ تہٕ تبلیغ کرنہٕ نِش بند۔","1.\\tتہٕ تِمن دۅہن ییلہ شاگردن ہُند تعداد ہُرراوُن، یۆنانین ہٕندِ طرفہٕ گٔیہِ عبرانین خلاف بڑبڑاوُن، تکیازِ تِہٕنزِ بیواہ ٲس روز مرہ کِس مَنٛز نظر انداز کرنہٕ آمٕژ۔\n2.\\tاَمہِ پَتہٕ بُلوو بہو شٲگِرَن ہٕندِس تعدادس {تِمن کُن}، تہٕ وونُن، یہِ چُھنہٕ کانہہ وجہ زِ أسۍ پزِ خدایہِ سُند کلام تراوُن، تہٕ میزن ہٕنز خدمت کرٕنۍ۔\n3. اَمہِ مۄکھہٕ وُچھِو تُہۍ پانس مَنٛز سَتھ ایماندار شخص، یِم روح القدس تہٕ حکمت سٍتـ̡ بٔرِتھ چھِ، یِمن أسۍ اتھ کاربارس پیٹھ مقرر کٔرِتھ۔\n4. مگر أسۍ کرو پنُن پان دُعا تہٕ کلام سٕنزِ خدمتہٕ خٲطرٕ مُسلسل۔\n5.\\tتہٕ یِمو چُھ سٲرۍسٕے لُکھ خوش گومُت، تہٕ تِمو چُھ سٹیفن یُس ایمانہٕ سٍتـ̡ تہٕ روح القدس سٍتـ̡ بٔرِتھ شخٕص چُھ، تہٕ فلپ، تہٕ پروکورس، تہٕ نِکنور، تہٕ تیمون، تہٕ پارمیناس، تہٕ نِکولس چُھہ انطاکیہ ہُند تبلیغ کَرُن:\n6.\\tیُس تِمو رسولن برونہہ کُن تھوو، تہٕ ییلہ تِمو دعا کٔر، تِمو تھووُن تِمن پیٹھ اتھہٕ۔\n7. تہٕ خدایہِ سُند کلام ہُریر۔ تہٕ یروشلمس مَنٛز گٔیہِ شاگردن ہُند تعداد واریاہ زیادٕ۔ تہٕ پادٕرین ہٕنٛز اکھ بٔڑ کمپنی ٲس عقیدٕچ فرمانبردار۔\n8. تہٕ سٹیفنن کٔر ایمان تہٕ طاقتہٕ سٍتـ̡ بٔرِتھ لُکن مَنٛز بٔڈۍ عجائب تہٕ معجزات۔\n9.\\tامہ پتہ سپد یہودی عبادت خانس متعلق کینہہ یتھ لبرٹائنز، سائرینین تہ اسکندریہ تہ یمن منز سیلیشیا تہ ایشیاہک تہ سٹیفنس سیتۍ اختلاف کران چھہِ۔\n10.\\tتہٕ تِم ہیوٚک نہٕ تٔمِس حکمتس تہٕ روحس خلاف مزاحمت کٔرِتھ۔\n11.\\tتێلہِ کٔر تِمو انسانس سٍتـ̡ یُس ونان، اسہِ چُھہ سُہ موسىٰ سٕندِس خلاف تہٕ خدایس خلاف توہین آمیز کتھ بوزمُت۔\n12.\\tتہٕ تِمو کٔرِکھ لُکن تہٕ بزرگن تہٕ کاتب ہٕندِس نِش تہٕ آیِکھ أمِس نِش تہٕ رٔٹِتھ تہٕ أنِکھ سُہ مجلسس مَنٛز۔\n13.\\tتہٕ کٔرِن اپُز گواہ قٲیِم، یِم ونان چھِ، یہِ شخٕص چُھنہٕ اتھ مُقدس جایہِ تہٕ شریعتس خلاف توہین آمیز الفاظ بولنہٕ بند کٔرِتھ:\n14.\\tکیازِ اسہِ چُھ سُہ یہ ونن بوزمُت زِ یہِ عیسیٰ مسیح کرِ یێمہِ جایہ تباہ تہٕ بدلاوِ تِم رسم یُس موسىٰ سٕندِ دِژ اسہِ دِژمٕژ۔ {رسم و رواج: یا، رسم}\n15.\\tتہٕ مجلسس منز بِہتھ سارِوٕے یُس أمِس کُن نظر دِوان اوس، تٔمۍ وُچھ تٔمۍ سُند بُتھ یُس أکِس فرشتہٕ سُند بُتھ اوس۔","1.\\tاَمہ پتہٕ ووٚن اعلیٰ پادٕرۍ، کیا یِم چیز چھَے یِتھ؟\n2. تہٕ تٔمۍ ووٚن، مردو، بٲے تہٕ باپ، بوزو۔ جلال ہُند خدا آو سٲنِس مٲلِس ابراہیمس نِش ظٲہر، ییلہ سُہ میسوپوٹیمیاہس مَنٛز اوس، چارنس مَنٛز روزنہٕ برونہہ،\n3.\\tتہٕ ووٚنُن أمِس زِ ژٕ نیٚبر پَنٕنہِ مُلکہٕ نِش تہٕ پنٕنِس رِشتہٕ دارس نِش تہٕ اَتھ زمینس مَنٛز یُس بہٕ ژےٚ ہٲوِ۔\n4.\\tتمہ پتہ آو سُہ چالڈین ہٕندِ سرزمینہٕ منزٕ نیبر تہٕ چارنس مَنٛز روزُن، تہٕ تتہِ ییلہ تٔمۍ سُند مول موٗد، تٔمۍ کٔر سُہ اتھ زمینس مَنٛز، یَتھ مَنٛز تُہۍ وُنۍ روزان چھِو۔\n5.\\tتہٕ تٔمۍ دِژ نہٕ اتھ منز کانہہ وراثت، نہ، تیوٗت نہٕ یوتاہ زِ تٔمِس دِیہِ أمِس أکِس ملکیت خٲطرٕ، تہٕ أمِس پتہٕ دِیہِ تٔمِس نِش کانہہ شُر۔\n6.\\tتہٕ خداین کٔر اَتھ دانشمندی سٍتـ̡ کتھ زِ تٔمۍ سُند بُل گژھہِ أکِس اجنبی زمینس مَنٛز روزُن۔ تہٕ یہ زِ تم گژھن تمن غلامی منٛز انن، تہٕ ژور ہتھ ؤری بدی ہٕنٛز التجا کرنہٕ۔\n7. تہٕ یٔمِس قومس خٲطرٕ تِم غلامی آسہِ، بہٕ کَرٕ بہٕ فٲصلہٕ، تہٕ اَمہِ پتہٕ یِن تِم یَتھ جایہِ میانہِ خدمت کرنہٕ۔\n8. تہٕ تٔمِس دِیُت ختنہٕ کرنُک عہد تہٕ یِتھٕ پٲٹھۍ دِیُت ابراہیمن اسحاق تہٕ ٲٹھمہِ دۅہہٕ کوٚرُن أمِس ختنہٕ۔ تہٕ اسحاق {پیدٕ} یعقوب۔ تہٕ یعقوب {پیدائش} کٔر بہن سرپرستن ہٕندِ۔\n9.\\tتہٕ حسد کٔرِتھ کُن یوسف مصرس منز، مگر خدا اوس تس سٍتۍ،\n10.\\tتہٕ دِژُن أمِس سارِوٕے مُصیبتَو نِش نجات تہٕ دِتُن أمِس مصرُک بادشاہ فرعون سٕندِس نظرس منز عنایت تہٕ حکمت۔ تہٕ بنوو سُہ مصرس تہٕ پننِس سارِنٕے گھرس پیٹھ گورنر۔\n11.\\tوۅنۍ آو سارِنٕے مصرٕچ تہٕ چنانٕچ زمینہٕ تہٕ سٮ۪ٹھاہ مصیبت، تہٕ سانین مٲلن مِلیو نہٕ کانہہ رزق۔\n12.\\tمگر یعقوبن ییلہ بوز زِ مصرس منز چُھ مکایہ، تٔمۍ سوٗزۍ سٲنـ̡ مٲلۍ سٍتـ̡ گۅڈٕ نیبر۔\n13. تہٕ دۆیمہِ لٹہِ آو یوسف پننین باین ہُند زان دِنہٕ۔ تہٕ یوسف سٕندِ رشتہٕ دار آو فرعونس سٍتـ̡ زاننہٕ۔\n14.\\tپَتہٕ سوٗزُن یوسف تہٕ بُلووُن پنُن مول یعقوب تہٕ تٔمۍ سٕندِس سارِنٕے رِشتہٕ دار، تریہ تہٕ پنٛداہ روح۔\n15.\\tیێلہِ یعقوب ووت مصرس مَنٛز، تہٕ سُہ تہٕ سٲنـ̡ باو،\n16.\\tتہٕ آیہ سیکیمس مَنٛز نِنہٕ، تہٕ تتھ قبرس مَنٛز تھاونہٕ یُس ابراہیم سٕندِس نیچوین ہٕندِس پٲنسہٕ سٍتـ̡ ہیوٚتمُت۔\n17. مگر ییلہ وعدُک وق نزدیک ووت، یُس خداین ابراہیمس سٍتـ̡ حلف اوس کورمُت، لوکھ گٔیہِ مصرس مَنٛز بٔڈِتھ تہٕ بٔڈِتھ بٔڈِتھ ۔\n18.\\tیوتام بیاکھ بادشاہ ووتھ، یُس نہٕ یوسف سٍتـ̡ زانان اوس۔\n19.\\tیۅہے کٔر سانین رشتہ دارن سٍتـ̡ تہٕ بد کار کٔر سانین مٲلن سٍتـ̡ ، یُتھ زن تِم پننین لۄکٹٮ۪ن شُرٮ۪ن کٔڈِتھ کٔرِتھ زِندٕ روزِ۔\n20. یتھ وقتس مَنٛز اوس موسیٰ زامُت، تہٕ سُہ اوس سٮ۪ٹھاہ گور، تہٕ پننِس مٲلہِ سٕندِس گَرَس مَنٛز تریہ ریتن رٔٹِتھ روزُن: {زیادٕ منصفانہٕ: یا، خدایہ سٕندِس سٍتـ̡ منصفانہ}\n21. تہٕ ییلہ سُہ کڑنہٕ آو ، فرعون سٕنزِ کورِ نِش نِش تہٕ دِژن أمِس پننِس نیچوِس خٲطرٕ پرورش ۔\n22. تہٕ موسیٰ اوس مصرین ہٕنزِ سارِنٕے حکمتَس مَنٛز زانان تہٕ سُہ اوس کلامَس تہٕ عملس مَنٛز طاقتور ۔\n23. تہٕ ییلہ سُہ ژتٲجی وُہُر اوس، تٔمِس دِلس منز آو یہ زِ سُہ گژھہِ پننین باین اسرٲیلِس نِش گژھُن۔\n24.\\tتہٕ یِمو منزٕ أکِس سٍتـ̡ ظلم سپدان وُچھِتھ دِژ تٔمِس بچاو، تہٕ دِتُن أمِس مظلوم سُند انتقام، تہٕ دِتُن مصری سٍتـ̡ مار۔\n25.\\tتکیازِ تس اوس خیال زِ تٔمۍ سٕندِس بٲے آسہ سمجِتھ زِ خدا کِتھہ پٲٹھـ̡ کرِ تِمن ہٕندِس اتھہٕ سٍتـ̡ نجات دِنہٕ، مگر تِمو اوس نہٕ سمجھان۔ {کیازِ: یا، وُن}\n26.\\tتہٕ دوٚیمہِ دۅہہ ہٲو تِمن پانس سٍتـ̡ یێلہِ تِم کوشش کٔرِتھ، تہٕ وونُن زِ جناب، تُہۍ چھِو بٲے۔ تہۍ کیازِ چھِو اکھ أکِس سٍتۍ غلط کران؟\n27.\\tمگر یمۍ پننس ہمساین سٍتۍ ظلم کٔر، تمس کٔر یہ ؤنتھ زِ ژے کٔمۍ بنوو اسہِ پیٹھ حکمران تہٕ قاضی؟\n28.\\tژے کٔرِکھ میہ مارُن، یتھہ پاٹھۍ ژے راتھ مصری کورمُت؟\n29.\\tاَمہِ وِزِ ژوٚل موسیٰ سٍتـ̡ تہٕ سُہ اوس مَدیان کِس ملکس مَنٛز اَکھ اجنبی ، یَتھ مَنٛز أمِس زٕ نیٚچوِ زاے ۔\n30.\\tتہٕ ییلہ ژتٲجی ؤری گٔیہ، تس آو کُنہِ بیابانس مَنٛز کُنہِ\n31.\\tییلہ موسىٰ وُچھ یہِ وُچھِتھ حٲران تہٕ ییلہ سُہ نزدیک وُچھِتھ وُچھُن، خداوند سٕنز آواز آیہِ أمِس نِش،\n32. {ونان} چُھس بہٕ چُھس چُھس تہندِس مٲلن ہُند خدا، ابراہیم سُند خدا، تہٕ اسحاق سُند خدا، تہٕ یعقوب سُند خدا۔ اَمہ پتہٕ گوو موسیٰ تھرتھر، تہٕ ہیوٚت نہٕ وُچھنٕچ ہمت کٔرِتھ۔\n33.\\tاَمہِ پتہٕ ووٚن خداوند أمِس زِ پَنٕنہِ کھورِ نِش ترٛٲوِو پَنٕنہِ کھۄرٕ پَنٕنِس کھۄرَو نِش پَنٕنہِ کھۄرٕ پَنٕنِس کھۄرٕ نِش تہٕ یێلہِ یێلہِ تہٕ یێلہِ تہٕ یێلہِ\n34. مے چُھہ وُچھمُت، میہ چُھہ پننین لوکن ہُند مصیبت وُچھمُت یُس مصرس مَنٛز چُھ، تہٕ مے چُھس تِہُند کرٛٮ۪کہٕ بوزمُت، تہٕ بہٕ چُھس تِمن نجات دِنہٕ خٲطرٕ بۄن آمُت۔ تہٕ وۄنۍ آو بہٕ ژےٚ مصرس منٛز۔\n35.\\tیہ موسیٰ یس تمو انکار کٔرِتھ ونان زِ ژے کٔمۍ بنوو حکمران تہٕ قاضی؟ یتھے پاٹھۍ سوز خداین فرشتہ سٕندِ اتھہٕ سٍتـ̡ حکمران تہٕ نجات دِنہٕ وول یُس أمس کُنہِ\n36.\\tتٔمۍ کٔر تِم نیبر، تمہ پتہ کٔر تمٔۍ مصر کِس سرزمینس منز، بحرِ احمرس مَنٛز تہٕ بیابانن مَنٛز ژتٲجی ؤرین مَنٛز عجائبات تہٕ نشانہٕ۔\n37. یہِ چُھ سُہ موسیٰ، یٔمۍ بنی اِسرٲیلِس ووٚنمُت زِ خداوند تُہُند خدا کرِ تُہٕندِس بٲے سٍتـ̡ میانہِ پٲٹھـ̡ تُہٕندِس خٲطرٕ تُلِتھ ۔ سُہ چُھہ بوزُن۔ {یِتھٕ پٲٹھۍ...: یا، بطور پانے}\n38.\\tیہِ چُھہ سُہ یُس بیابانس مَنٛز کلیساہٕ مَنٛز اوس، یُس کُنہِ سینا کِس پہاڑس مَنٛز أمِس سٍتـ̡ کتھ کٔرِتھ، تہٕ سٲنـ̡ بابن سٍتـ̡ یُس اسہِ دِنہٕ خٲطرٕ زندٕ وُچھان اوس۔\n39.\\tیٔمِس سٍتـ̡ سانہِ باپ سٍتـ̡ اطاعت کٔرِتھ، بلکہ کٔرِکھ تِمن نِش دِنہٕ آمُت، تہٕ دِلَن مَنٛز گٔیہِ دُبارٕ مصرس مَنٛز،\n40.\\tہارونس وَنُن زِ اسہِ برونہہ کُن بَنٲوِو اسہِ دیوتا، یُس اسہِ برونہہ کُن نیرُن، کیازِ یێمہِ موسیٰ یُس اسہِ مصرٕچ سرزمینہٕ منزٕ نیبر کٔرِتھ، اسہِ ٲس نہٕ پتاہ زِ تس کیا بنیوو۔\n41.\\tتہٕ تِمو بنوو تِمن دۅہن بَچھرٕ تہٕ بُتَس خٲطرٕ قربانی تہٕ کٔرٕکھ پننین اتھن ہٕنزِ کامہِ سٍتـ̡ خۅش۔\n42. پَتہٕ دِیُت خدایہِ سٕندِس لشکرس سٍتـ̡ پٲٹھـ� یِتھ کٔنۍ زَن پیغمبرن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، اے اِسرٲیلؠ ہٕندِس بَرٕتؠ، کیا ژے ژتٲجی ؤرین ہٕندِس بیابانس مَنٛز مارنہٕ آمٕتۍ جانور تہٕ قربانی دِژمٕژ؟\n43. آ، ژے تُل مولوچُک خیمہ تہٕ پنٕنِس دیوتا ریمفان سُند ستارہٕ، یِم تِمن ہٕنز پوجا کرنہٕ خٲطرٕ بنٲومٕتۍ: تہٕ بہٕ نِیہٕ ژے بابل نیبر نِنہٕ۔\n44.\\tسانین مٲلن اوس بیابانس منز گواہ سُند خیمہ دِژمُت، یُس تٔمۍ موسیٰ ہس سٍتـ̡ کتھ کرِتھ مقرر کورمُت اوس زِ سُہ گژھہِ تٔمِس طرزس مُطٲبق بناوُن یُس تٔمۍ وُچھمُت اوس۔ {کتھ کران: یا، کُس کتھ کٔر}\n45.\\tیُس سانہِ باپ تہِ یُس حضرت عیسیٰ مسیحس سٍتـ̡ غیر قومن ہٕندِس قبضس مَنٛز اننہٕ آو، یِم خداین سانین مٲلن ہٕندِس بُتھِس برونہہ کُن دِژمٕتۍ، داؤد سٕندِس دۅہس تام۔ {یہِ...: یا، رٔٹِتھ}\n46.\\tیٔمِس خدایہِ سٕندِس خدایہِ سٕندِ خٲطرٕ خیمہ ژھانڈُن یژھان۔\n47. مگر سلیمانن بنوو تس اکھ مکانہٕ۔\n48. تاہم چُھ نہٕ اَتھٕ سٍتـ̡ بٔنِتھ مندرن مَنٛز روزان۔ یتھہ پاٹھۍ پیغمبرن ہند ونن چھہ\n49.\\tآسمانُک تخت تہٕ زمین چھُ میٲنۍ قدمن ہُند تخت: ژٕ کُس مکانہٕ بناوکھ مےٚ؟ خداوند چُھ ونان: یا میانہِ آرام کرنٕچ جاے کیا چِھ؟\n50.\\tیِم سارِنٕے چیٖز چھَنہٕ میانہِ اَتھٕ بنٲومٕتۍ؟\n51. یێلہِ چُھہ دِل تہٕ کنن مَنٛز سختی تہٕ ختنہ کٔرِتھ، تہٕ چُھہ ہمیشہٕ روح القدسٕچ مزاحمت کران: یِتھٕ پٲٹھـ̡ چُھہ تُہٕندِس مٲلِس {کٔر}، تِتھے پٲٹھـ̡ چُھہ تُہٕندِس آبس سٍتـ̡ {کرُن}۔\n52.\\tکُس پیغمبرن منز چھہ نہ تہند باپ۔ تہٕ تِمو چھِ تِم مارۍ مٲرۍمٕتۍ یِم عادل سٕندِ یِنہٕ برونہہ ہاونہٕ آمٕتۍ ٲسۍ۔ یمن منز تم وۅنۍ غدار تہٕ قاتل ٲسۍ:\n53.\\tیِمو شریعت فرشتن ہٕندِس طرزس سٍتـ̡ رٔٹمٕژ آسہِ، تہٕ یِمو چُھہ نہٕ رژھراونہٕ آمُت۔\n54.\\tییلہ یِمو یِم کتھ بوٗزِ، تِمو ژٔٹِتھ دِل ژٔٹِتھ تہٕ تِمو کٔرٕکھ أمِس دندٕ دِتھ۔\n55.\\tمگر سُہ روٝحہِ پاک سٍتـ̡ بٔرِتھ وُچھُن آسمانس کُن تہٕ وُچھُن خدایہِ سُند جلال تہٕ عیسیٰ مسیح سٕندِس دچھنہِ اتھس پیٹھ کھڑا ۔\n56.\\tتہٕ وۆنُن، وُچھمُت آسمانہٕ یلہٕ تہٕ انسان سُند فرزند چُھ خدایہ سٕندِس دچھنہِ اتھس پیٹھ کھڑا ۔\n57.\\tاَمہ پتہٕ کٔر تِمو بَڑِ آوازٕ سٍتـ̡ کٔرِتھ أمِس کُن دِژٕن،\n58.\\tتہٕ کٔرِن أمِس شہرٕ منزٕ کٔڈِتھ تہٕ کٔرِن کَنہِ کٔرِتھ تہٕ گواہو ترٛٲوِکھ أکِس جوان سٕندِس قدمن نِش پَنٕنہِ پَلَو یُس ساؤل ناو اوس۔\n59. تہٕ تِمو لگٲوۍ سٹیفنس کٔنہِ کٔرِتھ خدایہِ سٍتـ̡ بُلاونہٕ تہٕ وونُن، خداوند عیسیٰ مسیح، میون روح رٔٹِو۔\n60.\\tتہٕ سُہ ووٚتھ کۅٹھہٕ بٔنِتھ تہٕ وۆن بَڑِ آوازِ سٍتـ̡ وۆنُن، خداوند، یہِ گۅناہ تھاو نہٕ تِمن ہٕندِس اِلزامس پیٹھ۔ تہٕ ییلہ تٔمۍ یہ ووٚن، سُہ گوٚو شوٚنگتھ۔","1. تہٕ ساؤل اوس پننِس مرنس پیٹھ رضامندی دِوان۔ تہٕ تمہِ وِزِ اوس کلیساہس خلاف سٮ۪ٹھاہ ظلم و ستم سپدان یُس یروشلمس مَنٛز اوس۔ تہٕ تِم ٲسۍ رسولن ورٲے، یہوداہ تہٕ سامریہ کِس علاقس مَنٛز منتشر گٔمٕتۍ۔\n2. تہٕ عقیدت مند لوکو نِو سٹیفن تٔمۍ سٕندِس تدفینس تام، تہٕ کورُکھ أمِس پیٹھ سٮ۪ٹھاہ ماتم ۔\n3.\\tساؤل سُند تعلق چھُ، تٔمۍ کٔر کلیساہٕچ تباہی، پرٮ۪تھ گرس مَنٛز ژاو تہٕ مرد تہٕ زنانہٕ کٔرٕن جیلس مَنٛز دٲخل۔\n4. تێمہِ کِنۍ یِم یِم پرٮ۪تھ کُنہِ جایہِ بٔرِتھ گٔیہِ کلامٕچ تبلیغ کرنہٕ خٲطرٕ۔\n5. پَتہٕ ووت فلپ سامریہ شہرس مَنٛز، تہٕ تِمن کٔرٕن مسیح سٕنز تبلیغ۔\n6. تہٕ لوکو کٔر اَکہٕ وٹہٕ سٍتـ̡ تِمن چیزن ہُند دھیان یِم فلپس کٔر تِمن معجزاتن بوزان تہٕ وُچھِتھ یِم تٔمۍ کٔرۍ۔\n7.\\tناپاک روحن ہٕندِس سٍتـ̡ گٔیہِ بَڑِ آوازِ سٍتـ̡ وُنـ̡ دِنہٕ آمٕتـ̡ یِمن سٍتـ̡ دِنہٕ آمٕژ تہٕ یِمن ہٕندِس سٍتـ̡ گٔیہِ شفا دِنہٕ۔\n8. تہٕ اتھ شہرس منز ٲس واریاہ خوشی۔\n9.\\tمگر اَکھ شخٕص اوس، یُس شمعون ناو اوس، یُس امہِ برونہہ أتھۍ شہرس منز جادوگری کران اوس، تہٕ سامریہٕکۍ لُکن دیتُن تہٕ دِژُن زِ پانہٕ اوس کانہہ بٔڈ شخص۔\n10. یٔمِس سارِوٕے یِمو سارِوٕے توجہ دِژ، کم از کم پیٹھٕ بٔڈِس تام، یہِ انسان چُھ خدایہ سُند بٔڈ طاقت۔\n11.\\tتہٕ تِمن اوس تِمن ہُند احترام تکیازِ واریاہس کالس اوس تِمن جادوگری سٍتۍ جادو کٔرۍمٕتۍ۔\n12. مگر ییلہِ تِمو پژھ زِ فلپس سٕندِ خدایہِ سٕنزِ بادشٲہی تہٕ عیسیٰ مسیح سٕندِس ناوٕچ تبلیغ کٔرِتھ، تِمو کٔر مرد تہٕ زنانہٕ دۄشوٕے بپتسمہ۔\n13.\\tتێلہِ اوس شمعون پانہ تہِ یقین تھاوان: تہٕ ییلہ أمس بپتسمہ دِنہٕ آو، سُہ اوس فلپس سٍتـ̡ جٲری تہٕ معجزات تہٕ نشانہٕ وُچھِتھ حٲران گومُت۔ {معجزات...: Gr. نشانہٕ تہٕ عظیم معجزات}\n14. یێلہِ یێلہِ یروشلمس مَنٛز موجود رسولو بوٗز زِ سامریاہس چُھ خدایہِ سُند کلام حٲصل گومُت، تِمو سوٗزۍ تِمن نِش پطرس تہٕ یوحنا:\n15.\\tیِمو ییلہ تِم بۄن وٲتِتھ، تِمن ہٕندِ خٲطرٕ دُعا کٔرٕن، یُس تِمن ہُند روح القدس حٲصل کٔرِتھ:\n16. (تکیازِ وُنیُک تام اوس سُہ یِمو منزٕ کٲنسہ تہِ پۯاونہٕ آمُت: صرف آیہ تِمو خداوند عیسیٰ سٕندِ ناوٕ سٍتـ̡ بپتسمہ دِنہٕ۔)\n17. پَتہٕ تھوو تِمو تِمن پیٹھ اتھہٕ، تہٕ تِمو رٔٹِتھ روح القدس۔\n18.\\tتہٕ یێلہِ شمعون وُچھ زِ رسولن ہٕندِس اتھہٕ تھپھ کٔرِتھ چُھہ روح القدس دِنہٕ آمُت، تٔمۍ دِژ تِمن پٲنسہٕ،\n19. یہ ونِتھ زِ مے دِیُن یہ طاقت تہِ، یُس تہِ بہٕ اتھہٕ تراوُن، سُہ گژھہِ روح القدس حٲصل کرنہٕ۔\n20. مگر پطرس ووٚن أمِس زِ تُہند پونسہٕ چُھہ ژے سٍتـ̡ ختم گومُت، کیازِ ژے چُھہ سوچمُت زِ خدایہ سُند تحفہٕ ییہ پونسہٕ سٍتـ̡ ہینہٕ۔\n21.\\tاتھ معاملس منز چُھہ نہ تۅہہ کانہہ حصہ تہٕ نہ لاکھ، تکیازِ تُہند دِل چُھنہٕ خدایہ سٕندِس نظرس منز صحیح۔\n22. تێمہِ کِنۍ کٔرِو پننہِ بدکٲری نِش توبہٕ، تہٕ خدایہِ سٕنز دُعا کٔرِو دُعا، یێلہِ چانہِ دِلُک خیال ییہِ معاف۔\n23.\\tکیازِ بہٕ چُھس سمجھان زِ تہٕ چُھکھ تہٕ بدکاری ہٕندِس بندس منز۔\n24.\\tاَمہِ پتہٕ دیُت شمعون جواب تہٕ وونُن زِ میانہِ خٲطرٕ کٔرِو خداوند سٕندِ خٲطرٕ دُعا زِ یِمو منزٕ یِمو کُنہِ تہِ کتھ یِم ژے کٔرمٕژ چھِ۔\n25. تہٕ ییلہ تِمو گوٲہی دِژ تہٕ خداوند سٕندِ کلامٕچ تبلیغ کٔر، یِمو گٔیہِ یروشلم واپس تہٕ کٔرٕکھ سامری سٕندٮ۪ن واریاہن گامن مَنٛز انجیل ہٕنز تبلیغ۔\n26.\\tتہٕ خداوند سٕندِ فرشتن ووٚن فلپس سٍتـ̡ وۆنُن زِ وۅتھٕ وُن تہٕ گژھ جنوبس کُن یُس یروشلم پیٹھہٕ غزہ تام واتان چُھ، یُس صحرا چُھ۔\n27. تہٕ سُہ ووٚتھ تہٕ ووت تہٕ وُچھ، ایتھوپیاہُک اکھ شخص، یُس ایتھوپیاہٕچ ملکہ کینڈیس سٕندِس تحت اکھ بٔڈ اختیار تھاون وول اوس، یٔمِس سٲرۍسٕے خزانُک ذمہٕ دار اوس، تہٕ اوس عبادت کرنہٕ خٲطرٕ یروشلم آمُت،\n28.\\tاوس واپس یِوان، تہٕ پننِس رتھس منز بِہتھ اوس یسیاس نبی پران۔\n29. اَمہِ پَتہٕ ووٚن روٝحہِ فِلپس نِش گژھُن، تہٕ پَنُن پان رٔلِتھ یَتھ رتھَس سٍتـ̡ شٲمِل گٔژھِو۔\n30.\\tتہٕ فلپس ژوٚل تٔمِس نِش، تہٕ بوز أمِس پیغمبر یسیاہس پران تہٕ وونُن، کیا ژیہ کیا پٔرِتھ چھُو؟\n31.\\tتہٕ ووٚن بہٕ کِتھہ کٔنۍ ہیکہٕ بہٕ کُنہِ انسانس سٍتـ̡ رہنمٲیی کٔرِتھ؟ تہٕ سُہ اوس فلپس یژھان زِ سُہ ییہ تس سٍتـ̡ بِہنہٕ۔\n32.\\tصحیفٕچ جاے یُس تٔمۍ پٔرِتھ پٔرِتھ اوس، سُہ آو ذبح کرنہٕ خٲطرٕ کٔرِتھ نِنہٕ۔ تہٕ یِتھے پٲٹھۍ کٔرِتھ\n33.\\tتٔمۍ سٕنزِ بے عزتی منز آو تٔمۍ سُند فیصلہ نِنہٕ: تہٕ کُس کرِ تٔمۍ سٕندِس زمانس ہُند اعلان؟ تکیازِ تٔمۍ سٕنز زندگی چھے زمینہٕ پیٹھٕ نِنہٕ آمٕژ۔\n34.\\tتہٕ خواجہ سرا دیُت فلپس جواب تہٕ وونُن، بہٕ چُھس ژےٚ دُعا کران، یُس نبی کُس کُس کتھ کران چُھ؟ پانس سٕتۍ، یا کٲنٛسہِ بییس انسانس سٕتۍ؟\n35. اَمہِ پَتہٕ کٔرٕن فِلپس پَنُن بوش تہٕ یێتھۍ صحیفہٕ سٍتـ̡ شروع کٔرِتھ کٔرٕن عیسیٰ مسیحٕچ تبلیغ۔\n36.\\tتہٕ ییلہ تِم وتہِ پکان پٔکۍ، تِم وٲتۍ أکِس آبس کُن، تہٕ کُنہِ آبس کُن وٲتِتھ وُچھِو، {یِتھ} چُھہ آب۔ کیا چُھہ میہ بپتسمہ دِنس منز رُکاوٹ تھاوان؟\n37. تہٕ فلپس ووٚن زِ اگر ژیہ پورٕ دِلہٕ سٍتـ̡ یقین تھاوان چُھ، تیلہِ ہێکہِ پٲٹھـ̡ یقین کٔرِتھ۔ تہٕ تٔمۍ دیُت جواب تہٕ وونُن، بہٕ چھُس یقین کران زِ عیسیٰ مسیح چُھ خدایہ سُند نیٚچُو۔\n38.\\tتہٕ تٔمۍ دِژ رتھَس رُکُن روزنُک حُکُم، تہٕ تِم گٔیہِ دۄشوے آبس منز، فلپ تہٕ کُرجہٕ سرا دۄشوٕے۔ تہٕ تٔمۍ دِژ أمِس بپتسمہ۔\n39.\\tتہٕ ییلہ تِم آبہٕ منزٕ نیبر دِنہٕ آمٕتۍ، خداوند سٕندِ روحن روٚٹ فلپس تہٕ کُنہِ تہِ وُچھُن نہٕ، تہٕ سُہ پوٚک خۅش گٔژھِتھ پننہِ وتہِ پٲٹھۍ۔\n40.\\tمگر فلپس آو ازوتسس منز لبنہٕ: تہٕ اَمہ کِنۍ گٔژِھتھ کٔرِن تٔمۍ سارنٕے شہرن مَنٛز تبلیغ کٔرِتھ، یوتام سُہ قیصریہ آو ۔","1. تہٕ ساؤل، توتہِ ووت خداوند سٕندِس مریدن خلاف دھمکی دِتھ تہٕ ذبح کٔرِتھ، گۆو بٔڈِس پادٕرِس نِش،\n2.\\tتہٕ کٔرٕن أمِس دمشق کِس عبادت خانس مَنٛز چِٹھہِ زِ اگر أمِس یِتھٕ وتہٕ لٔبِتھ، چاہے تِم مرد آسن یا زنانہٕ، سُہ اَنِن یِم یروشلمس کُن۔ {یتھ وتہِ: Gr. of the way}\n3.\\tییلہ سُہ سفر کٔرِتھ ووت دمشقس نزدیک، تہٕ اچانک گۆو تس اندۍ پکھۍ آسمانہٕ پیٹھہٕ گاش چمک:\n4. تہٕ سُہ پیوٚو زمینہِ پیٹھ، تہٕ بوزُن أمِس اکھ آواز یُس أمِس ونان چھُ، ساؤل، ساؤل، ژٕ کیازِ چُھکھ مےٚ ستاونہٕ آمُت؟\n5. تہٕ ووٚن تُہۍ کُس چُھ، خداوند؟ تہٕ خداوند ووٚن، بہٕ چُھس عیسیٰ یس ژے ستاونہٕ چُھ: ژےٚ چُھہ مشکل۔\n6.\\tتہٕ سُہ تھرِ تھرِ تہٕ حیران گٔژھِتھ وونُن، خداوند، ژے کیا کرُن میہ کرُن؟ تہٕ خداوند چُھہ أمِس وَنُن، وُتھِتھ تہٕ شہرس مَنٛز گژھُن، تہٕ یہِ گژھہِ ژے وَننہٕ یُن زِ ژے کیا کرُن۔\n7.\\tتہٕ أمِس سٍتـ̡ سفر کٔرِتھ یِم مرد سٍتـ̡ سٍتـ̡ وٲتِتھ گٔیہِ، اَکھ آواز بوزان مگر وُچھُن نہٕ کانہہ تہِ۔\n8. تہٕ ساؤل ووت زمینہِ منزٕ پٲدٕ۔ تہٕ ییلہ تٔمۍ سٕنزِ أچھ کھٲلِتھ وُچھ نہٕ أمِس کانہہ نفر، مگر تِمو کٔر أمِس اَتھٕ تھپھ کٔرِتھ تہٕ أنِن دمشقس منٛز۔\n9. تہٕ سُہ اوس تریہ دۅہ گاش نہٕ تہٕ نہ کھیوٚن تہٕ نہ چیوٚن۔\n10. تہٕ دمشقس مَنٛز اوس اکھ خاص شٲگِر، یٔمِس انانیاس ناو اوس۔ تہٕ أمِس ووٚن خداوند أکِس وژنس منز، انانیاس۔ تہٕ تٔمۍ ووٚن، وُچھ، بہٕ چُھس یتہِ، خداوند۔\n11.\\tتہٕ خداوند چُھ أمِس وَنُن، وۅتھٕ وُتھ، تہٕ گژھ تتھ سڑکہِ مَنٛز یَتھ سیدِ سٍتـ̡ ونان چھِ، تہٕ یہوداہ سٕندِس گرس مَنٛز پرژھہٕ گٲر کٔرِتھ یُس ساؤل ناو چُھ، یێلہِ سُہ دُعا کران چُھ،\n12.\\tتہٕ وُچھمُت أکِس وژنس منز یُس انانیاس ناوُک اکھ شخٕص اژان چُھ، تہٕ أمِس پیٹھ اتھہٕ تھووُن، یُتھ أمِس گاش میلہِ۔\n13. اَمہ پتہٕ دیُت انانیاس جواب، خداوند، مے چُھ یِمو منزٕ واریاہو نفرو بوزمُت زِ تٔمۍ کوتاہ بُرکار چُھ یروشلمس مَنٛز تُہندین مقدسن سٍتـ̡ کٔرمٕژ:\n14. تہٕ یێتہِ چُھ أمِس بٔڈۍ پادٕرین ہٕندِ طرفہٕ اِختِیار حٲصِل زِ سُہ چُھہ تُہٕندِس سارِنٕے ناوَس سٍتـ̡ پابند کرُن۔\n15.\\tمگر خداوند ووٚن أمِس وَتھ، پَنٕنہِ وَتہِ گژھُن، تِکیازِ سُہ چُھ میانہِ خٲطرٕ ژارنہٕ آمُت بانہٕ، یُس غیر قومن تہٕ بادشاہن تہٕ بنی اسرٲیلِس برونہہ کُن میون ناو تھاوُن:\n16. تکیازِ بہٕ ہاوٕ تس میانہِ ناوٕ خٲطرٕ کٲژاہ بٔڈ چیز گژھہِ دِنہٕ۔\n17.\\tتہٕ انانیاس دراو پننہِ وتہِ تہٕ ژاو گرس منز۔ تہٕ تٔمِس پیٹھ اتھہٕ تھٲوِتھ وونُن، برادر ساؤل، خداوند، {حتیٰ کہ} عیسیٰ مسیح، یُس تہٕ تۅہہِ ہٕندِس وتہِ منز ظٲہر گوو، تہٕ چُھہ مے سوزمُت، یُس ژے پنُن گاش حٲصل کٔرِتھ، تہٕ روح القدس سٍتـ̡ بٔرِتھ گژھِ۔\n18.\\tتہٕ یکدم پیوٚو تٔمۍ سٕنزِ أچھن نِش یِتھٕ پٲٹھۍ، تہٕ أمِس آو فوراً گاش تہٕ ووٚتھ، تہٕ کوٚرُن بپتسمہ دِنہٕ۔\n19. تہٕ ییلہ تس ماز میلہِ، سُہ آو مضبوط۔ اَمہِ پتہٕ اوس ساؤل کیٚنٛہہ دۄہ یِم دمشقس مَنٛز ٲسۍ۔\n20. تہٕ سیدِ سیدِ تٔمۍ کٔر یہِ عبادت خانن مَنٛز مسیح سٕنز تبلیغ زِ سُہ چُھ خدایہِ سُند نیٚچُو۔\n21.\\tمگر یُس سارِوٕے بوزان اوس تہٕ وونُن حٲران تہٕ وونُن؛ کیا یہِ چھُنہٕ سُہ یٔمۍ یِم یِم یِم یروشلمس مَنٛز امہِ ناوُک ناو بَناوان چھِ، تہٕ یِمن ہٕندِس ارادٕ سٍتـ̡ آو یُتھ سُہ تِم بٔڈِتھ پادٕرین نِش بٔنِتھ؟\n22. مگر ساؤلن ہُریوو طاقتس منز زیادٕ، تہٕ دمشقس مَنٛز روزن وٲلِس یہودی ہُند ہُرراوُن تہٕ ثٲبت کٔرِتھ زِ یہِ چُھ واریاہ مسیح۔\n23. تہٕ امہِ پتہٕ گٔیہِ واریاہ دۅہہ، یہودیو کٔر أمِس مارنُک مشورٕ:\n24.\\tمگر تِہُند انتظار اوس ساؤلس سٍتـ̡ پتاہ۔ تہٕ تِم ٲسۍ أمِس مارنہٕ خٲطرٕ دۄہ رات دروازٕ وٕچھان۔\n25.\\tپَتہٕ نِیو أمِس رٲژ رٲژ تہٕ ترووُن دیوارس نِش أکِس ٹوٗکرِ منز۔\n26. تہٕ ییلہ ساؤل یروشلم آو تہٕ تٔمۍ کٔر شاگردن سٍتـ̡ شٲمل گژھنٕچ کوشش، مگر تِم ٲسۍ أمِس کھوژان، تہٕ یێلہِ اوس نہٕ یقین زِ سُہ چُھ اکھ شٲگِر۔\n27. مگر برنابن نیو سُہ تہٕ أنِن رسولن نِش، تہٕ تِمن اعلان کورُن زِ تٔمۍ کِتھہ پٲٹھـ̡ اوس خداوند وتہِ وُچھمُت، تہٕ تٔمِس سٍتـ̡ کتھ کٔرمٕژ تہٕ کِتھہ کٔنۍ اوس تٔمۍ دمشقس مَنٛز عیسیٰ سٕندِ ناوٕ سٍتـ̡ دِلیری سان تبلیغ کٔرمٕژ۔\n28.\\tتہٕ سُہ اوس تِمن سٍتـ̡ یِمن سٍتـ̡ یِوان تہٕ یُس یروشلمس مَنٛز نیران اوس۔\n29.\\tتہٕ تٔمۍ کٔر خداوند عیسیٰ سٕندِ ناوٕ سٍتـ̡ دِلیلہٕ سٍتـ̡ کتھ تہٕ یونانین سٍتـ̡ کٔرٕن تنازعہٕ، مگر تِمو گٔیہِ أمِس مارنہٕ خٲطرٕ۔\n30.\\t{یُس}ییلہ بٲے پتاہ لٔگۍ، تِمو أنِو سُہ قیصریہ کُن تہٕ سوٗزُکھ سُہ ترسس کُن۔\n31. پَتہٕ کٔرٕن کلیساہٕ سٲرۍسٕے یہوداہس تہٕ گلیل تہٕ سامریہ سٍتـ̡ آرام تہٕ سٍتـ̡ تہٕ خداوند سٕندِس خوفس مَنٛز، تہٕ روح القدس سٕندِس آرامس مَنٛز پکُن گٔیہٕ زیادٕ۔\n32.\\tتہٕ سپُد یہِ سپُد، یُتھ پطرس سارِنٕے حلقن مَنٛز پٔکِتھ پٔرِتھ، سُہ آو تِمن مقدسن نِش تہِ یِم لِداہَس مَنٛز روزان ٲسۍ۔\n33.\\tتہٕ تتہِ وُچھ أمِس اینیاس ناوُک اکھ شخٕص یُس ٲٹھن ؤرین پننِس بسترس منز تھٲومُت اوس، تہٕ اوس فالج سٍتـ̡ بیمار۔\n34. تہٕ پطرس ووٚن أمِس اینیاس، عیسیٰ مسیح چُھہ ژے صحت مند بناوان: وۅتھُن تہٕ پَنُن بستر۔ تہٕ سُہ ووٚتھ فوراً۔\n35.\\tتہٕ یُس سارِوٕے لِڈا تہٕ سارونس مَنٛز روزان اوس، وُچھ أمِس تہٕ پھیُر خداوند کُن۔\n36.\\tوۅنۍ اوس جوپاہس منز تبیتھا ناوُک اکھ شٲگِر، یٔمِس تشریح مطابق ڈورکاس ونان چھِ: یہِ زنانہٕ ٲس نیک کامہِ تہٕ خیرات سٍتۍ بٔرِتھ یِم أمِس کٔرۍ۔ {ڈورکاس: یا، ڈو، یا، رو}\n37.\\tتہٕ تِمن دۅہن سپد یہ زِ سۅ ٲس بیمار تہٕ مٔرۍ: یُس تمو واش کٔرِتھ، تمو دِژ أکس ہیٚرمِس کمرس مَنٛز۔\n38.\\tتہٕ ییلہ لِدا یوپاہس نزدیک اوس، تہٕ شاگردو اوس بوزمُت زِ پطرس اوس تتہِ، تِمو سوٗزۍ أمِس نِش زٕ نفر، یہِ زِ سُہ کرِ نہٕ تِمن نِش یِنس ژیر کرنہٕ۔ {تاخیر: یا، غمگین}\n39. پطرس ووٚتھ تہٕ گۆو تِمن سٍتـ̡ ۔ ییلہ سُہ آو تِمو أنۍ سُہ ہیٚرمِس کمرس منٛز: تہٕ سارِنٕے بیواہ گٔیہٕ أمِس نِش وَنُن، تہٕ تِم کوٹ تہٕ پلو ہٲوِتھ یِم ڈورکاسن تِمن سٍتۍ ٲس۔\n40. مگر پطرس کٔر تِم سارِنٕے برونہہ کُن، تہٕ کۄٹھن بٔنِتھ کٔرٕن دُعا۔ تہٕ ووٚن جسمس کُن پھیُرِتھ تبیتھا، وۅتھُن۔ تہ تمۍ کٔر اچھ تہ ییلہ تس پیٹر وُچھ، سۅ بیوٹھ تھوٚد۔\n41.\\tتہٕ تٔمۍ دِژ أمِس اَتھٕ تہٕ تُلِتھ تھوٚد، تہٕ ییٚلہِ تٔمۍ مُقدسن تہٕ بیواہ بُلٲوِتھ دِژ سۄ زِندٕ پیش۔\n42.\\tتہٕ یہِ اوس سارِنٕے یوپاہس منز زاننہٕ آمُت۔ تہٕ واریاہ لوٗکھ ٲسۍ خداہس پیٹھ یقین تھاوان۔\n43.\\tتہٕ سپُد یہِ زِ سُہ روٗد واریاہن دۅہن جوپاہس منز أکِس شمعون سٍتـ̡ أکِس ٹینرس سٍتـ̡ روزان۔","1.\\tسیزراہس منز اوس اکھ خاص شخٕص ییمِس کارنیلیس ناو اوس، یُس بینڈُک اکھ سینچورین اوس یتھ اطالوی {بینڈ} ونان چھِ،\n2.\\t{A} دیندار {انسان}، تہٕ یُس خدایہ سٍتـ̡ سارِنٕے گرس سٍتـ̡ خدایہ سٍتـ̡ خوف کران اوس، یُس لُکن سٍتـ̡ سٮ۪ٹھاہ خیرات دِوان اوس، تہٕ ہمیشہ خدایہ سٕنز دُعا کران اوس۔\n3. تٔمۍ وُچھ أکِس وژنس مَنٛز یُس دۅہہٕ کِس نٔوِمِس گھنٹس مَنٛز خدایہِ سُند اکھ فرشتہ أمِس نِش یِوان تہٕ أمِس وَنُن کارنیلیئس۔\n4.\\tتہٕ ییلہ أمِس وُچھان اوس، سُہ گوٚو کھوژُن، تہٕ وونُن، یہ کیا چُھ، خداوند؟ تہٕ تٔمۍ ووٚن تٔمِس زِ تُہٕنٛز دُعا تہٕ تُہٕنٛز خیرات چھِ خدایہِ سٕنٛدِ برٛونٛہہ کُن یادگار خٲطرٕ آمٕژ۔\n5.\\tتہٕ وُنۍ سوزُن نفر یُس یُس پطرس سٍتـ̡ سُند ناو چُھ:\n6. سُہ چُھ أکِس شمعون سٕندِس سٍتـ̡ روزان، یٔمۍ سُند مکانہٕ سمندرس نِش چُھ، سُہ وَنُن ژے کیا کرُن۔\n7. تہٕ ییلہ فرشتہ یُس کارنیلیئس سٍتـ̡ کتھ کران اوس، تٔمۍ بُلوو پننین زٕ گرِ نوکر تہٕ تِمن ہُند اکھ عقیدت مند سپاہی یُس أمس لگاتار انتظار کران اوس۔\n8.\\tتہٕ ییلہ تٔمۍ تِمن سارِنٕے چیزن ہُند اعلان کٔر، تٔمۍ سوٗزۍ یُس یُس یوپاہس نِش دِنہٕ آمُت۔\n9.\\tپوٚت ییلہ تِم سفر کٔرِتھ شہرس نزدیک وٲتِتھ، پطرس ووت شیٚیِمہِ گھنٹہِ دُعا کرنہٕ خٲطرٕ مکانس پیٹھ۔\n10.\\tتہٕ سُہ گوٚو سٮ۪ٹھاہ فاقہٕ، تہٕ کھٮ۪وان اوس، مگر ییلہ تِمو تیار گٔیہ، سُہ گوٚو خۅش گٔژھن،\n11.\\tتہٕ وُچھ اسمانس کھُلُن، تہٕ اکھ خاص بانہٕ آو أمِس نِش وسان، یِتھ زن سُہ ژۅشونی کونن پیٹھ بٔڈِتھ وُچھِتھ زمینس پیٹھ تراوُن:\n12.\\tیتھ منز ٲس زمینہِ ہندۍ ژۅن کھۅرن ہندۍ جانور تہ جنگلی جانور تہ ہوہکۍ جاناوار تہ کۅکرۍ جاناوار۔\n13.\\tتہٕ تس آو اکھ آواز، وۅتھ، پطرس۔ مارُن تہٕ کھٮ۪ن۔\n14.\\tمگر پطرس ووٚن نہ، خداوند۔ تکیازِ میہ چھہ نہ زانہہ کانہہ چیز کھیوٚمت یُس عام یا ناپاک آسہِ۔\n15.\\tتہٕ دوٚیمہِ لٹہِ یُس خداین پاک کورمُت چھُ، {یُس} چُھہ نہٕ عام وَنان۔\n16. یہ آو تریہ لٹہِ کرنہٕ: تہٕ یہ برتن آو دُبارٕ جنتس مَنٛز رٹنہٕ۔\n17.\\tوۅنۍ ییلہ پطرس پانس منز شک اوس زِ یُس وژن تٔمۍ وُچھمُت اوس، تمیک مطلب کیا گژھہِ، وُچھِو یِمو نفر یِم کارنیلیس سٕندِ طرفہٕ سوزنہٕ آمٕتۍ ٲسۍ، تِمو اوس شمعون سٕندِس مکانس مُتلق پرژھہٕ گٲر کٔرمٕژ، تہٕ گٔیہِ دروازس برونہہ کُن کھڑا۔\n18.\\tتہٕ فون کٔرِتھ پرژھُن زِ شمعون یُس پطرس ناو اوس، اوسا اتہِ روزنہٕ آمُت۔\n19.\\tییلہ پطرس وژنس پیٹھ سونچُھ، روٝحن ووٚن أمِس وۆن، وُچھو، تریہ نفر چھِ تۅہہِ ژھاران۔\n20. تَمہِ وِزِ ووٚتھ، تہٕ بۄن پٲٹھۍ، تہٕ یِمن سٍتـ̡ گژھُن، کُنہِ تہِ شک کٔرِتھ، کیازِ مے چُھ تِم سوزمٕتۍ۔\n21. پطرس ووت تِمن نفرن نِش یِم کارنیلیس سٕندِ طرفہٕ أمِس نِش سوزنہٕ آمٕتۍ ٲسۍ۔ تہٕ ووٚنُن، وچھ بہٕ چھُس سُہ یُس ژےٚ ژھاران چھُو: کیا وجہ چھُکھ تہٕ یُس تہٕ یِمو چھِ؟\n22. تہٕ تِمو ووٚن، کارنیلیئس سُہ اکھ عادل انسان، یُس خدایہ سُند خوف چُھ، تہٕ یہودین ہٕندِس سارِنٕے قومس مَنٛز رٔژ خبر دِنہٕ آمُت، أمِس اوس خدایہِ سٕندِ طرفہٕ أکِس مقدس فرشتن تنبیہ دِژمُت زِ سُہ سُہ تُہٕندِس گَرَس مَنٛز سوزُن، تہٕ تۅہہِ ہٕنز کتھ بوزنہٕ خٲطرٕ۔\n23.\\tتمہ پتہ بُلٲوۍ تِمن اندر تہٕ کٔرِن تِمن ہٕندِس داخلس منز۔ تہٕ پوٚت پطرس تِمن سٍتـ̡ تہٕ یوپا ہٕندِ کینہہ بٲے گٔیہِ أمِس سٍتـ̡ ۔\n24. تہٕ پَگہہ ییٚلہِ تِم قیصریہ مَنٛز دٲخل گٔیہِ۔ تہٕ کارنیلیس اوس تِمن ہُند پیاران، تہٕ کورُن پننین رشتہٕ دارن تہٕ نزدیکی دوس بُلٲومُت۔\n25.\\tییلہ پطرس اژان اوس، کارنیلیس سمکھیوو أمس تہٕ پیوٚو أمس قدمن پیٹھ، تہٕ کٔرٕن أمِس پوٗزا کرنہٕ۔\n26.\\tمگر پطرس تُل سُہ تھوٚد تہٕ ووٚنُن، کھڑا گژھُن۔ بہٕ چھُس پانہٕ تہِ اکھ مرد۔\n27.\\tتہٕ ییلہ أمِس سٍتـ̡ کتھ کٔرِتھ، سُہ ژاو اندر، تہٕ وُچھِن واریاہ یِم اَکہٕ وٹہٕ آمٕتۍ۔\n28.\\tتہٕ تٔمۍ ووٚن تِمن پتاہ زِ یہودی شخصہٕ سٕندِ خٲطرٕ صحبت تھاوُن یا بییِس قومس مَنٛز یُن چُھ ناجٲیز۔ مگر خداین چھہ میہ ہٲومُت زِ بہٕ پزِ نہ کٲنسہِ انسانس عام یا ناپاک ونُن۔\n29. تێمہِ کِنۍ آو بہٕ ژےٚ نِش بےٚ انکار کرنہٕ، یێلہِ بہٕ سوزنہٕ آمُت: تێلہِ چُھس پرژھان ژے کمہِ ارادٕ خٲطرٕ سوزمُت؟\n30. تہٕ کارنیلیئسن ووٚن، ژور دۅہ برونہہ اوسُس بہٕ اتھ وقتس تام روزٕ تھاوان۔ تہٕ نٔومہِ بجہ کٔر میہ پننِس گرس منز دُعا، تہٕ وُچھ اکھ شخٕص چمکدار پلو لٲگِتھ میہ برونہہ کُن کھڑا،\n31. تہٕ وونُن، کارنیلیئس، تہنز دعا چِھ بوزنہٕ آمٕژ، تہٕ تُہند خیرات چُھ خدایہِ سٕندِس نظرس منز یاد پاونہٕ آمُت۔\n32.\\tلہٕ سوز یُس پطرس سٍتـ̡ چُھ، سُہ کٔرِو یُس پطرس سٍتـ̡ سٍتـ� سُہ چُھ سمندرٕ بٔٹھِس نِش شمعنہٕ سٕندِس گرس منز روزنہٕ آمُت: یُس یِنہٕ وِزِ سُہ یِنہٕ سٍتـ̡ تۅہہِ سٍتـ̡ کتھ کرِ۔\n33. تَمہِ کِنۍ سوز میہ ژے نِش۔ تہٕ ژے چھُکھ اَصٕل کٔرِتھ یُس تہٕ ژٕ آو آمُت۔ تێلہِ چُھہ أسـ̡ سٲری خدایہِ سٕندِس برونہہ کُن موجود، تِمن سارِنٕے چیزن بوزنہٕ خٲطرٕ یُس تۅہہِ خدایہِ سُند حکم دِنہٕ آمُت چُھ۔\n34.\\tپَتہٕ پطرس کٔر اَتھ مُتعلِق تہٕ وونُن، پٔزۍ پٲٹھـ̡ چُھس بہٕ سمجھان زِ خدا چُھنہٕ شخصن ہُند احترام کَران۔\n35. مگر پریتھ قومس مَنٛز یُس أمِس سٍتـ̡ خوفزدہ چُھ، تہٕ نیکی کَران چُھ، سُہ چُھ أمِس سٍتـ̡ قبول کرنہٕ یِوان۔\n36. سُہ کلام یُس {خدایہ} بنی اسرٲیلِس خٲطرٕ سوزمُت چُھ، یُس عیسیٰ مسیح سٕندِ طرفہٕ امنُک تبلیغ کران چُھ: (سُہ چُھ سارِنٕے ہُند رب :)\n37.\\tسُہ لفظ، {بہٕ چُھس ونان}، یُس سٲرۍسٕے یہوداہس منز شایع سپُد، تہٕ یُس یوحنا سٕندِ بپتسمہ پتہٕ گلیل پیٹھٕ شروع گومُت۔\n38. کِتھہ پٲٹھـ̡ کٔر خداین عیسیٰ مسیحس پاک روح سٍتـ̡ تہٕ طاقتہٕ سٍتـ̡ مسح کرنہٕ: یُس نیکی کٔرِتھ تہٕ شیطان سٕندِ سٍتـ̡ ظلمن ہٕندِس سارِنٕے سٍتـ̡ شفا دِنہٕ آو۔ تکیازِ خدا اوس تس سٍتۍ۔\n39. تہٕ أسۍ چھِ تِمن سارِنٕے چیزن ہٕندِ گواہ یِم تٔمۍ یہودین ہٕندِس ملکس تہٕ یروشلمس مَنٛز کٔر۔ یُس تمو مٲرِتھ کُلِس پیٹھ پھانسی دِژ:\n40. خداین دِژ تریمہِ دۅہہ تُلتھ تہٕ ہٲوُن سُہ کھلہٕ پٲٹھۍ۔\n41.\\tسارِنٕے لُکن ہٕندِ خٲطرٕ، بٔلکہِ خدایہ سٕندِ برونہہ کُن منتخب کرنہٕ آمٕتۍ گواہَن سٍتـ̡، یِمو سُہ مُردٕ منزٕ زندٕ گژھنہٕ پتہٕ أمِس سٍتـ̡ کھٮ۪وان تہٕ چیوان اوس۔\n42. تہٕ تٔمۍ دِیُت اسہِ حُکُم زِ سُہ چُھ خدایہِ سٕندِ طرفہٕ مقرر کرنہٕ آمُت یُس جلدٕے تہٕ مُردُک قاضی بنُن چُھ۔\n43.\\tتٔمِس دِیُن سارِنٕے پیغمبرن گوٲہی زِ یُس تہندِس ناوٕ سٍتـ̡ یُس أمِس پیٹھ ایمان تھاوان چُھ، سُہ گژھہِ گۅنہہ ہٕنز معافی حٲصِل کرنہٕ۔\n44.\\tیێلہِ پطرس یێلہِ تہِ یِم لفظ بوزان اوس، روح القدس پیوٚو تِمن سارِنٕے سٍتـ̡ یِمو یہِ لفظ بوزان اوس۔\n45.\\tتہٕ یِم ختنہ کٔرِتھ یِم پطرس سٍتـ̡ وٲتِتھ گٔیہِ حٲران، تکیازِ یہِ تہِ اوس غیر قومن پیٹھ تہِ روح القدس سُند تحفہٕ تراونہٕ آمُت۔\n46.\\tکیازِ تِمو بوز تِم زبانہِ سٍتـ̡ کتھ کٔرِتھ، تہٕ خدایہِ سٍتـ̡ بٔرِتھ۔ پطرس دیُت جواب،\n47. کیا کانہہ انسان ہیکہِ آبس منع کٔرِتھ، یُس نہٕ یِمن بپتسمہ دِنہٕ یُن، یِمو روح القدس تہٕ اسہِ تہِ بپتسمہ دِنہٕ یُن؟\n48. تہٕ تٔمۍ دِیُت تِمن خداوند سٕندِ ناوٕ سٍتـ̡ بپتسمہ دِنُک حُکُم۔ پتہٕ کٔر تِمو أمِس کینژن دۄہن روزنہٕ خٲطرٕ دُعا۔","1.\\tتہٕ رسولو تہٕ بٲے یُس یہوداہس مَنٛز اوس، بوز زِ غیر قومن تہِ اوس خدایہ سُند کلام حٲصل کورمُت۔\n2. تہٕ یێلہِ پطرس یروشلمس منز ووت، یێلہِ ختنہ کرنہٕ آمٕژ ٲس، تِمو کٔر أمِس سٍتـ̡ مُقابلہٕ،\n3.\\tیہ ونِتھ زِ ژے ٲسکھ ختنہ نہ کرنہٕ آمٕتۍ انسانس سٍتـ̡ کھٮ۪وان تہٕ تِمن سٍتـ̡ کھیوٚمُت۔\n4.\\tمگر پطرس کٔر شروع پیٹھے اتھ معاملس پیٹھ پرہیز، تہٕ کٔرٕن تِمن حُکمہٕ سٍتـ̡ وضاحت کٔرِتھ وونُن،\n5.\\tبہٕ اوسُس جوپا شہرس مَنٛز دُعا کران تہٕ أکِس وُچھِتھ وُچھ اکھ وژن، اَکھ خاص بانہٕ وُچھُن، یُس ژۅن کُنَو سٍتـ̡ آسمانہٕ پیٹھٕ وسان اوس۔ تہٕ یہ آو میہ تہِ:\n6.\\tیتھ پیٹھ ییلہ میہ اچھ بند کٔرۍ، میہ وُچھمُت تہٕ وُچھمُت زٔمیٖنہٕ ہٕندِس ژۅن قدمن ہٕندۍ جانور، تہٕ جنگلی جانور، تہٕ رٔژِتھ چیز تہٕ ہوہٕکۍ جاناوار۔\n7.\\tتہٕ بوز میہ اکھ آواز یُس میہ ونان اوس، وۅتھ، پطرس۔ مارُن تہٕ کھیوٚن۔\n8.\\tمگر میہ ووٚن، تۅہہ چھہ نہ خداوند، تکیازِ کنہِ ساعتہ چھہ نہ میٲنس ٲسس منز کانہہ عام یا ناپاک چیز دٲخل سپدان۔\n9.\\tمگر آوازِ دِژ میہ آسمانہٕ پیٹھٕ دُبارٕ جواب، یُس خداین پاک کورمُت، {یُس} چُھہ نہٕ عام وَنان۔\n10. تہٕ یہ آو تریہ لٹہِ کرنہٕ: تہٕ سٲری آیہ دُبارٕ جنتس مَنٛز کھیننہٕ۔\n11.\\tتہٕ وُچھِتھ گٔیہِ فوراً تریہ نفر تتھ مکانس منز ییتہِ بہٕ اوسس، یُس میہ نِش سوزنہٕ آمُت اوس، یُس میہ نِش سوزنہٕ آمُت اوس۔\n12.\\tتہٕ روحن دِژ میہ تمن سٍتـ̡ گژھنُک حُکُم۔ امہِ علاوٕ گٔیہِ یِم شےٚ بٲے میہ سٍتۍ، تہٕ أسۍ ژاو أمِس شخصہٕ سٕندِس گرس منز:\n13. تہٕ تٔمۍ ہٲو اسہِ زِ کِتھ کٔنۍ اوس تٔمۍ پننِس گرس مَنٛز اکھ فرشتہ وُچھمُت، یُس کھڑا اوس تہٕ أمِس ووٚنمُت، یُس یوپا نِش نفر سوزُن، تہٕ شمعون بُلاون، یٔمۍ سٕنز کنیت پطرس چھِ۔\n14. کُس کرِ تۅہہِ سٍتـ̡ کُس لفظ وَنُن، یێمہِ سٍتـ̡ تُہہِ تہٕ تُہُند سارِوٕے گرٕ بچاونہٕ ییہِ۔\n15. تہٕ یێلہِ بہٕ کتھ ہیوٚت، روح القدس پیوٚو تِمن پیٹھ، یِتھ کٔنۍ زَن اسہِ پیٹھ۔\n16.\\tتێلہِ گۆو میہ رب سُند کلام یاد، یێلہِ وۆن یوحنا پٔزۍ پٲٹھـ̡ آبہٕ سٍتـ̡ بپتسمہ دِنہٕ۔ مگر تُہۍ یِیہِ روح القدس سٍتـ̡ بپتسمہ دِنہٕ۔\n17. تێلہِ دِژ خداین تِمن یُتھ تحفہٕ یُس اسہِ خٲطرٕ دِیُت، یُس خداوند عیسیٰ مسیحس پیٹھ ایمان اوس تھاوان۔ بہٕ کیا اوسس، یُس بہٕ خدایس مقابلہٕ کٔرِتھ؟\n18.\\tیێلہِ یێلہِ یِم کتھ بوٗزِ، تِمو کٔر پانس سٍتـ̡ تہٕ خدایہِ سٕندِس جلال سٍتـ̡ وونُن، تێلہِ چُھہ خداین تہِ دِژمُت زِندٕ۔\n19.\\tوۅنۍ یِم سٹیفنس سٍتـ̡ سپدن وٲلِس ظلمس سٍتـ̡ بێیہِ مُلکَس مَنٛز پھٔہلِتھ گٔیہِ، تِمو گٔیہِ فینیس، قبرص تہٕ انطاکیہ تام سفر، تہٕ یہودی سٍتـ̡ کُنہِ تہِ لفظٕچ تبلیغ کٔرِتھ۔\n20.\\tتہٕ یِمو منزٕ ٲسۍ کینہہ قبرص تہٕ سائرین ہٕندِس انسان، یِمو ییلہ تِم انطاکیہ وٲتِتھ، یِمو کٔر یونانن سٍتـ̡ خداوند عیسیٰ سٕنز تبلیغ کٔرِتھ۔\n21.\\tتہٕ خداوند سُند اَتھٕ اوس تِمن سٍتـ̡ تہٕ واریاہ لٔگـ̡ یێلہِ پى۪ٹھہٕ پى۪ٹھ۔\n22. اَمہِ پتہٕ وٲژ یِمن چیزن ہٕنز خبر یُس یروشلمس مَنٛز اوس کلیساہٕ کِس کنن تام، تہٕ تِمو سوٗز برنباس زِ سُہ گژھہِ انطاکیہ تام گژھُن۔\n23.\\tیُس ییلہ سُہ آو تہٕ خدایہِ سُند فضل وُچھمُت، سُہ گوٚو خۄش، تہٕ تِمن سارِنٕے نصیحت کٔرِتھ زِ تِم گژھن دِلہٕ سٍتـ̡ خداوند سٕندِس سٍتـ̡ رٔٹِتھ رٔٹِتھ۔\n24. تکیازِ سُہ اوس اکھ اصل انسان، تہٕ روح القدس تہٕ ایمانہٕ سٍتـ̡ بٔرِتھ تہٕ خداوند سٕندِس سٍتـ̡ واریاہ لُکھ شٲمل کرنہٕ آمُت۔\n25. پتہٕ دراو برنباس تارسوس کُن، تاکہ ساؤل ژھانڈنہٕ خٲطرٕ:\n26. تہٕ ییلہ أمِس لٔبِتھ سُہ انطاکیہ نِش أنِتھ۔ تہٕ سپُد یہِ زِ پوٗرٕ ؤری کٔر تِمو کلیساہس سٍتـ̡ جمع تہٕ واریاہن لوٗکن ہیچھناوٕنـ̡ ۔ تہٕ شٲگردن ٲس انطاکیہس منٛز گوڑنتھ عیسائی وننہٕ یوان۔ {سۭتۍ...: یا، کلیساہس منز}\n27. تہٕ یِمن دۅہن آیہ یروشلم پیٹھٕ انطاکیہ تام پیغمبر۔\n28.\\tتہٕ تِمو منزٕ ووت اَکھ اگابس ناو، تہٕ یُس روحہٕ سٍتـ̡ اشارہ کورمُت زِ سٲرۍسٕے دُنیاہس منز گژھہِ واریاہ کمی آسٕنۍ، یُس کلاڈیس سیزر سٕندِس دۅہس مَنٛز سپُد۔\n29. پَتہٕ کٔر شٲگِر، پرٮ۪تھ أکِس انسانس پننہِ قٲبلِیت مُطٲبق، یہوداہس مَنٛز روزن وٲلِس بٲے سٍتـ̡ راحت واتنُک ارادٕ۔\n30. یُس تِمو تہِ کوٚر، تہٕ سوٗزُکھ یہِ برنباس تہٕ ساؤل سٕندِ اتھہٕ سٍتـ̡ بزرگن نِش۔","1.\\tوۆن تمہِ وقتہ ہیرودیس بادشاہن کلیساہٕچ کُنہِ {پھیلاونہٕ آمُت...: یا، شروع}\n2. تہٕ تٔمۍ مور یوحنا سُند بوے یعقوب تلوار سٍتـ̡ ۔\n3.\\tتہٕ کیازِ أمِس وُچھ یہودی خۅش گٔیہِ، سُہ وُچھ پطرس تہِ نِنہٕ خٲطرٕ۔ (تمہ پتہ ٲسۍ خمیر روٚس روٹی ہند دۅہ۔)\n4.\\tتہٕ ییلہ أمِس رٔٹِتھ رٔٹِتھ، تٔمِس تھووُن قٲد خانس منز، تہٕ دِژُن أمِس رژھراونہٕ خٲطرٕ ژورن ژۅن سپاہَن حوالہٕ۔ ایسٹر پتہٕ اوس سُہ لوکن برونہہ کُن اننُک ارادٕ۔ {ایسٹر: Gr. Passover} {کواٹرنینز: ژور فوجین ہنز اکھ فایل}\n5. پطرس آو جیلس مَنٛز تھاونہٕ: مگر کلیساہٕ رُکاونہٕ بغٲر آو خدایہِ سٕندِ خٲطرٕ دعا کرنہٕ۔ {دُعا...: یا، فوری تہٕ سنجیدگی سان دُعا کرنہٕ}\n6. تہٕ یێلہِ ہیرودیس أمِس نیبر کُن أنِتھ، امی رٲژ اوس پطرس دۄن فوجین درمیان شوٚنگتھ، دۄن زنجیرن ہٕنزِ زنجیر لٲگِتھ: تہٕ دروازس برونہہ کُن تھاون والیو اوس قٲد خانہٕ۔\n7. تہٕ وُچھ خداوند سُند فرشتہ آو تہٕ جیلس مَنٛز لوٚگ گاش، تہٕ تٔمۍ لوٚگ پطرس اندۍ پٲٹھۍ، تہٕ تھوٚد تھوٚد تہٕ ووٚتھ، ووٚتھُن جلدی وۅتھُن۔ تہٕ تٔمۍ سٕنزِ زنجیر گٔیہِ اَتھٕ نِش ژٔٹِتھ۔\n8.\\tتہٕ فرشتہٕ ووٚن أمِس پانس بٔرِتھ تہٕ پَنٕنۍ چُپنہٕ لٲگِتھ لٲگِتھ۔ تہٕ تٔمۍ کوٚر تِتھۍ کٔرۍ۔ تہٕ سُہ چُھ أمِس ونان زِ پَنُن پلو ترٛٲوِو پانس اندۍ پکھۍ، تہٕ میانہِ پتہٕ پٲٹھۍ۔\n9.\\tتہٕ سُہ دراو نیبر، تہٕ أمِس پَتہٕ پَتہٕ۔ تہٕ یہ چھہ نہ زانان زِ یہ اوس پوٚز یُس فرشتن اوس کوٚرمت۔ مگر سونچُن زِ تٔمۍ وچھ اکھ وژن۔\n10.\\tییلہ تِم گۄڈنِکِس تہٕ دۆیمِس وارڈس نِش وٲتِتھ، تِم وٲتۍ شیشتٕرِ دروازس کُن یُس شہرس کُن گژھان چھُ۔ یُس تِمن ہٕندِ خٲطرٕ پننہ مرضی سٍتۍ یلہٕ کھُلہٕ: تہٕ تِم گٔیہِ نیٚبر، تہٕ أکِس سڑکہِ کِنۍ گٔیہِ۔ تہٕ فوراً دراو فرشتہ أمِس نِش۔\n11. تہٕ ییلہ پطرس پانس نش آو، تٔمۍ ووٚن، وُنہِ چُھس بہٕ أکِس ضمانتس سٍتـ̡ پتاہ زِ خداوند چُھ پنُن فرشتہٕ سوزمُت، تہٕ چُھکھ میہ ہیرودیس ہٕندِ اتھہٕ نِش تہٕ یہودی لوکن ہٕنزِ سارِنٕے وۅمید نِش نجات دِژمٕژ۔\n12.\\tتہٕ ییلہ تٔمۍ {اتھ چیز} پیٹھ غور کوٚر، سُہ آو یوحنا سٕنزِ موج مریم سٕندِس گرس منز، یٔمۍ سٕنز کنیت مرقس ٲس۔ یتہٕ واریاہ ٲس دعا کرنہٕ خٲطرٕ جمع گٔمٕتۍ۔\n13. تہٕ یُتھ پطرس دروازٕ کِس دروازس پیٹھ دستک دِژ، اَکھ لڑکی آیہِ بوزنہٕ خٲطرٕ، ییمِس روڈا ناو اوس۔ {بوزنہٕ خٲطرٕ: یا پرژھنہٕ خٲطرٕ کُس اوس تتہِ}\n14.\\tتہٕ ییلہ تس پطرس سنز آواز پتاہ ٲس، تٔمۍ کھول نہٕ خوشی خٲطرٕ دروازٕ، بلکہ ژٔلِتھ ژٔلِتھ تہٕ وونُن زِ پطرس کِتھہ پٲٹھۍ اوس دروازس برونہہ کُن کھڑا ۔\n15.\\tتہٕ تِمو ووٚن أمِس پاگل۔ مگر تٔمۍ ٲس لگاتار تصدیق کران زِ یہ تہِ چھہ تیو۔ پتہٕ ووٚن تمو ، یہ چُھ تٔمۍ سُند فرشتہٕ۔\n16.\\tمگر پطرس تھوو دستک دِوان تہٕ ییلہ تِمو دروازٕ کھولِتھ وُچھ، تِم گٔیہِ حٲران۔\n17.\\tمگر تٔمۍ دِژ تِمن اتھہٕ سٍتـ̡ اِشارٕ کٔرِتھ تِمن ہُند اعلان زِ خداوند کِتھہ کٔنۍ اوس سُہ قٲد خانہٕ منزٕ نیبر کڈمُت۔ تہٕ تٔمۍ ووٚن، یِم چیز ہٲوِو یعقوبس تہٕ بٲے ۔ تہٕ سُہ دراو بییِس جایہ۔\n18.\\tوۅنۍ ییلہ دۅہ ووت، فوجین منز گوو نہ کانہہ لۅکٹ ہنگامہ، پطرس کیا گوو۔\n19. تہٕ ییلہ ہیرودین أمِس ژھانڈان تہٕ لوٚب نہٕ، تٔمۍ دِژ رٲچھ کرن والٮ۪ن ہُند معائنہٕ تہٕ حکم دِیُت زِ تِم گژھن مارنہٕ یِنۍ۔ تہٕ سُہ ووت یہوداہ پیٹھہٕ قیصریہ تام، تہٕ {تتہِ} گٔیہِ روزن۔\n20.\\tتہٕ ہیرودیس اوس صور تہٕ صیدون سٍتـ̡ تِمن سٍتـ̡ سٮ۪ٹھاہ ناراض، مگر تِم آیہ اَکہٕ سٍتـ̡ أمِس نِش، تہٕ بلاسٹس بادشاہ سُند چیمبرلین پنُن دوس بنٲوِتھ کوٚرُکھ امنُک خواہش۔ تِکیازِ تِہُند مُلُک اوس بادشاہ سٕندِ {ملک} سٍتۍ پرورش سپدان۔ {اوس زیادٕ...: یا، دشمن ذہن، جنگُک ارادٕ تھاوان} {بادشاہ سُند چیمبرلین: Gr. یہ اوس بادشاہ سٕندِس بیڈ چیمبرس پیٹھ}\n21. تہٕ أکِس مُقرر دۅہہٕ بِہتھ ہیرود، شٲہی لباسس منز لٲگِتھ، بِیوٹھ پننِس تختس پیٹھ، تہٕ کٔرٕن تِمن خٲطرٕ اکھ تقریر۔\n22.\\tتہٕ لُکن دِژ کرٛٮ۪کھ، {وونُن} یہِ چھے خدایہ سٕنز آواز، نہ کہِ انسان سٕنز آواز۔\n23.\\tتہٕ یێلہِ دِژ خداوند سٕندِ فرشتن أمِس مار، تکیازِ تٔمۍ دِژ نہٕ خدایس جلال تہٕ سُہ آو کیمہٕ کھٮ۪تھ تہٕ ترووُن بھوت۔\n24.\\tمگر خدایہ سُند کلام گۆو بڑیوو تہٕ بڑیوو۔\n25.\\tتہٕ برنباس تہٕ ساؤل آو یروشلم پیٹھٕ واپس، ییلہ تِمو پنٕنۍ وزارت پوٗرٕ کٔر، تہٕ پانس سٍتـ̡ نِیہِ یوحنا، یٔمۍ سٕنز کنیت مرقس ٲس۔ {وزارت: یا، چارج}","1. وۅنۍ ٲس کلیساہس منز یُس انطاکیہ ہس منز اوس، کینہہ پیغمبر تہٕ استاد ٲسۍ۔ یُس برنباس، تہٕ شمعون یتھ نائیجر وننہٕ اوس یوان، تہٕ لوسیئس آف سائرین، تہٕ مانین، یُس ہیرودیس ٹیٹرارکس تہٕ ساؤلس سٍتۍ پرورش اوس آمُت کرنہٕ۔ {کُس...: یا، ہیرودس سُند وۄرٕ بوے }\n2. یێلہِ تِمو خداوند سٕنز خدمت کٔرِتھ روزٕ تھوو، روح القدس ووٚن زِ مے کٔرِو برنباس تہٕ ساؤل الگ کامہِ خٲطرٕ یێمہِ خٲطرٕ مے تِمن بُلاونہٕ آمُت چُھ۔\n3.\\tتہٕ ییلہ تِمو روزٕ تہٕ دُعا کٔرِتھ تہٕ تِمن پیٹھ اتھہٕ تھوو، تِمو سوٗزِ۔\n4. یێمہِ سٍتـ̡ گۆو تِم روح القدس سٕندِ طرفہٕ سوزنہٕ آمٕتۍ، سٍتـ̡ روانہٕ سیلیوسیا کُن۔ تہٕ تتہٕ پیٹھہٕ دراو تم قبرص کُن۔\n5. تہٕ ییلہ تِم سلامیس مَنٛز ٲسۍ، تِمو کٔر یہودین ہٕندِس عبادت خانن مَنٛز خدایہِ سُند کلام تبلیغ کرنہٕ۔\n6.\\tتہٕ ییلہ تِم جزیرٕ کِنۍ پافوس کُن گٔیہِ، تِمو وُچھ اکھ خاص جادوگر، اکھ اپُز پیغمبر، اکھ یہوُد، یٔمۍ سُند ناو اوس بارجیس:\n7.\\tیُس ملکُک نائب سرجیئس پالس سٍتۍ اوس، یُس اکھ ہوشیار انسان اوس۔ یُس برنباس تہٕ ساؤل منگوو، تہٕ خدایہ سُند کلام بوزُن یژھان۔\n8.\\tمگر ایلیماس جادوگر (تکیازِ تسند ناو تہِ چھہ تشریح) تمن مقابلہ کٔرِتھ نائب عقیدہ نشہِ دور کرنچ کوشش کران۔\n9. پَتہٕ ساؤل، (یُس روٝحہِ پاک سٍتـ̡ بٔرِتھ چُھہ ساؤل، یُس روح القدس سٍتـ̡ بٔرِتھ چُھ، تێلہِ کٔر أمِس کُن نظر،\n10.\\tتہٕ وونُن، اے سارِوٕے نزاکت تہٕ شرارت سٍتـ̡ بٔرِتھ، {ژے} شیطان سٕندِ شُر، {ژے} تمام نیکی ہُند دُشمن، کیا ژٕ کٔرِکھ نہٕ خداوند سٕنزِ صحیح وتہٕ سٍتـ̡ گُرِ وتہٕ سٍتـ̡ رُکاونہٕ یِنہٕ؟\n11. تہٕ وُچھ، خداوند سُند اَتھٕ چُھہ توے پیٹھ، تہٕ ژے گژھِو انہِ گٔژھِتھ، یێلہِ کُنہِ کالس تام آفتاب وُچھِتھ نہٕ۔ تہٕ یکدم پیوٚو تس پیٹھ اکھ وُنُل تہٕ اکھ انہِ گوٚٹ۔ تہٕ سُہ ژھانڈان کینہہ اتھہٕ رٔٹِتھ رٔٹِتھ۔\n12.\\tامہ پتہ ییلہ تٔمۍ وُچھ یہِ سپدُن، سُہ گوو خداوند سٕندِس نظریہس پیٹھ حٲران گژھِتھ پژھ۔\n13.\\tوۅنۍ ییلہ پولس تہٕ تٔمۍ سٕنز کمپنی پافوس نشہِ آزاد گٔیہ، تِم آیہ پامفیلیا کِس پرگا کِس نِش تہٕ یوحنا آو یِمو نِش نیرِتھ یروشلم واپس۔\n14.\\tمگر ییلہ تِم پرگا پیٹھٕ نیرِ، تِم آیہِ پِسیڈیا کِس انطاکیہ کِس تہٕ سبت دۅہہٕ گٔیہِ یہودی عبادت خانس مَنٛز، تہٕ بیوٹھ ۔\n15.\\tشریعت پرنہٕ پتہٕ تہٕ پیغمبرن ہٕندِس بادشاہو سوٗزۍ تِمن نِش، یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہِ لُکن ہٕندِ خٲطرٕ کانہہ نصیحت آسہِ، تیٚلہِ کٔرِو وَنُن۔\n16.\\tپَتہٕ ووٚتھ پولس تھوٚد تہٕ اَتھٕ سٍتـ̡ اشارٕ کٔرِتھ وونُن، اِسرٲیلٕکۍ انسان، تہٕ یُس خدایہِ سٍتـ̡ ڈران چُھ، دِیُن بوزناوُن۔\n17.\\tاَمہِ اسرٲیلٕکِس لُکہٕ سٕندِس خداہَن چُھ سانین آبن ہُند انتخاب تہٕ لُکن ہُند تھدِ پٲٹھـ̡ بٔنِتھ کٔرِن تِم اَمہِ منزٕ نیبر۔\n18.\\tتہٕ ژتٲجی ؤرین ہٕندِس زمانس منز گٔیہِ تِمن ہٕندِس آداب سٍتـ̡ تِمن ہٕندِس آداب سٍتـ̡ دِنہٕ۔ {تکلیف...: یا بور کٔرِتھ، یا تمن کھیٚوان یتھہ پاٹھۍ اکھ نرس پننس بچس پیدہ کران چھ، یا کھیوٚن دِوان}\n19.\\tتہٕ ییلہ تٔمۍ چانان کِس سرزمینس مَنٛز سَتھ مُلکہٕ تباہ کٔرۍ، تٔمۍ کٔر تِمن ہٕنز زمین قرعہ اندازی سٍتـ̡ تقسیم۔\n20.\\tتہٕ اَمہِ پَتہٕ دِژ تِمن ژۅن ہتھ پنژاہ ؤرین ہٕندِس وقتس مُتعلِق سموئیل پیغمبرس تام۔\n21.\\tتہٕ امہ پتہ کٔر تِمو أکِس بادشاہس سٍتـ̡ خٲہش۔ تہٕ خداین دیُت تِمن سِس سُند نیچو ساؤل، یُس بنیامین سٕندِس قبیلُک اکھ شخٕص اوس، ژتٲجی وُہرۍ دِنہٕ۔\n22. تہٕ ییلہ تٔمۍ سُہ ہٹٲو، تٔمۍ تھوٚد تِمن نِش تِہُند بادشاہ بننہٕ خٲطرٕ۔ یٔمِس تہِ گوٲہی دِژ تہٕ وونُن، مے لوٚب داؤد یسی سُند نیچو، یُس میانہِ دِلہٕ پٲٹھۍ، یُس میانہِ سارِنٕے مرضی پورٕ کرِ۔\n23. أمِس انسان سٕندِ اولادٕ سٍتـ̡ چُھ خدا سٕندِس وعدس مُطٲبق اسرٲیلس سٍتـ̡ نجات دِنہٕ وول عیسیٰ مسیح پٲدٕ کورمُت:\n24. یێلہِ یوحنا سٕندِس یِنہٕ برونہہ، سارِنٕے اسرٲیلِس سٍتـ̡ توبہ کرنُک بپتسمہ دِنٕچ تبلیغ کٔر۔\n25.\\tتہٕ یوحنا پَنُن وَتھ پوٗرٕ کٔرِتھ ووٚنُن، تۅہہِ کُس چُھس باسان زِ بہٕ چُھس؟ بہٕ چُھس نہٕ {he}۔ مگر وچھ میہ پتہ چھہ اکھ یوان یمۍ سٕندِ کھۅرن ہٕندِس کھورِ ہُند بہٕ چھُس نہٕ یِمن ہٕندِس کھورِ\n26. انسانو {تہٕ} بٲے ، ابراہیم سٕندِ اولاد ، تہٕ یُس تہٕ یُس تہٕ یُس تہٕ خدایہِ سُند خوف چُھ، تۅہہِ خٲطرٕ چُھ امہِ نجات ہُند کلام سوزنہٕ آمُت۔\n27.\\tیِم یُس یروشلمس مَنٛز روزان چُھ، تہٕ تِمن ہٕندِس حُکُمرن ہٕندِس حُکُمران، تِکیازِ تِم ٲس نہٕ أمِس زانان تہٕ توتہِ چھِ پیغمبرن ہٕنزِ آوازٕ یِم پرٮ۪تھ سبت دۅہہٕ پرنہٕ یوان چھِ، تِمو چُھ تِمن ہٕنز مذمت کٔرِتھ پورٕ کٔرمٕژ۔\n28.\\tتہٕ یێلہِ تِمو لوٚب نہٕ أمِس مَرُنُک کانہہ وجہ، توتہِ اوس تِمو پیلاتس یژھان زِ سُہ گژھہِ مارنہٕ یُن۔\n29.\\tتہٕ ییلہ تمو أمس متعلق لیکھنہٕ آمُت سورُے پورٕ کٔر، تمو کُلِس پیٹھٕ بۄن تہٕ تھووُکھ قبرس مَنٛز۔\n30.\\tمگر خداین کٔر سُہ مُردٕ منزٕ زندٕ:\n31. تہٕ سُہ آو واریاہن دۅہن وُچھنہٕ یِم أمِس سٍتـ̡ گلیل پیٹھٕ یروشلم تام وٲتِتھ، یِم لُکن ہٕندِ خٲطرٕ تٔمۍ سٕندِ گواہ ٲسۍ۔\n32. تہٕ أسۍ چھِ ژےٚ خوشخبری دِوان زِ سُہ وعدٕ یُس مٲلِس سٍتـ̡ اوس کرنہٕ آمُت،\n33. خداین چُھ اسہِ تہندِ شُرین سٍتـ̡ یۅہے پورٕ کورمُت، یێلہِ سٍتـ̡ تٔمۍ کٔر عیسیٰ مسیح دُبارٕ زندٕ۔ یِتھ کٔنۍ زَن دٔیمِس زبورس مَنٛز تہِ چُھہ لیکھنہٕ آمُت، ژٕ چُھہ میون نیٚچُو، اَمہ دۅہہ چُھہ مے ژے زامُت۔\n34.\\tتہٕ یێلہِ زِ تٔمۍ دِژ سُہ مُردٕ پى۪ٹھہٕ زندٕ، {وُن} وُنہِ تہِ دِیہِ نہٕ دَوُد سٕنز رحمت۔ {رحمت: Gr. مقدس، یا صرف چیز: کُس لفظ Septuagint چُھ واریاہن جاین استعمال کران یُس عبرانی زبانہِ منز چُھ، رحمت}\n35. اَمہِ مۄکھٕ چُھ سُہ بییِس {زبور} مَنٛز تہِ ونان زِ ژے گژھ نہٕ پَنُن مُقدسَس بد عنوانی وُچھنُک اِجازت دِنہٕ۔\n36.\\tداؤد سٕندِ خٲطرٕ، ییلہ تٔمۍ خدایہ سٕنزِ مرضی سٍتـ̡ پننہِ نسلہِ ہٕنز خدمت کٔر، نندر گۆو تہٕ سُہ آو پننین مٲلن نِش تھونہٕ، تہٕ وُچھُن بدعنوانی: {پَتہٕ...: یا، ییلہِ تٔمۍ پننہِ وٲنسہِ منز خدایہ سٕنزِ مرضی ہٕنز خدمت کٔر}\n37.\\tمگر یُس خداین دُبارٕ دُبارٕ زندٕ کٔرِتھ وُچھ نہٕ کانہہ بدعنوانی۔\n38.\\tتێلہِ گژھہِ تۅہہِ یہ زانن زِ یێمہِ انسانہٕ سٍتـ̡ چُھہ تۅہہِ گۅنہن ہٕنز معٲفی دِنہٕ آمٕژ:\n39. تہٕ تٔمۍ سٕندِ ذریعہٕ چھ تمام ایمان تھاون وٲل تمام چیزن سٍتـ̡ راستی حٲصل سپدان، یێمہِ سٍتـ̡ موسیٰ سٕندِ شریعت سٍتـ̡ ہێکہِ نہٕ تۅہہِ انصاف سپدِتھ۔\n40. تێمہِ کِنۍ گژھہِ خبردار یُس تۅہہِ پیٹھ یُس پیغمبرن منز وننہ آمت چھُ۔\n41.\\tوُچھو، اے حقیر تہٕ حیران، تہٕ فنا گژھُن، کیازِ بہٕ چُھس تہندِس دۅہس منز اکھ کٲم کران، یُس نہٕ تۅہہ کُنہِ تہِ پژھ کٔرِتھ، یُس نہٕ کانہہ تہِ انسان تہِ اعلان کرِ۔\n42. تہٕ ییلہِ یہودی یہودی عبادت خانہٕ منزٕ نیبر نیرِ، غیر قومن کٔر التجا زِ یِم کلام یِن تِمن بیٚیِس سبت دوہ پرناونہٕ۔ {بیاکھ ...: Gr. درمیانی ہفتس منز، یا سبت درمیان درمیان}\n43.\\tییلہ جماعت پھُٹاونہٕ آیہ، واریاہ یہودی تہٕ مذہبی پیروکار گٔیہِ پولس تہٕ برنباس سٕنزِ پٲرو، یِمو تِمن سٍتـ̡ کتھ کٔرِتھ خدایہ سٕندِس فضل سٍتـ̡ جٲری روزنس پیٹھ آمادہ کٔر۔\n44. تہٕ دوٚیِم سبت دۅہ آو تقریباً سٲرۍسٕے شہرس خدایہ سُند کلام بوزنہٕ خٲطرٕ۔\n45.\\tمگر ییلہ یہودیو ہجوم وُچھ، تِم گٔیہِ حسد تہٕ تِمن چیزن خلاف کتھ کٔرِتھ یِم پولس کٔرِتھ تہٕ کُفر کٔرِتھ کٔرِتھ۔\n46.\\tپَتہٕ ووت پولس تہٕ برنباسن ہُند کلام تہٕ وونُن، یہ اوس ضروری زِ خدایہ سُند کلام گژھہِ گۅڈٕ ژے سٍتـ̡ وننہٕ یُن، مگر یہ وُچھِتھ زِ تہٕ پانس ہُند کلام دِیُن ابدی زندگی ہٕندِس لایق قرار دِنہٕ، یێلہِ أسۍ غیر قومن کُن پھیرِ۔\n47. یِتھٕ پٲٹھۍ چُھ خداوند اسہِ حُکُم دِژمُت، {وَنُن}، بہٕ چُھہ ژے غیر قومن ہُند گاش بنوومُت، یُتھ زِ ژٕ گژھہِ زمینہِ ہٕندِس اندس تام نجات دِنہٕ خٲطرٕ۔\n48.\\tتہٕ یێلہِ یہِ بوٗز تِمو گٔیہِ خۅش تہٕ کٔرٕکھ خداوند سٕندِ کلامٕچ حمد تہٕ یِمن ہٕندِس کُنہِ ہُند حکم دِنہٕ آمُت اوس، تِمو کٔر ایمان۔\n49.\\tتہٕ خداوند سُند کلام آو سٲرۍسٕے علاقس منز شایع کرنہٕ۔\n50.\\tمگر یہودیو کٔر دیندار تہٕ معزز زنانن تہٕ شہرٕکۍ سرکردہ مرد ہنگامہ تہٕ پولس تہٕ برنباسس خلاف کٔرٕکھ ظلم تہٕ کٔرِکھ تِم پننیو ساحلو نِش نٮ۪بر کٔرِتھ۔\n51.\\tمگر تِمو ژٔٹۍ پننین کھۅرن ہٕنز گرد پانس نِش تہٕ آیہِ اِکونیمس کُن۔\n52.\\tتہٕ شٲگِر گٔیہِ خوشی سٍتـ̡ تہٕ روح القدس سٍتـ̡ بٔرِتھ۔","1. تہٕ یہ سپد آئیکونیمس مَنٛز زِ تِم گٔیہِ دۅشوے اِکہٕ وٹہٕ یہودین ہٕندِس عبادت خانس مَنٛز، تہٕ یِتھٕ پٲٹھۍ کٔرٕکھ یہودی تہٕ یونانین ہٕندِس بٔڈِس تعدادس منز پژھ۔\n2.\\tمگر کافر یہودیو کٔر غیر قومن ہٕندِس دِلچس، تہٕ بٲے سٍتـ̡ کٔرٕکھ تِمن ہُند ذہنُک بُرٕ مُتٲثِر۔\n3. تَمہِ کِنۍ روٗد واریاہس کالس روزان تِم خداوند سٕندِس کلامَس مَنٛز دِژ دِنہٕ، یٔمۍ تٔمۍ سٕندِس فضل کِس کلامٕچ گوٲہی دِژ، تہٕ تِہندِ اتھو سٍتـ̡ کرنہٕ خٲطرٕ نشانہٕ تہٕ عجائب دِژٕ۔\n4. مگر شہرُک بٔڈ تعداد آو تقسیم کرنہٕ: تہٕ کُنہِ حِصہٕ آو یہودین سٍتـ̡ تہٕ رسولن سٍتـ̡ تقسیم کرنہٕ۔\n5.\\tییلہ دۅشوے غیر قومن تہٕ یہودین تہِ پننین حکمرانن سٍتـ̡ حملہٕ کرنہٕ آمُت، تہٕ تِمن سٍتـ̡ کٔرِتھ کٔرِتھ تہٕ تِمن کٔرِتھ\n6.\\tتِم گٔیہِ لِسٹرا تہٕ ڈربے کُن، لیکاونیا کین شہرن تہٕ اندۍ پٔکۍ علاقن کُن ژٔلِتھ:\n7. تہٕ تتہِ کٔر تِمو انجیل ہٕنز تبلیغ ۔\n8.\\tتہٕ اَکھ شخٕص بِہتھ لِسٹراہس منز، یُس پننہِ ماجہ ہٕندِس کُنہِ ہُند پَکُن اوس نہٕ۔\n9.\\tیێہے بوز پولس سٕنز کتھ یُس أمِس وُچھِتھ تہٕ وُچھِتھ تہٕ وُچھِتھ زِ أمِس چھُ شفا پٲٹھۍ،\n10.\\tبَڑِ آوازِ سٍتۍ وَنُن زِ کھٔرِتھ کھٔسِو۔ تہٕ تٔمۍ ووٚتھ وۄٹھ تہٕ پوٚک۔\n11. تہٕ ییلہ لوکو وُچھ پولس کیا اوس کوٚرمت، تِمو کٔر پنٕنۍ آواز تُل، لیکاونیا سٕندِس کلامس مَنٛز وونُن زِ دیوتا چِھ انسانن ہٕندِس شکلہٕ سٍتـ̡ اسہِ نِش آمٕتۍ۔\n12. تہٕ تِمو وُن برنباس، مشتری۔ تہٕ پال، مرکوریئس، تکیازِ سُہ اوس چیف سپیکر۔\n13. تمہ پتہ مشتری ہند پادٕر، یُس تہندِس شہرس برونہہ کنہِ اوس، اوٚن بیل تہٕ مالہٕ دروازن تام، تہٕ لوکن سٍتـ̡ کٔرِن قربانی۔\n14.\\tییلہ رسولو برنباس تہٕ پولس بوز، تِمو کٔر پَنٕنۍ پلو ژٔٹِتھ تہٕ لُکن مَنٛز ژٔلِتھ دِژٕکھ کرٛٮ۪کھ،\n15.\\tتہٕ وَنُن زِ جناب، یِم کیازِ چھِو یِم کَتھٕ کٔرِتھ؟ أسۍ تہِ چھِ تۅہہِ سٍتـ̡ یِتھۍ جذباتن ہٕندِس انسانس سٍتـ̡ تہٕ تۅہہِ سٍتـ̡ یِمن باطل نشہِ زندٕ خدایہ سٍتـ̡ پھیرُن، یٔمۍ اسمان، زمینہٕ، سمندر، تہٕ اَتھ مَنٛز موجود سارِنٕے چیزن ہُند بنوومُت چھُ۔\n16. یِمو پتھ کالس منز سارنٕے قومن پنٕنـ̡ پَنٕنـ̡ پٲٹھـ̡ پَکُن پَکُن دِنہٕ آمُت۔\n17. توتہِ تروو نہٕ تٔمۍ پنُن پان گواہ ورٲے تہٕ دِژُن اسمانہٕ سٍتـ̡ روٗد تہٕ پھلدار موسم، تہٕ دِژُن سانہِ دِل کھیٛنہٕ تہٕ خوشی سٍتـ̡ بٔرِتھ۔\n18.\\tتہٕ یِمو کلامَو سٍتـ̡ رُکٲوِتھ لُکھ زِ تِمو ٲس نہٕ تِمن خٲطرٕ قربانی دِژمٕژ۔\n19.\\tتہٕ اتہِ آیہِ انطاکیہ تہٕ آئیکونیم پیٹھٕ {یقین} یہودی، یِمو لُکن رٲضی کٔرِتھ، تہٕ پولس کٔرِتھ کٔرِکھ شہرٕ منزٕ نٮ۪بر، یہِ خیال کٔرِتھ زِ سُہ چُھ موٗدمُت۔\n20.\\tیێلہِ ییلہ شٲگِر أمِس اندۍ پکھۍ کھڑا گٔیہِ، سُہ ووٚتھ تہٕ ووت شہرس مَنٛز، تہٕ دوٚیمہِ دۅہہ دراو سُہ برنباس سٍتـ̡ ڈربے کُن۔\n21. تہٕ ییلہ تِمو اتھ شہرس مَنٛز انجیل ہٕنز تبلیغ کٔر، تہٕ واریاہن ہیچھناوٕن، تِم گٔیہِ دُبارٕ لِسٹرا کُن واپس، تہٕ اِکونیمس تہٕ انطاکیہ کُن، {واریاہ ہیٚچھناوٕنۍ: Gr. اوس واریاہ شٲگِرِد بنٲومٕتۍ}\n22. شاگردن ہٕنزِ روحن ہٕنز تصدیق کرٕنۍ، تہٕ تِمن ایمانس منز روزنٕچ تلقین کرٕنۍ، تہٕ یہ زِ اسہِ پزِ واریاہ مصیبت سٍتـ̡ خدایہ سٕندِس بادشاہتس مَنٛز دٲخل گژھُن۔\n23. تہٕ یێلہِ تِمو تِم پرٮ۪تھ کلیساہس مَنٛز بزرگ مقرر کٔرِتھ، تہٕ روزٕ سٍتـ̡ دُعا کٔرِتھ، تِمو کٔر تِمن خداہس سٍتـ̡ یٔمِس پى۪ٹھ۔\n24.\\tتہٕ ییلہ تِم پِسیڈیا سٲرۍسٕے پِسیڈیا گٔژھِتھ گٔیہِ، تِم آیہ پامفیلیا کُن۔\n25.\\tتہٕ ییلہ تِمو پرگاہَس مَنٛز کلام تبلیغ کٔر، تِم گٔیہِ اٹالیاہس مَنٛز:\n26. تہٕ اَمہِ پَتہٕ گٔیہِ انطاکیہ کُن سفر، ییتہِ تِمن کامہِ خٲطرٕ خدایہ سٕندِس فضل سٍتـ̡ سفارش کرنہٕ آمٕژ ٲس یُس تمو پوٗرٕ کٔر۔\n27. تہٕ ییلہ تِم آیہ، تہٕ کلیساہٕ جمع کٔرِتھ، تِمو کٔر تِمن سٍتـ̡ یُس خداین سٍتـ̡ کورمُت اوس، تہٕ کِتھہ پٲٹھـ̡ اوس تٔمۍ غیر قومن ہٕندِ خٲطرٕ ایمانُک دروازٕ کھولمُت۔\n28.\\tتہٕ اَتہِ روٗد تِم واریاہس کالس شٲگِرَن سٍتـ̡ روزان۔","1.\\tتہٕ یُس یہوداہ پیٹھٕ وسان اوس، تِمو ہیچھناوُن بٲے {تہٕ وونُن}، یوتام نہٕ تۅہہ موسیٰ سٕندِ طریقس پٲٹھـ̡ ختنہ کرنہٕ ییہِ، تۅہہِ ہیٛکو نہٕ نجات دِتھ۔\n2. یێلہِ پولس تہٕ برنباسس سٍتـ̡ کانہہ لۄکُٹ اختلاف تہٕ اختلاف سپُد، تِمو کوٚر طے زِ پولس تہٕ برنباس تہٕ یِمو منزٕ کینہہ باقٕے یِمن ہٕندِس سوالس مُتلق رسولن تہٕ بزرگن نِش گژھن یروشلمس تام۔\n3. تہٕ کلیساہٕ کہِ طرفہٕ اننہٕ پتہٕ گٔیہِ تِم فینیس تہٕ سامریہ کِنۍ، تہٕ یِمو کٔر سارِنٕے باین ہٕندِ خٲطرٕ سٮ۪ٹھاہ خوشی۔\n4. تہٕ ییلہ تِم یروشلم آیہ، تِم آیہ کلیساہٕ تہٕ رسولن تہٕ بزرگن ہٕندِ طرفہٕ استقبال کرنہٕ، تہٕ تِمو کٔر تِمن سارِنٕے چیزن ہُند اعلان یُس خداین تِمن سٍتـ̡ کورمُت۔\n5.\\tمگر فریسیین ہٕندِس فرقس سٍتـ̡ ووت یُس یقین اوس تھاوان زِ تِمن ہُند ختنہ کرُن چُھہ ضروری، تہٕ موسىٰ سٕندِس شریعتس پیٹھ عمل کرنُک حُکُم دِنہٕ چُھ۔ {گلاب...: یا، ووٚتھ، تمو ووٚن، یقین}\n6.\\tتہٕ رسولن تہٕ بزرگن گٔیہِ اَتھ معاملس پیٹھ غور کرنہٕ خٲطرٕ اِکہٕ وٹہٕ۔\n7. تہٕ ییلہ واریاہ اختلاف سپدِ، پطرس ووٚتھ تہٕ تِمن ووٚنُن، انسانو {تہٕ} بٲے، تہٕ تۅہہ چُھہ پتاہ زِ خداین کِتھہ پٲٹھـ̡ چُھہ اسہِ منزٕ ژٲرمُت، زِ غیر قومن گژھن میانہِ ٲسِس سٍتـ̡ انجیل ہُند کلام بوزُن تہٕ پژھ پٲٹھۍ۔\n8. تہٕ خدا، یُس دِل زانان چُھ، تِمن ہٕنز گواہی دِیُن، یِتھٕ پٲٹھـ̡ تٔمۍ اسہِ سٍتـ̡ روٝحہِ پاک دِژمُت، یێلہِ سٍتـ̡ تٔمۍ اسہِ سٍتـ̡ دِژمُت چُھ۔\n9. تہٕ اسہِ تہٕ تِمن درمیان تھاوُن نہٕ کانہہ فرق، تہٕ ایمان سٍتـ̡ تِہُند دِل پاک کرُن۔\n10.\\tتێلہِ کیازِ چُھہ خدایہِ شٲگِرَن ہٕنزِ گردنہِ پیٹھ جوہ لاگُن، یُس نہ سانہِ مٲلۍ سٕندِس باپ سٍتـ̡ تہٕ أسـ̡ ہیوٚک۔\n11. مگر أسـ̡ چُھہ یقین تھاوان زِ خداوند عیسیٰ مسیح سٕندِ فضل سٍتـ̡ گژھہِ أسـ̡ نجات دِنہٕ۔\n12.\\tاَمہ پتہٕ کٔر سارِوٕے ہجوم ژھۄپہٕ، تہٕ دِتُکھ برنباس تہٕ پولس سٍتـ̡ یہ اعلان زِ خداین کُس معجزہٕ تہٕ عجائب چھُ یِمو دٔسۍ غیر قومن مَنٛز کٔرمٕتۍ۔\n13.\\tتہٕ یِمو خاموش گژھنہٕ پتہٕ، یعقوبن دیُت جواب دِتھ وونُن، انسانو {تہٕ} بٲے، بوزو میانہِ کُن:\n14.\\tشمعون چُھ اعلان کوٚرمُت زِ کِتھ پٲٹھـ̡ چُھ خداین گوڈنِچہِ لٹہِ غیر قومن نِش یِمن نِش اکھ لُکھ نِنہٕ خٲطرٕ۔\n15.\\tتہٕ اَتھ سٍتـ̡ چُھہ پیغمبرن ہٕندِس کلامس سٍتـ̡ اتفاق سپدان۔ یِتھ کٔنۍ زَن یہِ لیٚکھنہٕ آمُت چھُ،\n16.\\tامہ پتہ گژھہِ بہٕ واپس، تہٕ دُبارٕ داؤد سُند خیمہ بناوُن، یُس پیوٚو پیوٚو۔ تہٕ بہٕ بناوٕ امکۍ کھنڈرات دوبارٕ، تہٕ بہٕ کرٕ یہ قٲیم:\n17.\\tیُتھ زِ انسانس ہٕندِس باقیاتس سٍتـ̡ خداوند سٕندِس سٍتـ̡ تہٕ سارِنٕے غیر قومن ہٕندِس سٍتـ̡ یِمن پیٹھ میون ناو وننہٕ چُھ، خداوند چُھ ونان یُس یِم سارِنٕے کامہِ کران چُھ۔\n18.\\tخدایس سٍتـ̡ چُھہ دنیا کِس ابتداہس پیٹھے تٔمۍ سٕنزِ سٲری کٲم زانان۔\n19. اَمہِ مۄکھٕ چُھ میون جملہٕ یہِ زِ أسۍ نہٕ تِمن پریشان کٔرِتھ، یِم غیر قومن مَنٛز خدایہِ سٍتـ̡ پھیران چھِ:\n20.\\tمگر یہ زِ أسۍ چھِ تِمن لیکھان زِ تِم روزن بُتن ہٕنزِ آلودگی، تہٕ زناکاری نِش، تہٕ گُلہٕ دِنہٕ نشہِ تہٕ خونس نِش پرہیز کٔرِتھ۔\n21.\\tپرٲنِس زمانس مَنٛز چُھ موسیٰ سٕندِس پرٮ۪تھ شہرس مَنٛز تِم تِم یِم تٔمِس تبلیغ کران چھِ، یِم پرٮ۪تھ سبت دۅہہٕ عبادت خانن مَنٛز پرنہٕ یوان چھِ۔\n22. اَمہِ پَتہٕ کٔرٕکھ رسولن تہٕ بزرگن سٲرۍسٕے کلیساہس سٍتـ̡ پولس تہٕ برنباسس سٍتـ̡ پنٕنـ̡ سٍتـ̡ منتخب نفر انطاکیہس کُن سوزنہٕ۔ {یعنی}، یہوداہ کنیت برساباس، تہٕ سیلاس، بٲے مَنٛز اہم شخص:\n23.\\tتہٕ یِمو لیکھۍ یِتھٕ پٲٹھۍ تِمو {چِٹھۍ}۔ رسول، بزرگ تہٕ بٲے چھِ انطاکیہیہ، شام تہٕ سیلیشیاہس مَنٛز غیر قومن ہٕندِس بٲے سٍتـ̡ سلام کٔرِتھ:\n24.\\tیُتھ زن اسہِ بوزمُت چُھ، یُس اسہِ نِش نیران چُھ، یُس اسہِ نِش دِنہٕ آمُت چُھ، تُہٕندِس روحس سٍتـ̡ ژٔٹِتھ دِژمُت، تہٕ وَنُن زِ {یێلہِ} گژھہِ ختنہ کرنہٕ یُن، تہٕ شریعت تھاوُن:\n25.\\tیِہ اوس اسہِ خٲطرٕ اصل باسیومُت، یُس اَکہٕ وِزِ سٍتـ̡ سٍتـ�\n26. تِم انسان یِمو سٲنِس آغہٕ عیسیٰ مسیح سٕندِ ناوٕ خٲطرٕ پَنٕنۍ جان خطرس منز ترٛٲومٕژ۔\n27.\\tاسہِ چُھ یہوداہ تہٕ سیلاس سوزمُت، یُس تہِ یۅہے کتھ زٲنِتھ وَنُن۔ {ٲس: Gr. word}\n28.\\tتکیازِ روح القدس، تہٕ اسہِ خٲطرٕ اوس یہ جان باسان زِ یِمو ضروری چیزو کھۅتہٕ زیادٕ بوجھ۔\n29.\\tیُس تُہۍ بُتن دِنہٕ آمتِس مازس نِش پرہیز کٔرِو، تہٕ خونس نِش تہٕ گُلہٕ دِنہٕ آمٕتۍ چیزن نِش تہٕ زناکاری نِش پرہیز کٔرِو۔ رژھ رژھ رژھ۔\n30. یێلہِ یێلہِ تِم خٲرج کٔرِتھ، تِم آیہِ انطاکیہ کُن، تہٕ ییلہ تِمو ہجوم جمع کٔرِتھ، تِمو واتنوو یہِ چُھ:\n31.\\t{یُس} ییلہ تمو پٔرۍ، تِمو گٔے تسلی دِنہٕ خٲطرٕ خوش۔ {تسلی : یا، نصیحت}\n32.\\tتہٕ یہوداہ تہٕ سیلاس تہِ پیغمبرن ہٕندِ آسنہٕ کِنۍ کٔرٕکھ بٲے سٍتـ̡ نصیحت تہٕ تصدیق کٔرِتھ۔\n33.\\tتہٕ ییلہ تِم أکِس جایہ روزِ، تِم آیہ بٲے سٍتـ̡ رسولن تام امن سان تراونہٕ۔\n34.\\tامہ باوجود سپد سیلاس اتہِ روزُن خۅش۔\n35. پولس تہٕ برنباس تہِ رودۍ انطاکیہس مَنٛز تہٕ باقین واریاہن سٍتـ̡ خداوند سُند کلام پرناوُن تہٕ تبلیغ کران۔\n36. تہٕ کینژو دۅہہ پۯاوٕ پۯاوُن تہٕ پۯاوُن پریتھ شہرس مَنٛز پننین باین نِش یتہِ أسـ̡ خداوند سٕندِ کلامٕچ تبلیغ کٔرمٕژ چِھ، {تہٕ وُچھِو} تِم کِتھہٕ پٲٹھـ̡ چِھ کران۔\n37. تہٕ برنباسن کوٚر پانس سٍتـ̡ جان نِنُک ارادٕ، یٔمۍ سٕنز کنیت مرقس ٲس۔\n38.\\tمگر پولس سونچ نہٕ تس پانس سٍتـ̡ نِن، یُس تِمن نِش پامفیلیا پیٹھٕ نیرِ، تہٕ گۆو نہٕ تِمن سٍتـ̡ کامہِ خٲطرٕ۔\n39.\\tتہٕ یِمن درمِیان اوس تنازعہ تیوت تیز زِ تِم گٔیہِ اَکھ أکِس نِش الگ الگ تہٕ یِتھٕ کٔنۍ نِش تہٕ دراو قبرص کُن۔\n40. تہٕ پولس کوٚر سیلاسُک انتخاب، تہٕ درٛاو خدایہ سٕندِ فضل سٍتـ̡\n41. تہٕ سُہ گۆو شام تہٕ سیلیشیا کِنۍ، کلیساہَن ہٕنز تصدیق کٔرِتھ۔","1.\\tپَتہٕ آو سُہ ڈربے تہٕ لِسٹرا کُن: تہٕ وُچھِتھ اوس اَکھ خاص شٲگِر، یُس تِموتھیس ناو اوس، یُس أکِس زنانہِ ہُند نیچو اوس، یُس یہودی ٲس، تہٕ اوسُس پژھ تھاوان۔ مگر تٔمۍ سُنٛد مول اوس یونانی:\n2.\\tیُس لسٹرا تہٕ آئیکونیمس منز موجود بٲیو ہٕندِ طرفہٕ اصل پٲٹھۍخبر دِنہٕ آمُت۔\n3. پولس گژھہِ تس سٍتـ̡ نیرُن۔ تہٕ تِمن یہودین ہٕندِ وجہ سٍتـ̡ رٔٹِتھ ختنہ کٔرِتھ یِمن ہٕندِس مَنٛز ٲس، تِکیازِ تِمن ٲس سارِنٕے زانان زِ تٔمۍ سُند مول اوس یونٲنی۔\n4. تہٕ ییلہ تِم شہرن مٔنزۍ گٔژھۍ، تِمو واتنوو تِمن رژھراونہٕ خٲطرٕ احکام، یِم یروشلمس مَنٛز رسولن تہٕ بزرگن ہٕندِ طرفہٕ مقرر کرنہٕ آمٕتۍ ٲسۍ۔\n5. تہٕ یِتھٕ کٔنۍ گٔیہٕ کلیساہٕ عقیدس مَنٛز قایم کرنہٕ، تہٕ روزانہٕ دۄہ گٔیہٕ تعدادس منٛز اضافہٕ۔\n6. وۅنۍ ییلہ تِم فریجیا تہٕ گلتیہ کِس علاقس منز گٔژھمٕتۍ، تہٕ روٝحہِ پاک سٕندِ طرفہٕ آیہ ایشیاہس مَنٛز کلام تبلیغ کرنہٕ خٲطرٕ منع کرنہٕ،\n7.\\tییلہ تِم میسیا وٲتِتھ، تِمو کٔر بتھینیاہس مَنٛز گژھنٕچ کوشش، مگر روحن دِژ نہٕ تِمن دِنہٕ۔\n8.\\tتہٕ تِم گٔیہِ میسیا کِنۍ گٔژھِتھ ٹرواس کُن۔\n9. تہٕ رٲژ آو پولس اکھ وژن ظٲہر۔ مقدونیہُک اکھ شخٕص کھڑا تہٕ أمِس دُعا کٔرِتھ وونُن زِ مقدونیہ اژُن تہٕ اسہِ مدد۔\n10. تہٕ ییلہ تٔمۍ یہ وژن وُچھ، اسہِ کٔر یکدم مقدونیہ گژھنچ کوشش، یٔقیٖنی طور جمع کٔرِتھ زِ خداوند اوس اسہِ تِمن انجیل ہنز تبلیغ کرنہٕ خٲطرٕ بُلاونہٕ آمُت۔\n11.\\tلہذا ٹرواس پیٹھہ ہارتھ ووت اسۍ سیود وتہِ سیود سموتھریشیا کُن تہ دوٚیمہِ دۅہہ نیپولس کُن۔\n12. تہٕ اَمہِ پَتہٕ فِلپی تام، یُس مقدونیہ کِس تتھ حصُک اہم شہر چُھ، {تہٕ} اکھ کالونی: تہٕ أسۍ ٲسۍ اَتھ شہرس مَنٛز کینژن دۅہن روزان۔ {سردار: یا، گۄڈنیُک}\n13.\\tتہٕ سبت دۅہہٕ دراو أسۍ شہرٕ نیبر أکِس دریاوٕ کِس بٹھہٕ کِنۍ، ییتہِ دُعا کرنہٕ یِوان اوس۔ تہٕ أسۍ بیوٹھ، تہٕ کٔرٕن تِمن زنانن سٍتۍ کتھ یِم {تتہِ} گٔیہِ۔ {سبت : Gr. Sabbath Day}\n14.\\tتہٕ لِڈیا ناوٕچ أکِس زنانہٕ، یۄس تھیتیرا شہرٕچ واگن رنگ کٕنَن واجنہِ ٲس، یۄسہٕ خدایہ سٕنز عبادت کران ٲس، بوز {اس}: یٔمۍ سُند دِل خداوند کھولُن، تہٕ سُہ کٔر تِمن چیزن سٍتـ̡ یِمن ہُند خیال اوس پولس سٍتـ̡ وننہٕ آمُت۔\n15. تہٕ ییلہ أمس بپتسمہ دِنہٕ آو، تہٕ تٔمۍ سٕندِس گرس سٍتـ̡ وۆنُن زِ یێلہِ تہٕ یێلہِ تہِ روزُن مُتعلِق۔ تہٕ تٔمۍ کٔر اسہِ مجبور۔\n16.\\tتہ سپد یہ سپدان، ییلہ أسۍ دعاہس منز گٔیہ، اکھ خاص لڑکی یۅسہٕ خدایی ہُند جذبہ تھاوان ٲس، ییمہ سٍتۍ پننین مالکن واریاہ فٲیدٕ میلہِ: {الہام ہُند: یا، ازگر سٕندِ}\n17.\\tیێہے گۆو پولس تہٕ اسہِ پٲٹھۍ، تہٕ وۆنُن زِ یِم لُکھ خدایہ سٕندِ خادم، یُس اسہِ نجات ہٕنز وتھ ہاوان چھُ۔\n18. تہٕ یہ کٔر أمس واریہن دۄہن ۔ مگر پولس، غمگین گژھتھ پھیُر تہٕ وونُن روحس کُن، بہٕ چُھس عیسیٰ مسیح سٕندِ ناوٕ سٍتـ̡ ژے حُکُم دِوان زِ سُہ گژھہِ أمِس نِش نیرُن۔ تہٕ سُہ آو أتھۍ گھنٹس نیبر۔\n19.\\tتہٕ ییلہ تٔمۍ سٕندِس مٲلکَو وُچھ زِ تِمن ہٕندِ فٲیدٕچ وۅمید چھیہ ختم، تِمو رٔٹِتھ پال تہٕ سیلاس رٔٹِتھ تہٕ رٔٹِتھ کٔرِکھ بازرِ منز حکمرانن نِش، {بازار: یا، دربار}\n20.\\tتہٕ أنِتھ تِم مجسٹریٹس نِش، یہودی آسنہٕ کِنۍ چھِ سٲنِس شہرس سٮ۪ٹھاہ پریشان کران،\n21.\\tتہٕ ہیچھناوُن رسم یُس نہٕ اسہِ خٲطرٕ حلال چھُ، تہٕ رومی آسنہٕ کِنۍ چھُنہٕ یِمن ہُند عمل کرُن۔\n22.\\tتہٕ ہجوم گٔیہِ یِمن خلاف اِکہٕ وٹہٕ، تہٕ مجسٹریٹو ژٔٹِتھ تہٕ دِتُکھ تِمن مارنُک حُکُم۔\n23.\\tتہٕ ییلہ تِمو تِمن پیٹھ واریاہ پٹۍ تھٲوِتھ، تِمو دِژ جیلس منز تہٕ دِژُکھ جیلس سٍتـ̡ یِمن ہُند حفاضت تھاونُک حکم دِنہٕ:\n24.\\tیُس یُتھ الزام رٔٹِتھ دِژُکھ تِم أنٛدرِمِس جیلس مَنٛز، تہٕ کٔرٕن پنٕنۍ کھۅر مٔنزۍ مَنٛز تیز ۔\n25.\\tتہٕ نصف رٲژ کٔر پولس تہٕ سیلاسن دُعا تہٕ خدایہ سٕندِ حمد گٮ۪وُن، تہٕ قٲدٮ۪و بوز تِم ۔\n26. تہٕ اچانک آو اکھ زبردست زلزلہٕ، یُتھ زن جیلٕچ بُنیاد لٔٹِتھ گٔیہٕ: تہٕ یکدم گٔیہٕ سٲری دروازٕ کھولنہٕ، تہٕ پرٮ۪تھ کٲنٛسہِ ہٕندِ بینڈ گٔیہٕ یلہٕ۔\n27.\\tتہٕ جیلُک رٲچھ کرن وول نیندٕ منزٕ بیدار سپدِتھ تہٕ جیلٕکۍ دروازٕ یلہٕ وُچھِتھ کٔڑِن تٔمۍ تلوار تہٕ مارُن پان تہٕ یہ خیال کٔرِتھ زِ قٲدۍ آسہٕ ژٔلۍمٕتۍ۔\n28.\\tمگر پولس وۆن بَڑِ آوازِ سٍتـ̡ وۆنُن، پانس کٔرِو نہٕ کانہہ نقصان ، کیازِ أسۍ سٲری چھِ یتہِ۔\n29.\\tتمہِ پَتہٕ وُپھ گاش منگُن، تہٕ ووت تھرتھرٲوِتھ تہٕ پولس تہٕ سیلاس برونہہ کُن پیوٚو۔\n30.\\tتہٕ وونُن تِم نٮ۪بر تہٕ وونُن، جناب، بہٕ کیا کرُن بچاونہٕ خٲطرٕ؟\n31. تہٕ تِمو ووٚن، خداوند عیسیٰ مسیحس پیٹھ یقین کرُن، تہٕ تُہۍ گژھہِ نجات تہٕ پنُن گر۔\n32. تہٕ تِمو کٔر أمِس سٍتـ̡ خداوند سُند کلام تہٕ تٔمۍ سٕندِس گرس مَنٛز موجود سارِنٕے سٍتـ̡ کتھ کرنہٕ۔\n33.\\tتہٕ تٔمۍ نِش رٲژ ہٕندِس أتھۍ وقتس منز، تہٕ لٔگِن تِمن ہٕندِس پٹِس واش کٔرِتھ۔ تہٕ آو بپتسمہ دِنہٕ، سُہ تہٕ تٔمۍ سٕندِس سارِنٕے سٍتـ̡ بپتسمہ دِنہٕ۔\n34. تہٕ ییلہ سُہ تِم پننِس گَرَس مَنٛز أنِتھ، تٔمۍ تھووُن تِمن برونہہ کُن ماز تہٕ کوٚرُن خدایس پیٹھ پژھ پٲٹھۍ۔\n35.\\tییلہ دۅہ آو مجسٹریٹو سوٗزۍ سارجنٹ، یہ ؤنتھ زِ تِم نفر گژھن گژھن۔\n36.\\tتہٕ جیلٕکۍ رٲچھ کرن والٮ۪ن ووٚن پولس یہِ وَنُن زِ مجسٹریٹو چُھہ ژےٚ نیرنہٕ خٲطرٕ سوزمُت: وۅنۍ نیرُن تہٕ سُکون سان نیرُن۔\n37. مگر پولسن ووٚن تِمن زِ تِمو چُھ رومی آسنہٕ کِنۍ اسہِ نَنہٕ ورٲے مُلمت تہٕ أسـ̡ قٲد خانس مَنٛز ترٛٲومُت۔ تہٕ وۅنۍ چھا تِم اسہِ رازٕ سان کڈان؟ نہٕ پٔزۍ پٲٹھۍ؛ مگر تِم گژھن پانہٕ یِن تہٕ اسہِ نٮ۪بر انن۔\n38.\\tتہٕ سارجنٹَو ووٚن یِم لفٕظ مجسٹریٹس تہٕ تِم گٔیہِ خوفہٕ، ییٚلہِ تِمو بوز زِ تِم چھِ رومی۔\n39.\\tتہٕ تِمو آیہِ تہٕ تِمن ہٕنز منگ تہٕ أنِکھ تِمن نٮ۪بر نیرُن، تہٕ یِمن ہُند شہر نیرُن یژھان۔\n40.\\tتہٕ تِم دراو قٲد خانہٕ منزٕ تہٕ ژاو لِڈیا سٕندِس گرس منز، تہٕ ییلہ تِمو بٲے وُچھِ، تِمو دِژ تِمن تسلی دِتھ درٛاو۔","1. وۅنۍ ییلہ تِم ایمفیپولس تہٕ اپولونیا کِنۍ گٔیہِ، تِم آیہ تھیسالونیکا کُن، یتہِ یہودین ہُند یہودی عبادت گاہ اوس۔\n2. تہٕ پولس گۆو تِمن نِش تہٕ تریہ سبت دۅہن کٔر تِمن سٍتـ̡ صحیفہٕ مُطٲبق استدلال کرنہٕ،\n3. کھولُن تہٕ الزام لگاوُن، زِ مسیح گژھہِ مُتٲثِر گومُت، تہٕ دُبارٕ زندٕ گومُت۔ تہٕ یہِ زِ یہِ عیسیٰ، یُس بہٕ تۅہہِ تبلیغ کران چُھ، چُھ مسیح۔ {کُس...: یا، کُس، تٔمۍ ووٚن، بہٕ چُھس تبلیغ کران}\n4.\\tتہٕ یِمو منزٕ کینہہ ایمان تہٕ کٔرٕکھ پولس تہٕ سیلاسس سٍتـ̡ رٔلِتھ۔ تہٕ دیندار یونانین ہٕنٛز اکھ بٔڑ تعداد، تہٕ اہم زنانن منٛز ٲس نہٕ کیٚنٛہہ۔\n5.\\tمگر یِمو یہودی یِمو نہٕ یقین کٔرِتھ، حسد کٔرِتھ رٔٹِتھ پانس نِش کٔرِکھ کینہہ بدکار تہٕ جمع کٔرِکھ سٲرۍسٕے شہرس ہنگامہٕ تہٕ یسن سٕندِس گرس پیٹھ حملہٕ تہٕ یِم لُکن برونہہ کُن اننٕچ کوٗشش۔\n6.\\tتہٕ ییلہ نہٕ تِم لٔبۍ، تِمو کٔر یعقوبن تہٕ کینہہ بٲے شہر کین حکمرانن نِش، یِمو دُنیا الٹ پلٹٲومُت چھِ، تِمو تہِ آیہ یور تہِ۔\n7. یُس یعقوب روٚٹمُت: تہٕ یِم سٲری چھِ قیصر سٕندِس حکمس برعکس کران زِ بیاکھ بادشاہ چُھہ عیسیٰ مسیح۔\n8.\\tتہٕ یِمو کٔر یِم کتھ بوزِتھ لُکن تہٕ شہرٕکین حکمرانن پریشان۔\n9.\\tتہٕ ییلہ تِمو یعقوبن تہٕ بییِس سٕنز رٲچھ کٔر، تِمو دِژ تِم یِمن نیران۔\n10.\\tتہٕ بٲے سوٗزۍ یکدم پولس تہٕ سیلاس رٲژ بیریا کُن، یُس یِتھ یہودین ہٕندِس عبادت خانس مَنٛز گٔیہِ۔\n11. یِم ٲسۍ تھیسالونیکا ہٕندِس کھۅتہٕ زیادٕ شریف، یتھ مَنٛز تِمو کلام پوٗرٕ ذہنس سٍتـ̡ وصول کٔرِتھ، تہٕ روزانہٕ صحیفہٕ ژھانڈان ٲس، کیا تِم چیز ٲسِ۔\n12. تَمہِ کِنۍ اوس یِمو مَنٛز واریاہَن ہُند ایمان تھاوان۔ تہٕ معزز زنانن ہٕنٛز یم یونانی آسہٕ، تہٕ مردن ہٕنٛز، کیٚنٛہہ نہٕ۔\n13.\\tمگر ییلہ تھیسالونیکا کین یہودین یہ پتاہ لوٚگ زِ خدایہ سُند کلام اوس پولس سٕندِ طرفہٕ بیراہس مَنٛز پرناونہٕ آمُت، تِم آیہِ تتہِ تہٕ لُکن ہُند ہنگامہ کٔرِتھ۔\n14.\\tتہٕ پَتہٕ سوٗز بٲے پولس سمندرس کُن گژھنہٕ خٲطرٕ، مگر سیلاس تہٕ تیموتھیس رودۍ وُنہِ تہِ اتہِ۔\n15.\\tتہٕ یِمو پولس سٍتـ̡ سُہ ایتھنز واتناوُن، تہٕ سیلاس تہٕ تیموتھیسس حکم حٲصل کٔرِتھ زِ تِم دِژ أمِس نِش یِنُک حُکُم۔\n16. وۅنۍ ییلہ پولس ایتھنزس منز تِمن ہُند پیاران اوس، تٔمۍ سُند روح گۆو تس منز ہلچل ییلہ تٔمۍ وُچھ شہر پوٗرٕ پٲٹھۍ بت پرستی خٲطرٕ دِنہٕ آمُت۔ {پورٕ...: یا، بُتن سٍتۍ بٔرِتھ}\n17.\\tلہذا اوس سُہ یہودین سٍتـ̡ یہودین سٍتـ̡ تہٕ پرہیزگارن سٍتـ̡ روزانہٕ تِمن سٍتـ̡ دۅہٕ تِمن سٍتـ̡ جھگڑٕ کران۔\n18. پتہٕ گو ایپیکیورین تہٕ سٹوکس کین کنہہ فلسفین سُند مقابلہٕ۔ تہٕ کینژَو ووٚن، یہِ بَبَر کیا وَن؟ باقٕے کینہہ چُھ، سُہ چُھ عجیب دیوتاہن ہُند اکھ ترتیب دِنہٕ وول باسان: کیازِ تٔمۍ کٔر تِمن عیسیٰ مسیح تہٕ قیامتٕچ تبلیغ کرنہٕ۔ {ببلر: یا، بیس فیلو}\n19.\\tتہٕ تِمو نیو سُہ تہٕ أنِتھ آریوپیگسس نِش، یہِ ونُن زِ اسہِ کیا چُھ یہِ نوو نظریہ، یَتھ مُتلق ژےٚ کتھ کران چھُ، {چُھ}؟ {ایریوپیگس: یا، مریخ پہاڑ: یہٕ اوس ایتھنزک ساروی کھوتہٕ اعلیٰ عدالت}\n20. تکیازِ ژے چُھہ سانین کنن تام کینہہ عجیب چیز انان: لہذا گژھہِ اسہِ معلوم زِ یمن چیزن ہند کیا مطلب چھہ۔\n21. (سارِنٕے ایتھنز تہٕ اجنبی لوٗکھ یِم تتہِ ٲسۍ، تِمو اوس پنُن وقت بییہ کُنہِ چیزس منز گُزٲرمُت، مگر یا تہٕ وننہٕ خٲطرٕ، یا کینہہ نٔو کتھ بوزنہٕ خٲطرٕ۔)\n22.\\tپَتہٕ ووت پولس مریخ کِس بالس منز کھڑا تہٕ وونُن، {اے ایتھنزٕکۍ لوکو، بہٕ چُھس سمجھان زِ تُہۍ چھِو پرٮ۪تھ چیزس مَنٛز واریاہ توہم پرست۔ {مارس ہل: یا، آریوپیگیٹس ہند کورٹ}\n23. ییلہ بہٕ پٔکۍ، تہٕ تہنز عبادتہٕ وُچھمٕژ، میہ لوٚب اکھ قربان گاہ یتھ پیٹھ یہ نوشتہٕ اوس، نامعلوم خدایہ سٕندِ۔ تَمہِ مۄکھٕ یٔمِس تُہۍ جہالت سٍتـ̡ پوجا کران چھِو، سُہ چُھس ژے سٍتـ̡ اعلان کٔرِتھ۔ {عبادت: یا، دیوتا یمن تم پوجا کران چھو}\n24. خدا یُس دنیا تہٕ اَتھ مَنٛز سارِنٕے چیٖز بنوومُت، سُہ چُھ اسمانُک تہٕ زمینُک رب چُھ، سُہ چُھ نہٕ اتھو سٍتـ̡ بَناونہٕ آمٕتـ̡ مندرن مَنٛز روزان۔\n25. نہ چُھہ انسان سٕندِ اتھو سٍتـ̡ پوجا کرنہٕ یوان، گویا أمِس چُھہ کُنہِ چیزٕچ ضرورت، یێلہِ سُہ چُھہ سارِنٕے زندگی، شاہ تہٕ سارِنٕے چیزن دِوان۔\n26. تہٕ کورُن اَکہِ خونہٕ سٍتـ̡ سارِنٕے انسانن ہٕندِس قومس سٍتـ̡ زمینہٕ کِس سارِنٕے بُتھِس پیٹھ روزنہٕ خٲطرٕ، تہٕ مقرر کرنہٕ آمُت وقت تہٕ تِمن ہٕندِ بستی ہٕندِ حدودُک تعین کورمُت۔\n27.\\tیُتھ زِ تِم گژھن رب سٕندِس سٍتـ̡ ژھانڈنہٕ، یێلہِ تِم أمِس پَتہٕ محسوس کٔرِتھ، تہٕ سُہ لٔبِتھ یێلہِ سُہ اسہِ سارِنٕے أکِس نِش دوٗر آسہِ۔\n28.\\tتکیازِ أسۍ چھہِ تس منز روزان، حرکت کران تہٕ پنُن وجود تھاوان۔ یتھے پاٹھۍ چھہ تۅہہِ پننیو شاعرو تہِ وننہ آمت زِ اسۍ چھہِ تسندۍ اولاد۔\n29.\\tتێلہِ چُھہ أسـ̡ خدایہِ سٕندِ اولاد، اسہِ پزِ نہٕ یہِ سونٛچُن زِ خدایہ چُھ سۄنہٕ یا رۄپہٕ یا کٔنـ̡ ہیوٗ ، یُس فن تہٕ انسان سٕندِ آلہٕ سٍتـ̡ کھٔنِتھ چُھہ ۔\n30.\\tتہٕ یێمہِ جہالتُک زمانہٕ چُھہ خداین أچھ دِوان۔ مگر وۅنۍ چُھ سارنٕے انسانس توبہ کرنُک حکم دِوان:\n31.\\tکیازِ تٔمۍ چُھ اکھ دۅہ مقرر کورمُت، یتھ مَنٛز سُہ دُنیاہس سٍتـ̡ نیکی سٍتـ̡ انصاف کرِ، یُس تٔمۍ مقرر کورمُت چُھ۔ {یمہٕ} تٔمۍ سارنٕے {انسان} یقین دِژمُت، یتھ منز تٔمۍ سُہ مُردٕ منزٕ زندٕ کورمُت۔ {دِژمُت...: یا، ایمانہٕ پیش کٔر}\n32.\\tییلہ تمو مرن ہندِ قیامژ ہنز خبر بوز، کینژو کٔر ٹھٹھہ: تہ باقیو ووٚن، اسۍ کرو تۅہہ بییہ اتھ معاملس منز۔\n33.\\tیێلہِ گۆو پولس تِمن منزٕ روانہٕ۔\n34.\\tتوتہِ چھہ کینہہ مرد أمس سیتۍ واٹھ دِوان تہٕ یقین تھاوان: یمن منز ڈیونیسیس آریوپیگیٹ تہٕ دمارس ناوٕچ اکھ زنانہ تہٕ تمن سٍتـ̡ باقٕے ٲسۍ۔","1. یِمو چیزو پَتہٕ دراو پولس ایتھنز پیٹھٕ تہٕ آو کورنتھس کُن۔\n2.\\tتہٕ وُچھ اکھ خاص یہودی یتھ عقیلہ ناو اوس، یُس پونٹس منز زامُت اوس، یُس حالٕے اِٹلی پیٹھٕ پننہ زنانہِ پرسکیلا سٍتۍ آمُت اوس۔ (تکیازِ زِ کلاڈیسن اوس تمام یہودین رومس منز نیرنُک حکم دِتمُت:) تہٕ آو تمن نِش۔\n3.\\tتہٕ کیازِ سُہ اوس اَمی ہنرُک، سُہ روٗد تِمن سٍتـ̡ روزُن، تہٕ کٔرٕن تِمن سٍتـ̡ خیمہ بناون۔\n4.\\tتہٕ سُہ اوس پریتھ سبت دۅہہ یہودی تہٕ یونانین ہٕندِس عبادت خانس مَنٛز استدلال کران۔\n5. تہٕ ییلہ سیلاس تہٕ تیموتھیس مقدونیہ پیٹھٕ آیہ، پولس آو روحس منز دباونہٕ، تہٕ یہودین گوٲہی دِژ عیسیٰ مسیح۔ {مسیح اوس: یا، مسیح اوس}\n6. تہٕ ییلہ تِمو پانس خلاف تہٕ کفر کٔرِتھ، تٔمۍ لوٚگ پَنُن پلو تہٕ تِمن وونُن، تُہند خون چُھہ پننین کلن پیٹھ۔ بہٕ چُھس صاف گومُت: از پتہٕ گژھٕ بہٕ غیر قومن نِش۔\n7. تہٕ سُہ دراو اَتہِ پٮ۪ٹھٕ تہٕ ژاو أکِس خاص {انسان سٕندِس} مکانس مَنٛز، یُس یُس خدایہِ سٕنز عبادت کران اوس، یٔمۍ سُند گرٕ اوس یہِ عبادت خانس سٍتـ̡ رٔلِتھ۔\n8. تہٕ یہودی عبادت خانہٕ ہُند اہم حکمران کرسپس اوس خداوند سٕندِس سارِنٕے گرس سٍتـ̡ پٔنِس سٍتـ̡ پٔنـ̡ پۯاوُن۔ تہٕ واریاہ کرنتھیو بوزن، تہٕ کوٚرکھ بپتسمہ دِنہٕ۔\n9. تیلہٕ کٔرِو خداوند پولس رٲژ أکِس وژنس سٍتـ̡ کتھ کرنہٕ، خوفزدہ گژھ نہٕ بلکہ کتھ کرٕن، تہٕ پَنُن سکون تھاوُن نہٕ:\n10.\\tکیازِ بہٕ چُھس ژے سٍتـ̡ تہٕ کانہہ تہِ شخص کرِ نہٕ ژے سٍتـ̡ تکلیف دِنہٕ خٲطرٕ، تکیازِ یتھ شہرس مَنٛز چُھس میہ واریاہ لوکھ آسان۔\n11.\\tتہٕ سُہ روٗد اَکہِ ؤری تہٕ شیہ ریتن تہٕ تِمن مَنٛز خدایہِ سُند کلام پرناوُن۔ {تتہِ جٲری: Gr. بِہتھ تتہِ}\n12. تہٕ ییلہ گیلیو اخایا ہُند نائب اوس، یہودیو کٔر پولسس خلاف اکی سٍتـ̡ بغاوت، تہٕ أنِکھ سُہ فیصلہٕ کِس مقامس پیٹھ،\n13.\\tیہ ونِتھ چھہ یہ {ساتھی} انسانس شریعت برعکس خدایہ سٕنز عبادت کرنہٕ خٲطرٕ آمادہ کران۔\n14. تہٕ ییلہ پولس وُنہِ پنُن بوش کھولُن اوس ، گیلیوَن ووٚن یہودین زِ اگر یہِ غلط یا بدکار فحاشی ہُند معاملہ آسہِ، اے یہودی، تیلہِ گژھہِ بہٕ ژے سٍتـ̡ برداشت کرُن:\n15.\\tمگر اگر یہ لفظن تہٕ ناون ہُند سوال آسہِ، تہٕ تُہٕندِس قونوٗنُک سوال آسہِ، تۅہہ وُچھِو {اَتھ کُن}۔ تکیازِ بہٕ آسہٕ نہٕ یتھین {معاملات} ہُند کانہہ جج بنان۔\n16. تہٕ سُہ کٔر تِمن فیصلہٕ چہ نشستہٕ پیٹھ۔\n17.\\tپتہٕ نیو سارِوٕے یونانیو یہودی عبادت خانُک اہم حکمران سوستھینز، تہٕ دِتُکھ أمِس عدالتٕچ نشستہٕ برونہہ کُن۔ تہٕ گیلیوَن اوس نہٕ یِمَو منٛزٕ کانٛہہ تہِ پرواہ۔\n18.\\tتہٕ پولس روٗد واریاہس کالس روزُن، تہٕ پتہٕ ہیوٚت باین نِش رخصت تہٕ تتہِ ووت شامس کُن، تہٕ تس سٍتـ̡ پرسیلا تہٕ عقیلہ۔ سینکریاہس منز اوس کلہ ژٹُن: تکیازِ أمس اوس اکھ عہد کورمُت۔\n19. تہٕ سُہ آو افسس نِش تہٕ تِم ترٛٲوِن تتہِ، مگر سُہ ژاو پانہٕ یہودی عبادت خانس مَنٛز، تہٕ کوٚرُن یہودین سٍتـ̡ استدلال کرنہٕ۔\n20.\\tییلہ تِمو تِمن سٍتـ̡ زیادٕ کالس روزُن یژھان، تٔمۍ کٔر نہٕ رضامندی ۔\n21.\\tمگر وونُن تِمن الوداع کٔرِتھ زِ بہٕ پزِ یُس یروشلمس مَنٛز یِنہٕ وول یُس دعوت یُس بہٕ یُس بہٕ یُس تہٕ سُہ دراو ایفیسس پیٹھٕ ٲبی سفر۔\n22.\\tتہٕ ییلہ سُہ قیصریہس مَنٛز ووتمُت، تہٕ ہیوٚر ووت تہٕ کلیساہَس سلام کٔرِتھ، سُہ ووت انطاکیہ کُن۔\n23.\\tتہٕ کینہہ کال گُزارنہٕ پتہٕ، سُہ دراو تہٕ سارِنٕے مُلکس گُلتیایہ تہٕ فریجیا کِس مُلکس منز، سارِنٕے شٲگِرِن مضبوٗط کٔرِتھ۔\n24. تہٕ اَکھ یہوُدی یُس اسکندریہس مَنٛز زامُت اوس، یُس صحیفہٕ مَنٛز طاقتور اوس، اَکھ فصیح شخٕص تہٕ صحیفہٕ مَنٛز طاقتور اوس، آو افسس کُن۔\n25. أمِس شخصس اوس خداوند سٕنزِ وتہِ ہُند ہدایت دِنہٕ آمُت۔ تہٕ روحس مَنٛز پُرجوش آسنہٕ کِنۍ، تٔمۍ کٔر رب سٕنزِ کتھہٕ سٍتـ̡ کتھ تہٕ ہیچھناوٕن، صرف یوحنا سٕندِ بپتسمہ زانان۔\n26. تہٕ تٔمۍ ہیوٚت یہِ عبادت خانس مَنٛز دِلیلہٕ سان کتھ کرٕنۍ: یٔمِس ییلہ عقیلہ تہٕ پرسکیلا بوٗز، تِمو نِیہِ سُہ تِمن نِش، تہٕ تٔمِس کٔرٕن خدایہِ سٕنز وتھ زیادٕ پوٗرٕ پٲٹھۍ۔\n27.\\tتہٕ ییلہ سُہ اخایہ مَنٛز نیرنہٕ خٲطرٕ تیار کرنہٕ آو، بٲے لیوکھ مریدن أمِس استقبال کرنٕچ تلقین کٔرِتھ: یِمو ییلہ سُہ آو تِمن سٍتـ̡ واریاہ مدد یُس فضل سٍتـ̡ پژھ تھاوان اوس۔\n28.\\tتکیازِ تٔمۍ کٔر یہودین ہُند قایل، {تہٕ یہ} عوٲمی طور صحیفہٕ سٍتـ̡ ہاوان زِ عیسیٰ مسیح چُھ۔ {مسیح: یا، مسیح چُھ}","1. تہٕ سپُد یہِ زِ ییلہ اپولوس کورنتھس منز اوس، پولس آو پیٹھمہِ ساحلہٕ کِنۍ گٔژھِتھ افسس نِش تہٕ کینہہ شٲگِر لٔبِتھ\n2. تٔمۍ ووٚن تِمن پى۪ٹھ، یێلہِ تہٕ یێلہِ چُھہ یێلہِ تہٕ یێلہِ چُھہ روح القدس حٲصِل سپُدمُت؟ تہٕ تِمو ووٚن أمِس زِ اسہِ چُھنہٕ تیوٗت بوزمُت زِ روح القدس چھا نہٕ۔\n3. تہٕ تٔمۍ ووٚن تِمَن، تیٚلہِ کمہِ خٲطرٕ آو بپتسمہ دِنہٕ؟ تہٕ تِمو ووٚن یوحنا سٕندِس بپتسمس تام۔\n4. پَتہٕ ووٚن پولس، یوحنا کٔر پٔزۍ پٲٹھـ̡ توبہٕ کِس بپتسمہ سٍتـ̡ بپتسمہ دِنہٕ، تہٕ لُکن وونُن زِ تِم پزِ أمِس پى۪ٹھ، یُس أمِس پَتہٕ یُس مسیح عیسیٰ مسیحس پى۪ٹھ۔\n5. ییلہ تِمو یہِ بوٗز، تِمو کٔر خداوند عیسیٰ سٕندِ ناوٕ سٍتـ̡ بپتسمہ دِنہٕ۔\n6. تہٕ ییلہ پولسن تمن پیٹھ اتھہٕ تھوو، روح القدس آو تمن پیٹھ۔ تہٕ تِمو کٔر زبانہٕ سٍتـ̡ کتھ تہٕ پیشن گویی کٔرٕنـ̡ ۔\n7.\\tتہٕ سٲری مرد ٲسۍ تقریباً باہ۔\n8. تہٕ سُہ گوٚو یہِ عبادت خانس مَنٛز، تہٕ ترٮ۪ن ریتن تام کٔرٕن دِلیری سان کتھ کرنہٕ، خدایہِ سٕنزِ بادشٲہی مُتلق کتھ کٔرِتھ بحث تہٕ قائل کٔرِتھ۔\n9.\\tمگر ییلہ غوطہٕ خور سختی کرنہٕ آیہ، تہٕ یِمو کٔر نہٕ پژھہٕ پٲٹھۍ، مگر ہجومس برونہہ کُن کٔرٕکھ اَتھ پٲٹھۍبد کتھ کرنہٕ، سُہ ژاو تِمو نِش تہٕ شٲگِرِ الگ کٔرِتھ روزانہٕ أکِس سٕندِس سکولس مَنٛز بحث کران۔\n10. تہٕ یہ رود دون ورین تام جٲری۔ یُتھ زن ایشیاہس مَنٛز روزان ٲسۍ، تِمو بوز خداوند عیسیٰ سُند کلام، یہودی تہٕ یونانی۔\n11. تہٕ خداین کٔر پولس سٕندِ اتھہٕ سٍتـ̡ خاص معجزہٕ:\n12.\\tیُتھ تٔمۍ سٕندِس جسمہٕ منزٕ بیمار رومال یا ایپرنس تام اننہٕ تہٕ یِمو نِش گٔیہِ بٮ۪مارِ تہٕ بد روح گٔیہِ تِمن نِش نیبر۔\n13. اَمہِ پَتہٕ کُنہِ آوارہ یہودی، یِمن منز بد روحن ہٕندِس ناوس سٍتـ̡ خداوند عیسیٰ سُند ناو دِنہٕ آمُت چھُ، یہِ ونُن زِ أسـ̡ چُھہ عیسیٰ سٕندِ سٍتـ̡ تُہٕندِس سٍتـ̡ تُہُند عہد کران یُس پولس تبلیغ کران چُھ۔\n14.\\tتہٕ اَکھ یہودی سکیوا سٕندِ سَتھ نیچوۍ، یُس پادٕرین ہُند سردار اوس، یِمو یہِ کٔر۔\n15. تہٕ بد روحن دیُت جواب تہٕ وونُن، عیسیٰ مسیح تہٕ پولس بہٕ زانان چھُس۔ مگر تُہۍ کُس چھِو؟\n16.\\tتہٕ سُہ شخص یٔمِس مَنٛز بد روح تِمن پیٹھ وۄٹھ دِژ، تہٕ یِمن پیٹھ غلبہٕ تہٕ تِمن پیٹھ غلبہٕ حٲصل کٔرِتھ ژٔلِتھ ژٔلِتھ تِم اَمہِ گرٕ منزٕ نٮ۪بر تہٕ زخمی گٔیہِ۔\n17. تہٕ یہِ اوس ایفیسس مَنٛز روزن وٲلِس سارِنٕے یہودی تہٕ یونانین تہِ زانان۔ تہٕ یِمن سارِنٕے سٍتـ̡ خوف پیوو تہٕ خداوند عیسیٰ سُند ناو آو بڑاونہٕ۔\n18.\\tتہٕ واریاہ یِمو پژھہٕ پٲٹھۍ، تہٕ کوٚرُکھ اقرار تہٕ پنٕنۍ اعمال ہٲوِکھ ۔\n19.\\tیِمو منزٕ واریاہو یِمو عجیب فَن ہُند استعمال کٔرِتھ کٔرِکھ پنٕنۍ کتابہٕ یکجا تہٕ سارِنٕے انسانس برونہہ کُن زٲلِتھ تہٕ تِمو گٔنزۍ تِمن ہُند قٕمتھ تہٕ لٔبِکھ پنژاہ ساس رۄپہٕ۔\n20. یێلہِ بێیہِ خدایہِ سُند کلام تہٕ گٔیہِ غالب۔\n21.\\tیِم چیز ختم گژھنہٕ پتہٕ، پولس اوس روحس مَنٛز ارادٕ، ییلہ سُہ مقدونیہ تہٕ اخایا مٔنزۍ گٔژھِتھ یروشلم گژھُن، یہِ وونُن زِ بہٕ تتہِ گژھنہٕ پتہٕ، بہٕ پزِ روم تہِ وُچھُن۔\n22. چنانچہ سوٗزۍ تمو منزٕ زٕ مقدونیہ یِمو تٔمِس خدمت کٔر، تیموتھیس تہٕ ایراسٹس۔ مگر سُہ روٗد پانہٕ أکِس سیزنس ایشیاہس منٛز۔\n23.\\tتہ اتھۍ ساعتہ گۆو نہ اتھ متعلق کانہہ لۅکٹ ہنگامہ۔\n24.\\tدِمِتریَس ناوٕکِس أکِس شخصس خٲطرٕ، یُس رۄپہٕ ساز اوس، یُس ڈیانا سٕندِ خٲطرٕ رۄپہٕ ہٕندِ مزار بنٲوِتھ، تٔمِس ہیوٚت نہٕ کٲرِگرن کانہہ لۄکُٹ فٲیدٕ۔\n25.\\tیِمَن تٔمۍ یِتھۍ پیشہٕ کامہِ والٮ۪ن سٍتۍ رٔلِتھ بُلوو، تہٕ وونُن، جناب، تۅہہ چھِو پتاہ زِ اَمہ ہٕندِ ہٕندِ سٍتۍ چھُ اسہِ پنُن دولت۔\n26.\\tتوے چُھہ وُچھان تہٕ بوزان زِ نہ صرف ایفیسس مَنٛز بلکہ تقریباً سٲرۍسٕے ایشیاہس مَنٛز، اَمہ پولس چُھ واریاہن لُکن ہُند آمادہ تہٕ پھیُرُن، یہِ ؤنِتھ زِ تِم چِھنہٕ کانہہ دیوتا، یِم اتھو سٍتـ̡ بناونہٕ آمٕتۍ چھِ:\n27. تاکہ نہ صرف یہ سون ہنر گژھہِ خطرس منز۔ بلکہ یہ تہِ زِ عظیم دیوی ڈیانا سٕندِس مندرس گژھہِ حقارت کرنہٕ یُن، تہٕ تٔمۍ سٕنز عظمت گژھہِ تباہ کرنہٕ یُن، یٔمِس سٲرۍسٕے ایشیا تہٕ دُنیا پوجا کران چھِ۔ {سیٹ ایٹ ناٹ: یا، بدنام کرنہٕ آمُت، یا، حقارت}\n28.\\tتہٕ ییلہ تِمو یِم کتھٕ بوز، تِمو گٔیہِ غصہٕ سٍتـ̡ تہٕ وونُن زِ عٔظیٖم چُھہ افسِین ہُند عٔظیٖم ڈیانا۔\n29. تہٕ سورُے شہر اوس پریشٲنی سٍتۍ بٔرِتھ: تہٕ مقدونیہ ہٕکۍ نفر گیئس تہٕ اریسٹارکس رٔٹِتھ گٔیہِ تِم اَکہٕ وِزِ تھیٹرس منز۔\n30.\\tتہٕ ییلہ پولس لوکن منز اژان آسہِ، شاگردن کٔر نہٕ أمس برداش۔\n31.\\tتہٕ ایشیاہُک سردار، یُس تٔمۍ سٕندِ دوس اوس، سوزُکھ أمِس نِش، یہِ یژھان زِ سُہ کرِ نہٕ پانس تھیٹرس منز اژُن۔\n32. تَمہِ کِنۍ ٲسۍ کیٚنٛہہ اَکھ کتھ تہٕ کیٚنٛہہ بییِس چیز: تِکیازِ مجلسہٕ ٲس پریشان۔ تہٕ زیادٕ حصہٕ ٲس نہٕ خبرے زِ تم کیازِ آیہ اکوٹہٕ۔\n33.\\tتہٕ تِمو کٔر سکندر ہجومہٕ منزٕ نیبر، یہودی کٔر أمِس برونہہ کُن۔ تہٕ سِکندر کٔر اَتھٕ سٍتۍ اِشارٕ، تہٕ کٔرِن لوکن برونہہ کُن پنُن بچاو۔\n34. مگر ییلہ یمن پتاہ زِ سُہ چُھ یہوُد، سارِوٕے دِژ اَکہِ آوازٕ سٍتـ̡ دۄن گھنٹن ہٕندِس وقفس سٍتـ̡ دِژ دِژٕن، عٔظیٖم چُھہ افسِین ہُند عٔظیٖم۔\n35.\\tتہٕ ییلہ ٹاؤن کلرک لُکن مطمئن کٔر، تٔمۍ ووٚن، {اے افسسٕکۍ انسانو، کُس انسان چُھ یُس نہٕ زانان چُھہ زِ افسِین ہُند شہر چُھ عظیم دیوی ڈیانا سُند پوجا کرن وول، تہٕ مشتری پیٹھٕ پیوٚو {تصویر} سُند پوجا کرن وول۔ {اکھ عبادت گزار: Gr. the Temple Keeper}\n36. تیلہِ وُچھِتھ زِ یِمن چیزن خلاف ہیکو نہٕ کتھ کٔرِتھ، تہٕ پزِ نہٕ ژھۄپہٕ روزُن، تہٕ جلدبازی کرُن نہٕ۔\n37. تکیازِ ژے چھِو یِم نفر یور أنۍمٕتۍ، یِم نہ گرجا گھرن ہٕندِ ڈاکہ دِنہٕ وٲلۍ، تہٕ نہ چھِ تُہنزِ دیوی ہٕندِ کفر کُن۔\n38.\\tلہذا اگر دیمِتریس تہٕ أمِس سٍتـ̡ یِمن کاریگرن سٍتـ̡ کٲنٛسہِ شخصس سٍتـ̡ کانہہ معاملہٕ چُھ، تیلہِ چُھ قانون یلہٕ تہٕ تِمن ہٕندِس نٲیرس سٍتـ̡ چُھہ: تِم گٔژھن اکھ أکِس سٍتـ̡ مُتعلِق۔ {قانون...: یا، عدالتک دوہ چھ تھاونہٕ یوان}\n39.\\tمگر اگر تۅہہ باقی معاملاتن متعلق کُنہِ چیزس متعلق پرژھہ گٲر کرِو، تیلہِ گژھہِ یہ قانونی مجلسس منز طے کرنہٕ یُن۔ {قانونی: یا، عام}\n40.\\tتکیازِ اسہِ چھہ امہ دۅہک ہنگامہ آرایی ہندِ خاطرہ سوالیہ نشان زِ اسہِ چھہ نہ کانہہ وجہ۔\n41.\\tتہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، تٔمۍ کٔر اسمبلی برخاست۔","1. تہٕ ہنگامہ بند گژھنہٕ پتہٕ، پولس بُلوو شٲگردن تہٕ رٔلِتھ رٔٹِتھ تہٕ دراو مقدونیہ کُن گژھنہٕ خٲطرٕ۔\n2. تہٕ ییلہ سُہ تِمن حصن پیٹھ گٔژھِتھ تہٕ تِمن واریاہ نصیحت دِژ، سُہ آو یونانس منز،\n3. تہٕ {تتہِ} روزِ تریہ ریت۔ تہٕ ییلہ یہودی أمس پیاران اوس، ییلہ سُہ شام کُن نیرُن اوس، تٔمِس اوس مقدونیہ کِنۍ واپس گژھنُک ارادٕ۔\n4. تہٕ تتہٕ تٔمۍ سٕندِ سٍتـ̡ ایشیا سوپیٹرس منز بیریا کِس سٍتـ̡ ۔ تہٕ تھیسالونیکی، اریسٹارکس تہٕ سیکنڈس۔ تہٕ ڈربے ہُک گیئس، تہٕ ٹموتھیس۔ تہٕ ایشیا، ٹائچیکس تہٕ ٹروفیمس۔\n5. یِم گٔیہِ برونٹھ کُن سانہِ خٲطرٕ ٹرواس منٛز۔\n6. تہٕ أسۍ دراو فِلپی نِش خمیرٕ روٚس روٹی ہٕندِس دۅہہٕ پتہٕ، تہٕ وٲتِتھ پانژن دۅہن منز تِمن نِش ٹرواس کُن۔ ییتہِ أسۍ سَتھ دۄہ روزان چھِ۔\n7. تہٕ ہفتہٕ کِس گۄڈنِکِس دۅہہٕ ییلہ شٲگِر روٹی پھُٹراونہٕ خٲطرٕ اِکہٕ وٹہٕ وٲتِتھ، پولس کٔر تِمن تبلیغ تہٕ پگہہ نیرنہٕ خٲطرٕ تیار۔ تہٕ روٗد نصف رٲژ تام پنٕنۍ تقریر جٲری۔\n8.\\tتہٕ ہیٚرمِس کمرس مَنٛز ٲسۍ واریاہ گاش، یَتھ منٛز تِم جمع ٲسۍ گٔمٕتۍ۔\n9.\\tتہٕ أکِس دارِ منز بِہتھ یوتیکس ناوُک اکھ نوجوان یُس سٮ۪ٹھاہ شوٚنگتھ گوو، تہٕ یُتھ پولس واریاہس کالس تبلیغ کران اوس، سُہ ووت نندر سٍتـ̡ تہٕ پیوٚو تریمہِ لٹہِ پیٹھٕ بۄن، تہٕ سُہ آو مٔرِتھ تُلنہٕ۔\n10. تہٕ پولس پیوٚو بۄن تہٕ پیوٚو أمِس پیٹھ، تہٕ وونُن پانس مُشکِل کرُن۔ تکیازِ تسنز زندگی چھیہ تس منز۔\n11.\\tییلہ سُہ دُبارٕ ووٚتھ، تہٕ کھیوٚن تہٕ کھٮ۪وان تہٕ واریاہس کالس کتھ کٔرِتھ، یێلہِ دۅہہ پھُٹنس تام تہِ گۆو سُہ روانہٕ۔\n12.\\tتہٕ تِمو أنۍ جوان زِندٕ تہٕ رژھ۔\n13.\\tتہٕ أسۍ گٔیہِ جہازس پیٹھ، تہٕ گٔیہِ اسوس کُن، تتہِ گٔیہِ پولس پانس نِنُک ارادٕ، تِکیازِ تٔمۍ اوس پانس پَکُن پکنُک خیال تھاوان۔\n14.\\tتہٕ ییلہ سُہ اسہِ سٍتـ̡ اسہِ سٍتـ̡ سمکھیوو، أسـ̡ نِش نِش تہٕ آۓ مِٹِلینس کُن۔\n15. تہٕ أسۍ ووت تتہِ سفر، تہٕ دوٚیمہِ دۅہہ آو چیوسس خٕلاف۔ تہٕ دوٚیمہِ دۅہہ وٲتۍ أسۍ ساموس تہٕ روٗدۍ ٹروگیلیمس منٛز۔ تہٕ دوٚیمہِ دۅہہ آو أسۍ میلیٹس کُن۔\n16.\\tتکیازِ پولس اوس افسس سٍتـ̡ سفر کرنُک عزم کورمُت، تکیازِ سُہ گُزٲرِ نہٕ ایشیاہس مَنٛز وقت، تکیازِ تٔمِس اوس جلدی کٔرمٕژ، اگر یہ ممکن آسہِ، پینتیکوسٹ کہ دۅہہٕ یروشلمس مَنٛز روزُن۔\n17.\\tتہٕ میلیٹس سٍتـ̡ سوٗز تٔمۍ ایفیسس نِش تہٕ کورُن کلیساہٕکۍ بزرگن بُلاونہٕ۔\n18.\\tتہٕ ییلہ تِم أمِس نِش آیہ، تٔمۍ ووٚن تِمن پتاہ زِ بہٕ گۅڈنچہ دۅہہ پیٹھٕ ییلہ بہٕ ایشیاہس مَنٛز آو، بہٕ کِتھہٕ پٲٹھۍ چُھس ژےٚ سٍتـ̡ پرٮ۪تھ موسمس سٍتـ̡ رودمُت،\n19.\\tخداوند سٕنز خدمت کٔرٕنـ̡ سٍتـ̡ سٍتـ̡ یُس یہودین ہٕندِس انتظارس منز روزنہٕ سٍتـ̡ میہ سٍتـ̡ سپُد:\n20.\\t{تہٕ} کِتھہ کٔنۍ تھوو نہ میہ کانہہ تہِ چیز یُس نفع بخش آسہِ، مگر ژے ہٲومُت تہٕ ژے ہٲومُت تہٕ عوٲمی طور تہٕ گرٕ گرٕ ہیچھناومُت،\n21. یہودین تہٕ یونانین تہٕ یونانن سٍتـ̡ گوٲہی دِن، خدایس سٍتـ̡ توبہ تہٕ سٲنِس آغہٕ عیسیٰ مسیحس سٍتـ̡ ایمان دِنـ̡ ۔\n22. تہٕ وُچھِو بہٕ روٝحہِ سٍتـ̡ یروشلمس کُن بٔنِتھ، یہِ نہٕ زانان زِ تتہِ یِم چیز سپدِ:\n23. یێلہِ چُھہ روح القدس پریتھ شہرس مَنٛز گوٲہی دِوان تہٕ یہِ ونان زِ بندھن تہٕ مصیبتَن ہٕندِس سٍتـ̡ چُھہ میہ روزُن۔ {میہ کٔرِو: یا، انتظار کٔرِو}\n24. مگر یِمو منزٕ چُھہ نہٕ کانہہ تہِ چیز بہٕ متٲثر کران، تہٕ نہ چُھس بہٕ پنٕنۍ زندگی پانس خٲطرٕ عزیز مانان، یُتھ بہٕ ہێکہٕ خوشی سان پنُن وتھ مُکمل کٔرِتھ، تہٕ یُس میہ خداوند عیسیٰ سٕندِ طرفہٕ حٲصل سپُدمُت چُھ، یُس میہ خدایہ سٕندِ فضل ہٕنزِ خوشخبری ہٕنز گوٲہی دِنہٕ خٲطرٕ حٲصل سپدان چُھ۔\n25.\\tتہٕ وُچھِو بہٕ پتاہ زِ یێمہِ سٍتـ̡ بہٕ خدایہِ سٕنزِ بادشٲہی ہٕنز تبلیغ کرنہٕ آمٕژ چھِ، تێلہِ گژھہِ نہٕ میون بُتھ وُچھان۔\n26. اَمہِ مۄکھٕ چُھس بہٕ ژےٚ یہِ دۅہہٕ درٕج کَرنہٕ خٲطرٕ نِوان زِ بہٕ چُھس سارِنٕے {انسانَن} ہٕندِ خونہٕ سٍتـ̡ پاک گٔژھمُت۔\n27. کیازِ بہٕ چُھس نہٕ ژےٚ خدایہِ سٕندِ مشورٕ سٍتـ̡ دِنہٕ سٍتـ̡ دِنہٕ آمُت۔\n28. تێمہِ کِنۍ کرو پانس تہٕ سارنٕے ریوڑس سٍتـ̡ یُس روح القدس چُھہ نگران، یُس تٔمۍ پننِس خونہٕ سٍتـ̡ ہیوٚتمُت چُھ، یُس تٔمۍ پننِس خونہٕ سٍتـ̡ ہیوٚتمُت چُھ۔\n29. کیازِ بہٕ چُھس یہِ زانان زِ میانہِ نیرنہٕ پتہٕ گژھن غمگسار رامہٕ ہونہٕ یِنہٕ تہٕ یِمن ہٕندِس ریوڑس منز دٲخل گژھن۔\n30.\\tتہِ گژھن انسان وۅتھان تہ غلط کتھہ کٔرِتھ تہٕ تِمن ہٕندِ پَتہٕ شٲگِرِ نِنہٕ خٲطرٕ۔\n31.\\tتێلہِ وُچھِو تہٕ یاد تھاوُن زِ ترٮ۪ن ؤرین ہٕندِس وقفس تام اوس نہٕ میہ پرٮ۪تھ أکِس رٲژ تہٕ دۅہس اوٚش دِنہٕ سٍتـ̡ خبر دِنہٕ بنٛد کٔرمٕژ۔\n32. تہٕ وۄنۍ، بھائیو، بہٕ چُھس تہٕ تٔمۍ سٕندِس فضل کِس کلامس سٍتـ̡\n33. مے چُھس نہٕ کٲنسہ تہِ شخصہٕ سٕندِ رۄپہٕ، یا سۄنہٕ یا پلوَن ہُند لالچ۔\n34.\\tآ، تۅہہ چھیہ پتاہ زِ یِمو اتھو چھِ میانین ضروریاتن تہٕ تِمن ہٕنز خدمت کٔرمٕژ یِم میانہِ سٍتۍ ٲسۍ۔\n35. مے چُھہ ژےٚ سارِنٕے چیٖز ہٲومٕتۍ، یێلہِ کِتھہ پٲٹھـ̡ چُھہ یێلہِ کُنہِ سٍتـ̡ کمزورن سٍتـ̡ مدد کرٕنـ̡ تہٕ خداوند عیسیٰ سٕندِ کلامَس یاد تھاوُن، یێلہِ چُھہ یێمہِ سٍتـ̡ دِنہٕ آمُت چُھہ زیادٕ بابرکت ۔\n36. تہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، سُہ بوٚن کۄٹھن بۄن، تہٕ تِمن سارِنٕے سٍتـ̡ دُعا کٔرٕن۔\n37.\\tتہٕ تِم سارِوٕے رووُن دَگ تہٕ پولس سٕنزِ گردنہِ پیٹھ پیوٚو تہٕ بوسہ دِژٕن،\n38.\\tسارِوٕے کھۅتہٕ زیادٕ غمگسار زِ تِمن ہُند بُتھ وُچھُن نہٕ۔ تہٕ تِم گٔیہِ أمِس سٍتۍ جہازس تام۔","1.\\tتہ سپد یہ زِ ییلہ أسۍ تِمو نِش نِش نیرِتھ تہٕ لانچ کٔرۍ، أسۍ آیہ کوس کُن سیود وتہِ ہیتھ تہٕ امہ پتہ روڈس کُن تہٕ تتہِ پیٹھہ پترا تام:\n2. تہٕ فینیشیا کُن اکھ جہازٕ وُچھِتھ گٔیہِ أسۍ جہازس منز تہٕ درٛاو درٛاو۔\n3.\\tوۅنۍ ییلہ اسہِ قبرص دریافت سپدِ، اسہِ تروو یہ کھوورِ طرفہ تہ شامس کُن سفر کٔرِتھ ووت صورس منز، تکیازِ تتہِ اوس ٲبی جہازس پنُن بور تُلُن۔\n4. تہٕ شٲگِرِ ژھانڈِتھ روٗد أسۍ سَتھ دۅہہ، یٔمۍ پولس روحہٕ سٍتـ̡ ووٚنمُت زِ سُہ پزِ نہٕ یروشلمس تام گژھُن۔\n5. تہٕ ییلہ أسۍ تِم دۅہ پوٗرٕ کٔرۍ، أسۍ دراو تہٕ پَنٕنۍ وَتھ پٔکۍ۔ تہٕ تِمو سارِوٕے أنۍ اسہِ زنانہٕ تہٕ شُرِ ہٮ۪تھ، یوٚت تام أسۍ شہرٕ نیبر نیرِتھ، تہٕ أسۍ بٔٹھِس پیٹھ کۄٹھہٕ بٔنِتھ دُعا کٔرِتھ۔\n6. تہٕ ییلہ أسۍ اَکھ أکِس نِش رخصت گٔیہِ، أسۍ رٔٹۍ جہاز۔ تہٕ تِم آیہ دُبارٕ گرٕ واپس۔\n7. تہٕ ییلہ أسۍ صور پیٹھٕ پنٕنۍ وتھ مُکمل کٔرۍ، أسۍ وٲتۍ بطلیمیس نِش، تہٕ بٲے سلام کٔرِتھ اکہِ دۅہہ تِمن سٍتـ̡ روزُن۔\n8.\\tتہٕ دۆیمہِ دۅہہ گٔیہِ أسۍ یُس پولس سٕندِس صحبتس سٍتـ̡ اوس، تہٕ وٲتِتھ وٲتِتھ گٔیہِ قیصریہ کُن: تہٕ أسۍ ژاو فلپ سٕندِس گرس منز، یُس ستن منزٕ اکھ اوس۔ تہٕ تس سٍتۍ روزُن۔\n9. تہٕ أتھۍ شخصس ٲس ژور کورِ، کنوارۍ، یِمو پیشن گویی کٔر۔\n10.\\tییلہ أسۍ واریاہن دۅہن روٗدۍ، یہوداہ پیٹھہ آو اکھ پیغمبر یُس آگابوس ناو اوس۔\n11. تہٕ ییلہ سُہ اسہِ نِش آو، تٔمۍ رٔٹ پولس سُند کمر، تہٕ کوٚرُن پنٕنۍ اتھہٕ تہٕ کھۅر بٔنِتھ تہٕ وونُن، یِتھٕ پٲٹھۍ چُھ روح القدس ونان زِ یِتھٕ پٲٹھۍ کرِ یروشلمس مَنٛز یہودی یُس اتھ بندس منز چُھ، تہٕ یِمن ہٕندِس اتھس مَنٛز دِنہٕ۔\n12.\\tییلہ اسہِ یِم کتھ بوز، اسہِ تہٕ تمہِ جایہِ ہٕندِس تِمو دۅشوے کٔر أمِس یروشلمس تام نہ گژھنٕچ التجا ۔\n13.\\tپَتہٕ دِیُت پولس جواب، تۅہہ کیا مطلب چُھہ روُن تہٕ میون دِل پھُٹراونُک؟ تکیازِ بہٕ چُھس نہٕ صرف پابند روزنہٕ خٲطرٕ تیار، بلکہ خداوند عیسیٰ سٕندِ ناوٕ خٲطرٕ یروشلمس مَنٛز مرنہٕ خٲطرٕ تہِ تیار۔\n14. تہٕ ییلہِ نہٕ أمِس راضی کرنہٕ آو، أسۍ ووٚن زِ خداوند سٕنز مرضی گژھہِ پورٕ۔\n15. تہٕ یِمو دۅہہٕ پَتہٕ أسۍ گاڑِ رٔٹِتھ تہٕ ووت یروشلمس کُن۔\n16.\\tاَتھ سٍتـ̡ گۆو اَسہ سٍتـ̡ قیصریہ ہٕندِس مریدٕ سٍتـ̡ تہٕ پانس سٍتـ̡ أنۍ قبرصُک اکھ مناسن، یُس اکھ پرون شٲگِر، یٔمِس سٍتـ̡ أسـ̡ روزُن پزِ۔\n17. تہٕ ییلہ أسۍ یروشلم وٲتۍ، بٲے کٔر اسہِ خوشی سان استقبال۔\n18.\\tتہٕ پَتہٕ پولس گۆو اسہِ سٍتـ̡ یعقوبس نِش۔ تہٕ سٲری بزرگ ٲسۍ موجود۔\n19. تہٕ ییلہ تٔمۍ تِمن سلام کٔر، تٔمۍ کٔر خاص طور اعلان زِ خداین کُس چیز چھُ پننہِ وزارتہٕ سٍتـ̡ غیر قومن مَنٛز کٔرمٕژ۔\n20.\\tتہٕ ییلہ تِمو بوز، تِمو کٔر خداوند سٕنز حمد تہٕ وونُن زِ ژے وُچھمُت بٲے، کٲژاہ ساسہٕ بٔدۍ یہودی چھِ یِم ایمان تھاوان چھِ۔ تہٕ تِم سٲری چھِ قانونُک جوش:\n21. تہٕ تِمن چُھہ تۅہہِ مُتلق خبر دِنہٕ آمُت زِ تِمن سارِنٕے یہودی یِم غیر قومن مَنٛز چھِ، موسیٰ سٕندِس سٍتـ̡ تراوُن ہیچھناوُن، یہِ ؤنِتھ زِ تِمن پزِ نہٕ پننین شُرین ختنہ کرُن، تہٕ نہ پَزِ رسمن پَکُن پَکُن۔\n22. تیلہٕ کیا چُھ؟ ہجوم گژھہِ اَکہٕ وٹہٕ گژھُن: تِکیازِ تِم بوزِن زِ تُہۍ چھِو آمُت۔\n23. تێمہِ کِنۍ کٔرِو یێلہِ أسۍ ژے ونان چھِ: اسہِ چھِ ژور نفر یِمن پیٹھ عہد چُھ۔\n24.\\tتِمن سٍتـ̡ رٔٹِو تہٕ پان پاک کرُن، تہٕ تِمن سٍتـ̡ روزُن تہٕ تِمن سٍتـ̡ کلہٕ کھسنہٕ یِن، تہٕ سارِنٕے گژھن پتاہ زِ تِم چیز یِمن مُتلق تۅہہِ متعلق زاننہٕ آمٕژ چھِ، تِم چھِنہٕ کیٚنٛہہ تہِ۔ مگر {یہ} تہٕ چُھکھ پانس منظم پکان تہٕ قانونس برقرار تھاوُن۔\n25.\\tیِمن غیر قومن ہٕندِس عقیدس سٍتـ̡ چُھہ اسہِ لیوکھمُت زِ تِم چِھہ نہٕ یِتھٕ کُنہِ چیزس پیٹھ عمل کران، صرف یہ زِ تِم چِھ بُتن ہٕندِس دِنہٕ نِش، خونس نِش، گُلہٕ دِنہٕ نِش تہٕ زناکاری نِش بچاوان۔\n26. پَتہٕ نِیوو پولس نفر، تہٕ دٔیمہِ دۅہہ ژاو تِمن سٍتـ̡ پاک کٔرِتھ ہیکلس مَنٛز، یُس پاکیزگی ہٕندِس دۅہہٕ ہٕندِس پوٗرٕ آسنٕچ علامت دِنہٕ خٲطرٕ، یوتام نہٕ یِمن منز پرٮ۪تھ أکِس خٲطرٕ نذرانہ پیش کرنہٕ یُن۔\n27. تہٕ ییلہ ستھ دۅہ لگ بھگ مۅکلیوو، یہودی یُس ایشیاہٕکۍ ٲسۍ، ییلہ تمو أمس مندرس منز وُچھ، سارِنٕے لُکھ ہلچل تہٕ تٔمِس پیٹھ تھووُکھ اتھہٕ۔\n28.\\tکُنہِ جایہ لوکن تہٕ شریعت تہٕ اتھ جایہ ہیچھناوُن چُھہ سُہ انسان، یُس سارنٕے انسانس تہِ لوکن تہٕ شریعت تہٕ اتھ جایہ ہیچھناوان چُھ، تہٕ بییہِ أنِن یونانۍ تہِ مندرس مَنٛز، تہٕ کورُن اتھ مقدس جایہ آلودہ کرنہٕ۔\n29. (تِکیازِ تِمو اوس امہِ برونہہٕ أمِس سٍتـ̡ شہرس مَنٛز ٹروفیمس وُچھمُت، یُس تِمو خیال اوس زِ پولس اوس مندرس مَنٛز أنمُت۔)\n30.\\tتہٕ سورُے شہر آو منتقل کرنہٕ، تہٕ لُکھ ژٔلِتھ ژٔلِتھ تہٕ تِمو کٔرِکھ پولس تہٕ کٔرِکھ مندرٕ منزٕ نیبر، تہٕ دَرٕ گٔیہِ دروازٕ بند۔\n31.\\tتہٕ ییلہ تِم أمِس مارنہٕ خٲطرٕ گٔیہِ، بینٛڈ کِس چیف کپتانس وٲژ خبر زِ سورُے یروشلم چُھ ہنگامہٕ سٍتـ̡ ہنگامہٕ سٍتـ̡ ۔\n32.\\tیِمو فوراً سپاہ تہٕ سپاہ رٔٹِتھ ژٔلِتھ تِمن نِش ژٔلِتھ تہٕ ییلہ تِمو چیف کپتان تہٕ سپاہ وُچھِ، تِمو دراو پولس مارنہٕ۔\n33.\\tاَمہ پتہٕ آو چیف کپتان نزدیک، تہٕ رٔٹِتھ دِتُن أمِس زٕ زنجیر لٲگِتھ گٔنڈِنُک حُکُم۔ تہٕ پرژھُن زِ سُہ کُس چُھ، تہٕ تٔمۍ کیا اوس کوٚرمُت۔\n34. تہٕ کیٚنٛہہ روو ہجومس منٛز، کیٚنٛہہ بیاکھ چیز، تہٕ ییٚلہ أمس ہنگامہ ہُند یقین معلوم ہیوٚک نہٕ، تٔمۍ دِژ أمس قلعس منٛز نِنُک حُکُم۔\n35.\\tتہٕ ییلہ سُہ ہیرن پیٹھ ووت، تِتھے پٲٹھۍ آو سُہ لُکن ہٕندِ تشددٕ خٲطرٕ سپاہِ سٍتـ̡ پٲدٕ کرنہٕ۔\n36.\\tتکیازِ لُکن ہٕندِس بٔڈِس لُکن ہٕندِس پَتہٕ پَتہٕ وُچھِتھ وُچھِتھ وُچھِو۔\n37. تہٕ یێلہِ پولس قلعس مَنٛز نِنہٕ یِنہٕ وول، تٔمۍ ووٚن چیف کپتانس، کیا بہٕ ہیکہٕ ژےٚ سٍتـ̡ کتھ کٔرِتھ؟ کٔمۍ ووٚن، ژٕ ہیکوا یونانۍ بولِتھ؟\n38.\\tژیہ چھُنہٕ سُہ مصری، یُس یمن دۅہن برونہہ ہنگامہ کٔرِتھ ژور ساس نفر بیابانن منز دِژمُت اوس۔\n39.\\tمگر پولسن ووٚن، بہٕ چُھس اکھ انسان یُس تارسوسُک اکھ یہودی چُھ، {اکھ شہر} چُھ، یُس نہٕ کُنہِ تہِ شہرُک شہری چُھ، تہٕ بہٕ چُھس ژے التجا کران زِ بہٕ کٔرِو لوکن سٍتـ̡ کتھ کرنہٕ۔\n40. تہٕ ییٚلہِ تٔمِس اجازت دِژ، پولس ووت ہیرن پیٹھ، تہٕ کوٚرُن لُکن اتھہٕ سٍتـ̡ اِشارٕ۔ تہٕ ییلہ سٮ۪ٹھاہ خاموشی گٔیہ، تٔمۍ کٔر عبرانی زبانہِ منز وونُن،","1. مردو، بٲے تہٕ باپ، بوزو میٲنۍ دفاع {یُس بہٕ وۅنۍ چانہِ خٲطرٕ کران چُھس}۔\n2.\\t(تہٕ ییلہ تِمو بوز زِ تِمو کٔر تِمن سٍتـ̡ عبرٲنی زبانہِ منز کتھ کرنہٕ، تِمو تھوو زیادٕ ژھۅپہٕ: تہٕ سُہ چُھ ونان،)\n3. بہٕ چُھس پٔزۍ پٲٹھۍ اکھ انسان {یُس} اکھ یہودی چُھ، یُس تارسوسس مَنٛز زامُت چُھ، {اکھ شہر} چُھ، توتہِ چُھس اتھ شہرس مَنٛز گمالییل سٕندِس قدمن مَنٛز پرورش گومُت، {تہٕ} چُھس مٲلن ہٕندِس شریعت کِس کٲمل طریقس مطٲبق پرناونہٕ آمُت، تہٕ اوسُس خدایہ سٍتـ̡ جوش، یِتھ کٔنۍ تۅہہ سارِوٕے از تہِ چُھ۔\n4.\\tتہٕ میہ کٔر یِتھٕ پٲٹھۍ مرنس تام ستاونہٕ، مرد تہٕ زنانہٕ دۅشوٕے قٲد خانس مَنٛز واتناوُن۔\n5.\\tیِتھے پٲٹھۍ چُھہ بٔڈۍ پادٕرۍ تہِ مے گوٲہی دِوان، تہٕ بزرگن ہٕنزِ سارِنٕے جایداد تہٕ یِمو سٍتـ̡ میہ تہِ بٲے چِٹھہِ رٔٹِتھ تہٕ دمشق گۆو تِم أنِتھ یِم یِم یِمن ہٕندِس یورشلمس کُن بٔنِتھ ٲسۍ، سزا دِنہٕ خٲطرٕ۔\n6. تہٕ سپد یہ زِ ییلہ بہٕ پنُن سفر کٔرِتھ، تہٕ دُپہرس بجہِ دمشقس نزدیک ووتمُت، اچانک گۆو اسمانس منزٕ میٲنس اندۍ پکھۍ اکھ زبردست گاش۔\n7. تہٕ بہٕ پیوٚو زمینس پیٹھ، تہٕ بوز اکھ آواز یُس مےٚ ونان چُھ، ساؤل، ساؤل، ژے کیازِ چُھکھ مےٚ ستاونہٕ یوان؟\n8.\\tتہٕ میہ دیت جواب، ژٕ کُس چُھہ، خداوند؟ تہٕ تٔمۍ ووٚن مےٚ زِ بہٕ چُھس ناصرتُک عیسیٰ مسیح، یُس ژے ستاوان چھُ۔\n9.\\tتہٕ یِمو یِمو میہ سٍتـ̡ گاش وُچھمُت، تہٕ کھوژمٕتـ̡ مگر تِمو بوز نہٕ تٔمۍ سٕنز آواز یُس میہ کتھ کران اوس۔\n10. تہٕ مےٚ ووٚن، بہٕ کیا کرٕ خداوند؟ تہٕ خداوند ووٚن مے زِ وۅتھٕ وُتھ، تہٕ گژھ دمشقس مَنٛز۔ تہٕ اَتہِ یِیہِ تۅہہِ سارِنٕے چیزن ہٕنز وَننہٕ یِنہٕ یِم تۅہہِ خٲطرٕ مقرر کرنہٕ آمٕتۍ چھِ۔\n11.\\tتہٕ ییلہ بہٕ تَمہِ گاشہِ ہٕندِس جلال خٲطرٕ وُچھِتھ ہیوٚک نہٕ، تِمن ہٕندِس اتھہٕ سٍتـ̡ یِم پانس سٍتـ̡ ٲسۍ، بہٕ ووت دمشقس مَنٛز۔\n12.\\tتہٕ اکھ انانیاس، یُس شریعت مطٲبق اکھ متقی انسان اوس، یُس سارِنٕے یہودی روزان اوس،\n13.\\tآو میہ نِش تہٕ کھڑا گووُن تہٕ وونُن زِ برادر ساؤل، پنُن گاش رٔٹِو۔ تہ اتھۍ ساعتہ میہ امس کن نظر۔\n14.\\tتہٕ ووٚن سانین آباؤ اجدادن ہٕندِ خداہن چُھ ژیہ ژٲرمُت، یُتھ ژے تٔمۍ سٕنزِ مرضی زانٕن، تہٕ وُچھُن تہٕ تٔمۍ سٕنزِ ٲسٕچ آواز بوزٕنۍ۔\n15.\\tتکیازِ ژے یُس تہِ وُچھمُت تہٕ بوزمُت چُھ، تۅہہ گژھہِ سارِنٕے انسانن ہٕندِ خٲطرٕ تٔمۍ سٕنز گواہ بنٕنۍ۔\n16. تہٕ وۅنۍ کیازِ چُھہ ژیہ ژیرِتھ؟ وۅتھٕ وُتھ، تہٕ بپتسمہ دِیُو، تہٕ پَنٕنۍ گۅناہ واش کٔرِو، خداوند سٕندِ ناوٕ پکار۔\n17. تہٕ سپُد یہِ زِ یێلہِ بہٕ دُبارٕ یروشلم آو تہٕ یێلہِ بہٕ مندرس مَنٛز عبادت کران اوسس، بہٕ اوسُس خۅد گَژھان۔\n18.\\tتہٕ وُچھ سُہ میہ ونان زِ جلدی کرو تہٕ یروشلم منزٕ نیرُن جلدی نیرُن، تکیازِ تِمن میلہِ نہٕ میانہِ متعلق تہنز گواہی ۔\n19.\\tتہٕ میہ ووٚن، خداوند، تِمن چھے پتاہ زِ میہ کٔر پرٮ۪تھ کُنہِ عبادت خانس مَنٛز قٲد تہٕ مار دِژمٕژ یِم تۅہہِ پیٹھ یقین تھاوان ٲسۍ۔\n20. تہٕ ییلہ چانہِ شہید سٹیفن سُند خوُن روٚس، بہٕ تہِ اوسس کھڑا تہٕ تٔمۍ سٕندِس مرنس پیٹھ رضامندی دِژمٕژ، تہٕ تِمن ہُند پوشاک تھووُن یِمو سُہ مارنہٕ آو۔\n21.\\tتہٕ تٔمۍ ووٚن میہ نیرُن، تکیازِ بہٕ سوزٕ ژے دور دور غیر قومن نِش۔\n22.\\tتہٕ تِمو دِژ أمِس اَتھ لفظس سٍتـ̡ سامعین، تہٕ {پتہٕ} تُلِتھ تُلِتھ وونُن، یُتھ {سٲتھی} دوٗر کرُن زمینہٕ پیٹھ، کیازِ یہِ چُھنہٕ لایق۔\n23.\\tتہٕ یِمو کٔرِکھ کرٛٮ۪کہٕ دِنہٕ، تہٕ لٔگِتھ کٔرِکھ ہوہس مَنٛز گرد،\n24. چیف کپتانن دِیُت أمِس قلعس منٛز اننُک حُکُم، تہٕ دِتُن حکم زِ تٔمِس گژھِ کوڑٕ دِتھ معائنہٕ کرنہٕ یُن۔ تاکہ تس گژھہِ معلوم زِ تِم کیازِ ٲسۍ أمِس خٕلاف یُتھ وُچھان۔\n25. تہٕ یێلہِ تِمو أمِس تھوٚنگہٕ لٲگِتھ بٔنِتھ، پولس ووٚن یُس اَتھ سٍتـ̡ کھڑا اوس، کیا تۅہہِ ہٕندِ خٲطرٕ چُھہ حلال یُس رومی تہٕ بےٚ مذمت چُھ؟\n26.\\tییلہ سُہ بوٗز تہٕ وونُن چیف کپتانس تہٕ وونُن زِ ژیہ کیا چُھ کران تہٕ یہِ چُھ رومی ۔\n27.\\tاَمہِ پتہٕ آو چیف کپتان، تہٕ وونُن تٔمِس زِ ژٕ چھُکھ رومی؟ تٔمۍ ووٚن، آ۔\n28.\\tتہٕ چیف کپتانن دیُت جواب، واریاہ رقمہٕ سٍتۍ کٔر مے یہ آزٲدی حٲصل۔ تہٕ پولس ووٚن، مگر بہٕ اوسُس {آزاد} زامُت۔\n29.\\tامہ پتہ دراو تِم أمِس نِش یُس أمِس معائنہٕ کرُن آسہِ: تہٕ چیف کپتان تہِ کھوژُن، ییلہ تس یہ معلوم سپدان اوس زِ سُہ اوس رومی، تہٕ امہ مۅکھہ زِ تٔمۍ اوس أمس پابند کورمُت۔ {أمِس معائنہٕ کٔرِتھ: یا کٔرِکھ أمِس اذیت دِنہٕ}\n30.\\tپگہہ دۅہہ کیازِ تس آسہِ یہ یقین پتاہ زِ تس پیٹھ یہودین ہند الزام اوس، تمٔۍ ترووُن سُہ پننہِ جمٲژ نِش آزاد تہٕ دِتُن چیف پادٕرین تہٕ تِہندِ سارنٕے مجلسس حُکُم، تہٕ کوٚرُن پولس بۄن تہٕ تھووُن تِمن برونہہ کُن۔","1. تہٕ پولس وُچھِتھ وُچھِتھ وونُن، انسانو {تہٕ} بٲے، بہٕ چُھس از تام خدایہِ سٕندِس برونہہ کُن سارِنٕے ضمیرس سٍتـ̡ زندٕ۔\n2.\\tتہٕ اعلیٰ پادٕرۍ انانیاس دِیُت تِمن یُس أمِس سٍتـ̡ کھڑا اوس، تِمن دِیُت أمِس ٲسِس تھپھ دِنُک حُکُم۔\n3.\\tپَتہٕ ووٚن پولس تٔمِس زِ خدایہِ دِیہِ ژے ژے سَفیدٕ دیوار، کیازِ ژٕ بِہتھ بہٕ شریعت پٲٹھـ̡ میانہِ سٍتـ̡ انصاف کٔرِتھ، تہٕ دِیُت میہ شریعت کِس خلاف مارُنُک حُکُم۔\n4.\\tتہٕ یِمو وَنُن یِمو وَنُن زِ تُہۍ چھُکھ خدایہِ سٕندِس اعلیٰ پادٕرِس سٍتـ̡ بدنام کٔرِتھ؟\n5.\\tپَتہٕ ووٚن پولس زِ بہٕ چُھس نہٕ بٲے زِ سُہ اوس اعلیٰ پادٕرۍ، تکیازِ یہِ چُھہ لیکھنہٕ آمُت زِ ژے گژھ نہٕ پننِس لوکن ہٕندِس حاکمس متعلق بد کتھ کٔرٕنۍ۔\n6. مگر ییلہ پولس یہ وُچھ زِ اَکھ حصہٕ چھُ صدوقی تہٕ بیٛاکھ فریسی، تٔمۍ دِژ مجلسس مَنٛز، انسانو {تہٕ} بٲے، بہٕ چُھس فریسی، فریسی سُند نیٚچُو: مُردن ہٕنزِ وۅمید تہٕ قیامتس سٍتـ̡ چُھس میہ سوال۔\n7. تہٕ ییلہ تٔمۍ یہِ ووٚن، فریسیَن تہٕ صدوقین درمیان گٔیہٕ اختلاف تہٕ بٔڈ گٔیہِ تقسیم۔\n8.\\tصدوقین ہُند ونُن چُھ زِ قیامت، نہ فرشتہٕ تہٕ نہ روح، مگر فریسی چھِ دۄشوٕنی ہُند اقرار کران۔\n9.\\tتہٕ گۆو اَکھ بٔڈ کرٛٮ۪کہٕ، تہٕ یِم فریسِین ہٕندِ طرفہٕ ٲسۍ، تہٕ وونُکھ زِ اسہِ چھُنہٕ أمِس شخصس مَنٛز کانہہ بُردی لبنہٕ آمٕژ، مگر اگر کانہہ روح یا فرشتہٕ أمِس سٍتـ̡ کتھ آسہِ کٔرمٕژ، تیلہِ گژھہِ نہٕ أسـ̡ خدایس سٍتـ̡ جنگ کرنہٕ۔\n10.\\tتہٕ ییلہ سٮ۪ٹھاہ اختلاف سپُد، چیف کپتانن دِژ یہ خوفہٕ زِ پولس ییہ تِمو منزٕ ٹُکرٕ ٹُکرٕ کرنہٕ، دِتُن فوجین حکم زِ سُہ گژھن بۄن نِن، تہٕ تِمو منزٕ نِن زبردستی نِن، تہٕ سُہ أنِن قلعس منز۔\n11. تہٕ یێمہِ رٲژ گۆو خداوند أمِس سٍتـ̡ کھڑا تہٕ وونُن، پولس سٍتـ̡ گژھہِ خوش روزُن، یێتھ پٲٹھـ̡ ژے یروشلمس مَنٛز میانہِ مُتلق گوٲہی دِژمٕژ چُھ، تِتھے پٲٹھـ̡ گژھہِ رومس مَنٛز تہِ گوٲہی دِنہٕ۔\n12.\\tییلہ دۅہ ووت، کینہہ یہودی گٔیہِ اِکہٕ وٹہٕ، تہٕ کوٚرُکھ پانس بد دعا کٔرِتھ زِ تِم کرِ نہٕ توٚت تام کھٮ۪وان تہٕ چیٚنہٕ یوٚت تام تِم پولس مٲرِتھ مٲرِتھ۔ {بد دعا تحت: یا، عذابُک حلف ہیتھ }\n13. تہٕ تِم ٲسۍ ژتٲجی کھۄتہٕ زیادٕ یِمو یہِ سٲزِش کٔرمٕژ۔\n14.\\tتہٕ تِم آیہِ بٔڈۍ پادٕرین تہٕ بزرگن نِش تہٕ وونُن، أسۍ چُھہ پانس أکِس بٔڈِس لعنتس سٍتـ̡ بٔڈِتھ بٔنِتھ زِ أسـ̡ چُھہ نہٕ توٚت تام کھٮ۪وان زِ أسـ̡ پولس مارنہٕ آمُت چُھہ نہٕ۔\n15.\\tوۅنۍ چھِو تۅہہ مجلسس سٍتـ̡ اِشارٕ کٔرِتھ زِ سُہ أنِو سُہ پگہہ تام توے نِش، یِتھہٕ پٲٹھۍ تُہۍ أمِس مُتلِق کینہہ پرژھہٕ گٲر کٔرِو: تہٕ أسۍ، یا سُہ یِنہٕ وٲلِس نزدیک، چھِو أمِس مارنہٕ خٲطرٕ تیار۔\n16. تہٕ ییلہ پولس سٕنزِ بینہِ ہٕندِس نیچِوِ تِہٕندِس انتظارس منز روزنہٕ آمٕژ خبر بوٗز، سُہ گوٚو قلعس مَنٛز ژاو تہٕ ووٚنُن پولس ۔\n17.\\tپَتہٕ بُلوو پولس أکِس صٔدِرس نِش تہٕ وونُن، یہِ جوان أنِو بٔڈِس کپتانس نِش، تکیازِ أمِس چُھ أمِس کُنہِ کتھ وننہٕ خٲطرٕ۔\n18.\\tتێلہِ نِیوو أمِس تہٕ أنِن سُہ بٔڈِس کپتانس نِش، تہٕ وونُن، پولس قٲدِ بُلووُن میہ نِش تہٕ دُعا کٔرٕن میہ نِش یہِ جوان پانس نِش، یُس تۅہہِ کینہہ ونُن چُھ۔\n19.\\tاَمہ پتہٕ رٔٹِتھ بٔڈۍ کپتانن أمِس اتھہٕ تھپھ کٔرِتھ ژٔلِتھ ژیہ ژیہ کیا چُھہ وَنُن؟\n20.\\tتہٕ ووٚن، یہودی چُھہ تۅہہِ خٲہش کرنہٕ خٲطرٕ رضامندی ظٲہر کٔرمٕژ زِ ژے کٔرِو پَلہٕ پولس مجلسس مَنٛز اَننہٕ، گویا تِم کرِ أمِس سٍتـ̡ کُنہِ حدس تام پرژھہٕ۔\n21.\\tمگر تِمن ہٕندِس انتظارس منز چُھہ تِمو منزٕ ژتٲجی کھۅتہٕ زیادٕ نفر یِمو پانس سٍتـ̡ قَسم کٔرِتھ چُھہ زِ تِم کرِ نہٕ توٚت تام کھٮ۪وان تہٕ چیوٚن نہٕ توٚت تام یِم أمِس مٲرِتھ مٲرِن، تہٕ وۄنۍ چھِ تِم تۅہہِ نِش وعدٕ ژھارنہٕ خٲطرٕ تیار۔\n22.\\tتہ دِژ چیف کپتانن نوجوانس نیرُن، تہٕ دیتُن حکم زِ ژے چھے نہٕ یِم چیز میہ ہٲومٕژ۔\n23.\\tتہٕ تٔمۍ بُلوو زٕ ہتھ سپاہ قیصریہ گژھنہٕ خٲطرٕ تیار، تہٕ گُرۍ سوار تریہ تہٕ داہ تہٕ نیزٕ سوار زٕ ہتھ رٲژ ہٕندِس تریمہٕ گھنٹس منز۔\n24.\\tتہٕ دِیُن درندٕ یُتھ تِم پولس رٔٹِتھ تہٕ اَنِن فیلکس گورنرس نِش۔\n25.\\tتہٕ تٔمۍ لیوکھ یِتھٕ پٲٹھۍ اکھ چِٹھۍ:\n26. کلاڈیس لیسیاس، بہترین گورنر فیلکس {سوز} سلام۔\n27.\\tیہِ شخٕص آو یہودی نِش نِنہٕ، تہٕ یِمو سٍتـ̡ مارنہٕ یُن، پتہٕ آو بہٕ اکھ لشکر ہیتھ تہٕ بچٲوُن سُہ رومی۔\n28.\\tتہٕ ییلہ میہ یہ وجہ معلوم آسہِ ہے زِ تمو کٔر تس پیٹھ الزام لگاونہٕ، بہٕ اوٚن سُہ تِہنزِ مجلسس مَنٛز۔\n29.\\tیٔمِس پیٹھ میہ تِہٕندِس قونوٗنٕکۍ سوالَن ہُند الزام لگاونہٕ آمُت اوس، مگر تٔمِس سٕندِس اِلزامس پیٹھ اوس نہٕ کانہہ تہِ موتُک یا بانڈُک لایق قرار دِنہٕ آمُت۔\n30.\\tییلہ میہ یہ وننہ آو زِ یہودی کتھہ پاٹھۍ چھہِ أمس شخصس پیاران، میہ سوز سیدِ سیود ژے نِش، تہٕ دِتُن تٔمۍ سٕندِس ملزمن تہِ حکم زِ تِمن ہٕندِس خٕلاف کیا چھُ۔ الوداع۔\n31. پتہٕ سپاہیو یُتھ زن تمن حکم اوس دِنہٕ آمُت، نیو پال تہٕ أنِن رٲژ اینٹیپیٹریس نِش۔\n32.\\tپوٚت دۅہہ دراو تِم گُرۍ سوارِ أمِس سٍتۍ نیرنہٕ خٲطرٕ، تہٕ گٔیہ قلعس منز واپس۔\n33.\\tییمہِ سٍتـ̡ یێلہِ تِم قیصریہ وٲتِتھ گورنرس نِش خط واتنوو، پولس تہِ اوس أمِس برونہہ کُن پیش۔\n34.\\tتہٕ ییلہ گورنرن چِٹھۍ پٔرۍ، تٔمۍ پرژھ سُہ کُس صوبہٕ۔ تہٕ ییلہ تس یہ سمجھ زِ {سُہ} اوس سیلیشیاہُک؛\n35. تٔمۍ ووٚن زِ بہٕ بوزٕ تۅہہ ییلہ تُہند الزام تہِ یِن۔ تہٕ دِیُت أمِس ہیرودس سٕندِس فیصلہٕ خانس مَنٛز تھاونُک حُکُم۔","1. تہٕ پانژو دۅہہٕ پَتہٕ ووت انانیاس بٔڈۍ پادٕرۍ سٍتـ̡ تہٕ أکِس مقرر سٍتـ̡ تہٕ {ناو} ترٹولَس سٍتـ̡ ، یٔمۍ گورنرس پولس خلاف اطلاع دِژ۔\n2. تہٕ ییلہ أمِس بُلاونہٕ آو ، ترٹولسن ہیوٚت تٔمِس پیٹھ الزام لگاونہٕ تہٕ وونُن، یہ وُچھِتھ زِ تۅہہِ سٍتـ̡ چُھہ أسـ̡ سٮ۪ٹھاہ سکوُن حٲصل سپدان، تہٕ یێمہِ قومہٕ سٍتـ̡ چُھہ تُہٕندِس دٲیرس سٍتـ̡ سٮ۪ٹھاہ لایق کٲم کرنہٕ یِوان،\n3. أسۍ چھِ ہمیشہٕ، تہٕ پرٮ۪تھ جاین ، سارِوٕے کھۄتہٕ شریف فیلکس، پوٗرٕ شُکرگزاری سان قبول کران۔\n4.\\tبہٕ چھُس ژے دُعا کران زِ ژے بوزِو اسہِ پننہِ معافی ہٕندِس بارس منز کینہہ لفظ۔\n5.\\tتکیازِ اسہِ لوٚب یہِ شخٕص {a} وُپھ تہٕ سارِنٕے دُنیاہس منز سارِنٕے یہودین مَنٛز بغاوت کرنُک تہٕ ناصرین ہٕندِس فرقُک سرغنہٕ:\n6.\\tیُس تہِ چُھہ مندرس ناپاک کرُن: یُس أسۍ رٔٹِتھ تہٕ سانہِ شریعت مطٲبق فیصلہ کرُن۔\n7. مگر چیف کیپٹن لیسیاس آو {اسہِ پیٹھ}، تہٕ سٮ۪ٹھاہ تشدد سان نِیوُن سُہ سانہِ اتھہٕ نِش،\n8.\\tپننین ملزمن ہُند حُکُم دِیُن زِ تۅہہِ کُس یِمن سارِنٕے چیزن ہُند علم حٲصِل کٔرِتھ، یِمن ہُند أسۍ أمِس پیٹھ الزام لگاوان چھِ۔\n9.\\tتہٕ یہودی تہِ کٔر یہ ؤنِتھ رضامندی زِ یِم چیز چھِ یِتھے پٲٹھۍ آسان۔\n10. پَتہٕ پَتہٕ پَتہٕ پَتہٕ گورنرن أمِس کتھ کرنہٕ خٲطرٕ اِشارٕ کٔرِتھ، دِیُت جواب، یوتاہ بہٕ چُھس پتاہ زِ ژٕ چُھہ واریاہو ؤرِیو پیٹھٕ یَتھ قومُک قاضی روٗدمُت، بہٕ چُھس پانس سٍتـ̡ زیادٕ خۄش سان جواب دِوان:\n11. تکیازِ ژیہ یہ سمجِتھ زِ بہٕ چُھس عبادت کرنہٕ خٲطرٕ یروشلم تام ووتمُت وُنہِ تہِ صرف باہ دۅہ۔\n12.\\tتہٕ تِمو وُچھ نہٕ میہ مندرس مَنٛز کٲنٛسہِ شخصس سٍتـ̡ بحث کران، نہ کُنہِ تہِ کُنہِ شخصس سٍتـ̡ لُکن ہٕندِس سٍتـ̡ تُلنہٕ آمُت، نہ عبادت خانن مَنٛز تہٕ نہ شہرس مَنٛز۔\n13.\\tنہ ہیکن تم چیز ثٲبت کٔرِتھ یمن پیٹھ تم وۅنۍ میہ الزام لگاوان چھہِ۔\n14. مگر بہٕ چُھس ژے برونہہ کُن اقرار کران زِ یێمہِ پٲٹھـ̡ تِم بدعتی ونان چھِ، تِتھٕ پٲٹھـ̡ چُھس بہٕ پننین آباؤ اجدادن ہٕندِس خدایہِ سٕنز عبادت کران، یِمن سارِنٕے چیزن پیٹھ ایمان تھاوان چُھہ یِم شریعت تہٕ پیغمبرن مَنٛز لیکھنہٕ آمٕژ چھِ۔\n15. تہٕ خدایس سٍتـ̡ وۅمید تھاوٕنـ̡ ، یُس تِم پانہٕ تہِ اجازت دِوان چُھ، زِ مُردن ہُند قیامت، نیک تہٕ ناانصاف۔\n16. تہٕ یَتھ مَنٛز چُھس بہٕ پنُن پان ورزش کران، یُس ہمیشہٕ خدایہِ سٍتـ̡ تہٕ انسانس سٍتـ̡ جرم نِش پاک روزُن۔\n17. وۅنۍ آو واریاہو ؤریو پَتہٕ بہٕ پننِس قومس خٲطرٕ خیرات تہٕ نذرانہ اننہِ۔\n18.\\tییمہِ سٍتـ̡ ایشیاہٕکۍ کینہہ یہودی وُچھ میہ مندرس مَنٛز پاکیزگی حٲصل کٔرِتھ، نہ بٔڈِس سٍتـ̡ تہٕ نہ ہنگامہ سٍتـ̡ ۔\n19.\\tکُس گژھہِ ژے برونہہ کُن آسُن، تہٕ اعتراض کرُن، اگر تِم میانہِ خلاف آسہِ۔\n20.\\tنتہٕ یِمو یِمن وَنُن یێلہِ بہٕ مجلسس برونہہ کُن کھڑا آسہِ،\n21.\\tامہِ اکہِ آوازِ سٍتـ̡ یێمہِ سٍتـ̡ چُھس بہٕ تِمن مَنٛز کھڑا روُن، مُردن ہٕندِس قیامتس پیٹھ چھُ اَز تہِ سوال کٔرِتھ ژے سٍتـ̡ پرژھہٕ گٲر کٔرِتھ۔\n22.\\tتہٕ ییلہ فیلکس یِم کتھٕ بوز، تٔمۍ کٔر یِم کتھ بٔنِتھ تہٕ وونُن، ییلہ لیسیاس چیف کپتان بۄن یِیہ، بہٕ گژھہٕ تُہند معاملہٕ پورٕ پٲٹھۍ۔\n23.\\tتہٕ تٔمۍ دِیُت أکِس صد پٲٹھـ̡ حُکُم زِ سُہ کرِ پولس رٔٹِتھ تہٕ أمِس دِیہِ آزادی، تہٕ سُہ گژھِ نہٕ پننِس واقفیت سٍتـ̡ أمِس نِش یِنـ̡ منع کرنہٕ۔\n24. تہٕ کینژَو دۅہو پَتہٕ ییلہ فیلکس پننہِ زنانہِ ڈروسیلا سٍتـ̡ آو، یۄسہٕ یہودی ٲس، تٔمۍ سوٗز پولس سٍتـ̡ تہٕ بوزُن أمِس مسیحس پیٹھ ایمانہٕ مُتعلِق۔\n25.\\tییلہ تٔمۍ نیکی ، مزاج، تہٕ یِنہٕ وٲلِس فٲصلس متعلق استدلال کوٚر، فیلکس لوٚگ تھر تھر تہٕ جواب دِژُن، یَتھ وقتس خٲطرٕ گژھ پنٕنۍ وتہِ۔ ییلہ میہ کانہہ آسان موسم آسہِ، بہٕ کرٕ ژے بلاو۔\n26.\\tتس ٲس یہ تہِ وۅمید زِ تس گژھہِ پولس نِش پونسہٕ دِنہٕ، یُتھ سُہ گژھہِ أمِس راوُن، اَمہِ مۄکھٕ سوٗزُن أمِس سٍتـ̡ اکثر تہٕ أمِس سٍتـ̡ رٲبطہٕ۔\n27. مگر دۄیو ؤریو پتہٕ آو پورسیئس فیسٹس فیلکس سٕندِس کمرس منز: تہٕ فیلکس اوس یہودین خوشی ہاونہٕ خٲطرٕ تیار، تروو پولس پابند۔","1. وۅنۍ ییلہ فیسٹس صوبس منز آو، تریہ دۅہہ پَتہٕ ووت سُہ قیصریہ پیٹھٕ یروشلمس تام۔\n2. اَمہِ پَتہٕ دِژ تٔمِس پادٕرِ تہٕ یہودی سردارَن پولس خٕلاف، تہٕ کٔرٕن أمِس مُتعلِق،\n3.\\tتہٕ أمِس سٍتـ̡ احسان یژھان، زِ سُہ سوزِ أمِس یروشلمس کُن تہٕ مارنہٕ مۅکھٕ وتہِ پیٛارُن۔\n4. مگر فیسٹسن دیُت جواب زِ پال گژھہِ قیصریہ منز تھاونہٕ یُن، تہٕ سُہ گژھہِ پانہٕ جلدٕے نیرُن۔\n5.\\tتَمہِ کِنۍ ووٚن تِم یُس تہٕ یُس تہِ قٲبل چھُ، گژھن میہ سٍتـ̡ بٔنِتھ تہٕ أمِس شخصس سٍتـ̡ اگر کانہہ بد کاری آسہِ۔\n6. تہٕ ییلہ سُہ تِمن منز دہن دۅہن کھۄتہٕ زیادٕ روزُن، سُہ ووت قیصریہ کُن۔ تہٕ دوٚیمہِ دۅہہ دِژ فیصلہٕ چہ نشستس پیٹھ بِہتھ پال اننُک حُکُم۔ {مزید ...: یا، یتھ کٔنۍ زن کنہہ کاپیہٕ پران چِھ، ٲٹھ یا دہن دوہن کھوتہٕ زیادٕ نہٕ}\n7.\\tتہٕ ییلہ سُہ آو یُس یروشلم پیٹھٕ بۄن آمُت، یِم یہودی اندۍ پٔکھۍ کھڑا گٔیہِ، تہٕ کٔرٕن پولس خلاف واریاہ تہٕ سنگین شکایت، یِم نہٕ تِم ثٲبت کٔرِتھ ہیوٚک نہٕ۔\n8. ییلہ زن تٔمۍ پانس خٲطرٕ جواب دِژ، نہ یہودین ہٕندِس قانونس خلاف، نہ ہیکلس خلاف، تہٕ نہ وُنہِ تام قیصرس خلاف، مے کٔر نہٕ کانہہ تہِ جرم ۔\n9.\\tمگر فیسٹس، یُس یہودین خۅش کرنہٕ خٲطرٕ تیار اوس، دیُت پولسُک جواب تہٕ وونُن، کیا ژٕ گژھ یروشلمس تام تہٕ یِمن چیزن ہُند فیصلہ ییہ میانہِ برونہہ کُن؟\n10.\\tپَتہٕ ووٚن پالس، بہٕ چُھس قیصر سٕندِس حکمس پیٹھ کھڑا یُس میہ فیصلہ گژھہِ کرُن: یہودین سٍتـ̡ چُھہ نہٕ میہ کانہہ غلطی کٔرمٕژ، یێتھ زن ژے بخوبی زانان چُھ۔\n11. یێلہِ بہٕ مُجرِم آسہِ، یا کانہہ تہِ موتُک لایق کٲم آسہِ کٔرمٕژ، بہٕ چُھس نہٕ مرنہٕ نِش انکار کٔرِتھ، مگر یێلہِ یِمو منزٕ کانہہ تہِ چیز آسہِ نہٕ یِمن پیٹھ یِم الزام لگان چھِ، کانہہ تہِ ہیکہِ نہٕ مے تِمن حوالہٕ کٔرِتھ۔ بہٕ چُھس سیزرس اپیل کران۔\n12.\\tتمہِ پتہ ییلہ تٔمۍ مجلسس سٍتۍ کتھ باتھ کٔر، دیتُن جواب، کیا ژے چھوا سیزرس اپیل کٔرمٕژ؟ سیزرس نِش گژھ ژے گژھُن۔\n13. تہٕ کینژَو دۄہو پتہٕ آیہِ بادشاہ ایگریپا تہٕ برنیس فیسٹسَس سلامی کرنہٕ خٲطرٕ سیزریہ ۔\n14.\\tتہٕ ییلہ تِم واریاہ دۅہ ٲسۍ، فیسٹسن کٔر بادشاہس برونہہ کُن پولس سُند سبب اعلان تہٕ وونُن زِ فیلکس سٕندِ دٔسۍ چُھ اکھ خاص شخٕص بٔنِتھ روزمُت:\n15.\\tکِس بارس مُتلِق ییلہ بہٕ یروشلمس مَنٛز اوسس، بٔڈۍ پادٕرۍ تہٕ یہودی بزرگو دِژ میہ اطلاع، تہٕ تٔمِس خلاف فیصلہٕ گژھُن یژھان۔\n16. یٔمِس مےٚ جواب دِیُت، یہ چُھنہٕ رومین ہُند طریقہٕ زِ سُہ چُھ کٲنٛسہِ تہِ شخٕص مرنہٕ خٲطرٕ دِنہٕ آمُت، امہ برونہہ زِ یٔمِس مُلزِم آسہِ أمِس بُتھِ کُن الزام لگاونہٕ یِوان، تہٕ أمِس خٕلاف دِنہٕ آمٕتۍ جُرمَس مُتعلِق چھُ پانَس جواب دِنُک اجازت۔\n17. لہذا، ییلہ تِم یور وٲتۍ، پگاہ کُنہِ تہِ ژیر ورٲے بہٕ بیوٹھ فیصلہٕ چہ نشستس پیٹھ، تہٕ دیتُن أمس نفرس نیبر اننُک حُکُم۔\n18.\\tیمن خلاف ییلہ الزام لگاون والیو کھڑا گٔیہ، تمو ووت نہ تمن چیزن ہند کانہہ الزام یُس میانہِ خیالہ اوس:\n19.\\tمگر تس خلاف ٲسۍ پننین توہم پرستی تہٕ أکِس عیسیٰ مسیحس متعلق کینہہ سوال، یُس موٗدمُت اوس، یُس پولس زندٕ آسنُک تصدیق کوٚر۔\n20.\\tتہٕ کیازِ میہ اوس یِتھۍ سوالن پیٹھ شک کورمُت، میہ پرژھ سُہ کیا یروشلم گژھِ، تہٕ یِمن معاملن ہُند فیصلہ ییہ کرنہٕ۔ {میہ اوس شک کٔرتھ...: یا، میہ اوس شک زِ اتھ متعلق کتھہ پاٹھۍ کرو پرژھہ}\n21.\\tمگر ییلہ پالن آگسٹس سٕنزِ سماعتس خٲطرٕ مخصوص روزنٕچ اپیل کٔر، میہ دیُت حکم زِ سُہ روزِ توٚت تام روزُن یوٚت تام بہٕ سُہ سیزرس نِش سوزنہٕ۔ {سماعت: یا، فیصلہٕ}\n22.\\tاَمہ پتہٕ ووٚن اگریپاہن فیسٹس، بہٕ تہِ بوزٕ أمس نفرس پانے۔ پگہہ تام ووٚن تٔمۍ سُند بوزُن۔\n23.\\tتہٕ پگہٕ ییلہ اگریپا آو تہٕ برنیس آو سٮ۪ٹھاہ شوکت سان تہٕ شہر کین اہم نفرن سٍتۍ، فیسٹس سٕندِس حُکمس پیٹھ آو پال برونہہ کُن اننہٕ۔\n24. تہٕ فیسٹسن ووٚن، بادشاہ اگریپا، تہٕ سٲری انسان یُس اسہِ سٍتـ̡ موجود چُھ، تہٕ یێمہِ سٍتـ̡ یہودی سٍتـ̡ میہ سٍتـ̡ وُچھمُت، یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ یہودی سٍتـ̡ چُھہ یێمہِ سٍتـ̡ وُچھمُت، یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ یہودی سٍتـ̡ سٍتـ̡ سٍ\n25. مگر ییلہ میہ یہ وُچھ زِ تٔمۍ اوس نہٕ موتس لایق کانہہ تہِ کٲم کٔرمٕژ، تہٕ تٔمۍ چُھ پانہٕ آگسٹسس اپیل کٔرمٕژ، مے کوٚر تس سوزنُک ارادٕ۔\n26.\\tیٔمِس مُتلق چُھنہٕ میہ پننِس آقاہس لیکھُن کانہہ خاص کتھ چھُ۔ اَمہِ مۄکھٕ ووت بہٕ سُہ ژےٚ برونہہ کُن، تہٕ خاص کر ژےٚ برونہہ کُن، اے بادشاہ اگریپا، یُس معائنہٕ کرنہٕ پتہٕ آسہٕ مےٚ کینہہ لیکھُن۔\n27.\\tتکیازِ میہ چھہ یہ غیر معقول باسان زِ قٲد سوزُن چھہ غیر معقول، تہٕ نہ چھہ تس خلاف دِنہٕ آمتین جُرمَن ہٕنز نشاندہی کرنہٕ خٲطرٕ۔","1. اَمہ پتہٕ ووٚن اگریپاہَن پولس پانس کُن کتھ کرنُک اجازت۔ پَتہٕ پٔھلٲو پولس اَتھٕ تہٕ دیتُن پانَس جواب:\n2. بہٕ چُھس پانس خۅش سمجھان، بادشاہ اگریپا، تکیازِ بہٕ کرٕ از دۅہہ ژے برونہہ کنہِ تِمن سارِنٕے چیزن ہُند جواب یِمن پیٹھ میہ یہودین ہُند الزام چُھ:\n3.\\tخاص کر {امہ مۅکھہ زِ بہٕ چھُس زانان زِ ژیہ چھُس تمام رسمن تہٕ سوالن مَنٛز مٲہر، یِم یہودین منز چھِ، اَمہِ مۅکھٕ چُھس بہٕ ژے صبرٕ سان بوزُن۔\n4. میانہِ جوانی پیٹھے میانہِ طرزِ زندگی یُس یروشلمس منز میانین قومن منز گۅڈنچہ لٹہِ اوس، سارِنٕے یہودی زانان چھُ۔\n5. یُس میہ گۅڈہ پیٹھے زانان اوس، اگر تم گوٲہی دِن، زِ سانہِ مذہبک سارِوٕے کھۄتہٕ سخت فرقہٕ پتہٕ اوسُس بہٕ فریسی روزان۔\n6. تہٕ وُنۍ چُھس بہٕ کھڑا تہٕ چُھس پننین مٲلن سٍتـ̡ خدایہِ سٕندِ وعدٕ کِس وۅمید سٍتـ̡ فیصلہ کرنہٕ آمُت:\n7. یتھ کُن سانین بارہ قبیلن ہُند وعدٕ چُھہ یِنٕچ وۅمید کران یُس دۅہ تہٕ راتس خدایہ سٕنز خدمت کران چُھ، یِنٕچ وۅمید چھِ۔ کمہِ خٲطرٕ چُھ بادشاہ ایگریپا، میہ چُھ یہودین پیٹھ الزام لگاونہٕ آمُت۔ {دۄہ تہٕ رات: Gr. رات تہٕ دۄہ}\n8. یہ کیازِ گژھہِ تۅہہِ سٍتـ̡ ناقابل یقین چیز سمجھنہٕ یُن، زِ خدایہ کرِ مرن زندٕ۔\n9.\\tمیہ اوس پزۍ پاٹھۍ پانس سیتۍ سونچتھ زِ میہ پزِ حضرت عیسیٰ ناصری سٕندِس ناوس برعکس واریاہ کٲم کرٕنۍ۔\n10.\\tیروشلمس مَنٛز کُس کُس کتھ کٔر میہ تہِ: تہٕ واریاہن مقدسن کٔر میہ جیلس مَنٛز، یُس بٔڈۍ پادٕرین ہٕندِ طرفہٕ اختیار حٲصِل کٔرِتھ۔ تہٕ ییلہ تِم مارنہٕ آیہ، مے دِژ تمن خلاف پنٕنۍ آواز۔\n11.\\tتہٕ میہ دِژ تِمن پرٮ۪تھ عبادت خانس مَنٛز اکثر سزا، تہٕ کُفر کُن کُفر کرنہٕ خٲطرٕ مجبوٗر۔ تہٕ تِمن خلاف سٮ۪ٹھاہ پاگل آسنہٕ کِنۍ کٔر مے تمن عجیب شہرن تام ستاونہٕ۔\n12.\\tییلہ بہٕ سردار پادٕرین ہٕندِ اِختِیار تہٕ حکم ہٮ۪تھ دمشق گوٚو،\n13.\\tدوپہرس اے بادشاہ، وُچھ میہ وتہِ منز آسمانہ پیٹھہ اکھ گاش، آفتابہ کس گاشس پیٹھ، یُس میہ اندۍ پکھۍ چمکان اوس، یُس میہ سیتۍ سفر کران اوس۔\n14. تہٕ ییلہ أسۍ سارِوٕے زمینہِ پیٹھ پیوٚو، میہ بوز اکھ آواز یُس میہ سٍتـ̡ کتھ کران اوس، تہٕ عبرانی زبانہِ منز ونان چُھ، ساؤل، ساؤل، ژے کیازِ چُھکھ میہ ستاونہٕ آمُت؟ {یہِ} چُھہ ژےٚ خٲطرٕ مُشکِل زِ کُنہ\n15. تہٕ مےٚ ووٚن، ژٕ کُس چُھ، خداوند؟ تہٕ تٔمۍ ووٚن، بہٕ چُھس عیسیٰ یس ژے ستاوان چھُ۔\n16.\\tمگر تھوٚد تہٕ کھڑا گژھِو پننین قدمن پیٹھ، کیازِ بہٕ چُھس ژے امہِ مقصدٕ خٲطرٕ ظٲہر گومُت، یِمن دۄشوٕنی چیزن ہٕندِس مَنٛز تہٕ یِمن چیزن مَنٛز بہٕ ژے ظٲہر سپدِ۔\n17.\\tژے لُکن نِش تہٕ غیر قومن نِش نجات دِنہٕ خٲطرٕ، یِمن نِش بہٕ وۅنۍ ژے سوزان چھُ،\n18.\\tتِمن ہٕنزِ أچھ کھولنہٕ خٲطرٕ، {تہٕ} تہٕ {تِم} تاریک پیٹھٕ گاشس کُن پھیرٕن، تہٕ شیطان سٕندِ طاقتہٕ سٍتـ̡ خدایہ سٍتـ̡ یُس تِمن گۅنہن ہٕنز معافی حٲصل کٔرِتھ، تہٕ تِمن مَنٛز وَراثت حٲصِل کٔرِتھ یُس میانہِ مَنٛز ایمان سٍتـ̡ پاک سپدان چُھ۔\n19. اے بادشاہ ایگریپا، بہٕ اوسُس نہٕ آسمانی وژنس نافرمان:\n20. مگر دِژُن تِمن گۅڈٕ دمشقس منز، یروشلمس منز، تہٕ یہوداہ کین سارنٕے ساحلن منز، تہٕ {پتہٕ} غیر قومن ہٲوِتھ زِ تِم گژھن توبہ کرُن تہٕ خدایس کُن پھیرُن، تہٕ توبہ کرنہٕ خٲطرٕ کامہِ کرنہٕ۔\n21.\\tیِمو وجہو کِنۍ رٔٹۍ یہودی میہ مندرس مَنٛز، تہٕ گٔیہِ میہ مارنہٕ خٲطرٕ۔\n22. اَمہِ مۄکھٕ چُھس خدایہِ سٕنز مدد حٲصِل کٔرِتھ، بہٕ چُھس از تام لۄکٹِس تہٕ بٔڈِس گوٲہی دِوان، یِم پیغمبرن تہٕ موسىٰ ہن وَننہٕ آمٕتۍ چھِ:\n23. یُس مسیح گژھہِ مصیبت دِنہٕ، تہٕ سُہ گژھہِ گۄڈنیُک سُہ یُس مُردٕ منزٕ زندٕ روزُن، تہٕ لوکن تہٕ غیر قومن ہٕندِ خٲطرٕ گاش ہاوُن۔\n24. تہٕ یێلہِ تٔمۍ پانس خٲطرٕ کتھ کٔر، فیسٹسن وون بَڑِ آوازِ سٍتۍ، پال، تہٕ ژٕ چُھکھ پانس نِش ۔ واریاہ ہیچھن چھہ ژیہ پاگل بناوان۔\n25.\\tمگر تٔمۍ ووٚن، بہٕ چُھس نہٕ پاگل، سارِوٕے کھۄتہٕ شریف فیسٹس۔ بلکہ کٔرِو سچائی تہٕ سنجیدگی ہٕندۍ کلام۔\n26.\\tکیازِ بادشاہس چُھ یِمن چیزن ہُند پتاہ تہٕ یٔمِس برونہہ کُن بہٕ آزادانہ کتھ کران چُھس، کیازِ بہٕ چُھس یقین زِ یِمو منزٕ چُھنہٕ کانہہ تہِ چیز أمِس نِش پوشیدٕ روزان۔ تکیازِ یہ کتھ ٲس نہ کُنہِ کونس منز کرنہ آمژ۔\n27. بادشاہ اگریپا، کیا تُہۍ چھِو پیغمبرن پیٹھ یقین تھاوان؟ میہ چھیہ پتاہ زِ ژیہ چھکھ یقین تھاوان۔\n28. اَمہ پتہٕ ووٚن اگریپاہَن پولس زِ ژے چُھہ میہ عیسٲے بننہٕ خٲطرٕ آمادہ کران۔\n29. تہٕ پولس ووٚن، بہٕ چُھس خدایہِ سٍتـ̡ یێلہِ نہ صرف ژے بلکہ یِم سٲری یُس از میہ بوزان چُھ، تِمن ہٕندِس پٲٹھـ̡ تہٕ یِتھے پٲٹھـ̡ چُھس۔\n30. تہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، بادشاہ ووٚتھ، تہٕ گورنر تہٕ برنیس، تہٕ تِم یِم تِمن سۭتۍ بِہِتھ:\n31.\\tتہٕ ییلہ تِم اَکہِ طرفہٕ گٔیہِ، تِمو کٔر پانہٕ أکِس سٍتـ̡ کتھ باتھ کٔرِتھ زِ یہِ انسان چُھہ نہٕ موتس لایق تہٕ بندھن لایق کانہہ تہِ کٲم کران۔\n32.\\tاَمہ پتہٕ ووٚن اگریپاہن فیسٹس زِ یہِ نفر آسہ ہا آزاد کرنہٕ آمُت، اگر نہٕ تٔمۍ سیزرس اپیل کٔرِتھ آسہِ۔","1. تہٕ ییلہ یہ طے آو کرنہٕ زِ اسہِ پزِ اٹلی کُن سفر کرُن، تمو واتنوو پال تہٕ کینہہ باقٕے قٲد، یُس آگسٹس سٕندِ بینڈُک سینچورین اوس جولیس ناوُک {ایک}۔\n2. تہٕ ادرامیٹیم کِس ٲبی جہازس منز دٲخل گژھِتھ دراو اسہِ لانچ ، یمیک مطلب ایشیا کین ساحلن پیٹھ سفر کرُن۔ {اَک} اریسٹارکس، تھیسالونیکا ہُک مقدونی، اسہِ سٍتـ̡ آسُن۔\n3. تہٕ دوٚیمہِ دۅہہ کٔر اسہِ سیدونس کُن۔ تہٕ جولیس کٔر شائستگی سان پولس التجا تہٕ دِژٕن پننین دوستن نِش گژھنٕچ آزادی۔\n4. تہٕ ییلہ أسۍ تتہِ پیٹھٕ روانہٕ کٔرۍ، أسۍ دراو قبرص تلہ کنہِ، تکیازِ واو اوس برعکس۔\n5.\\tتہٕ ییلہ أسۍ سِلیشیا تہٕ پامفیلیا کِس سمندرس اپارِ سفر کٔرۍ، أسۍ وٲتۍ لیشیا کِس {اکھ شہر} میرا کُن۔\n6. تہٕ تتہِ لوٚب اسکندریہ ہُک اکھ جہازٕ یُس اٹلی کُن سفر کران اوس۔ تہٕ تٔمۍ ترٛٲو اسہِ اَتھ منٛز۔\n7.\\tتہٕ ییلہ أسۍ وارہ وارہ وارہ دۅہن سفر کٔرۍ، تہٕ کنیڈسس خلاف کم آو تہٕ واو آو نہٕ اسہِ دِنہٕ، اسہِ دراو کریٹس تلہ کنہِ، سالمونس خٕلاف۔ {کریٹ: یا، کینڈی}\n8.\\tتہٕ مشکل سٍتۍ ووت تتھ جایہ یتھ فیئر ہیونز ونان چھِ۔ یَتھ نکھٕ اوس شہر {of} Lasea۔\n9. وۅنۍ ییلہ واریاہ وقت گُزراونہٕ آو، تہٕ ییلہ بحری سفر اوس وۅنۍ خطرناک گومُت، تکیازِ روزٕ اوس وۅنۍ گۅڈے مۅکلیومُت، پولسن دِژ تمن نصیحت، {روزہ: روزٕ اوس سٔتِمہِ ریتہٕ کِس دٔہمہِ دۅہہ}\n10.\\tتہٕ تِمن وونُن، جناب، بہٕ چُھس باسان زِ یہ سفر گژھہِ نہ صرف لوڈِنگ تہٕ جہازُک بلکہ سانہِ زُوُن تہِ نقصان تہِ۔ {زخم: یا، زخم}\n11. بہر حال اوس سینچورین جہازک مالک تہٕ مٲلک سُند یقین تھاوان، تمن چیزو کھوتہٕ زیادٕ یم پال ٲس وننہٕ آمژ۔\n12. تہٕ چونکہ یہ پناہ گاہ ٲس نہٕ وندٕ خٲطرٕ آسان آسان، زیادٕ حصہٕ اوس تتہٕ نیرنُک مشورٕ دِتمُت، اگر کُنہِ تہٕ طریقہٕ سۭتۍ تم فینیسس تام وٲتِتھ، {تہٕ تتہٕ} وندس تام۔ {یُس} چُھ کریٹُک اکھ پناہ گاہ، تہٕ جنوب مغرب تہٕ شمال مغربس کُن واقع۔\n13.\\tتہٕ ییلہ جنوبی واو لۅتہٕ لۅتہٕ واو ، یہ خیال کٔرتھ زِ تِمو چُھ {پنُن} مقصد حٲصل کورمُت، تِمو دراو کریٹس نزدیک۔\n14.\\tمگر کینژس کالس پتہ آو اتھ خلاف اکھ طوفانی واو یتھ یوروکلیڈن ونان چھہِ۔ {arose: or, beat}\n15.\\tتہٕ ییلہ جہازٕ رٔٹتھ تہٕ ہوہس منز ہیوٚک نہٕ ہیوٚک، اسہِ دِژ {أمِس} گٲڑۍ۔\n16.\\tتہٕ أکِس خاص جزیرس تلہ کنہِ یتھ کلاڈا ونان چھِ، اسہِ ٲس ناوِ منز یِنہٕ خٲطرٕ واریاہ کٲم کٔرمٕژ۔\n17.\\tیُس ییلہ تِمو روٚٹمُت اوس، تِمو کٔر ٲبی جہازس تل مدد کٔرِتھ۔ تہٕ یہ خوفہٕ زِ تِم گژھن تیز سینڈَس منٛز پیٚنہٕ، سٹریک سیل، تہٕ یِتھ کٔنۍ گٔیہٕ چلاونہٕ۔\n18.\\tتہٕ أسۍ سٮ۪ٹھاہ طوفانس سٍتۍ لٔگِتھ دٔسۍ جہازٕ ہلکہٕ۔\n19.\\tتہٕ تریمہِ دۅہہ کٔر أسۍ پننیو اتھو سٍتۍ جہازُک ٹال۔\n20.\\tتہٕ ییلہ نہ آفتاب تہٕ تارکھ واریاہن دۅہن منز ظٲہر سپدِ، تہٕ اسہِ پیٹھ آو نہٕ کانہہ لۄکُٹ واو تہٕ اسہِ پٲٹھۍیہ سورے وۅمید ختم گٔیہِ۔\n21.\\tمگر واریاہس کالس پرہیز کرنہٕ پتہٕ ووت پولس تِمن منز کھڑا تہٕ وونُن، جناب، ژیہ پزِ میہ بوزُن، تہٕ کریٹس نشہِ گژھہِ نہٕ یلہٕ تراوُن، تہٕ یہ نقصان تہٕ نقصان۔\n22. تہٕ وۅنۍ چُھس بہٕ ژےٚ نصیحت کران زِ تۅہہِ منز گژھہِ نہٕ کٲنسہ تہِ انسان سٕنزِ زُو نۄقصان، مگر جہازٕ سٍتـ̡ گژھہِ نہٕ۔\n23. تکیازِ از رٲژ اوس میہ سٍتـ̡ خدایہِ سُند فرشتہ، یٔمۍ سُند بہٕ چُھس تہٕ یٔمِس سٍتـ̡ بہٕ خدمت کران چُھس،\n24.\\tیہ ونان، خوفہٕ نہٕ پٲٹھۍ، پالس۔ ژے گژھہِ سیزرس برونہہ کُن انُن: تہٕ خداین دِژ ژے سٲری یم پانس سٍتۍ سفر کران چھِ۔\n25. اَمہِ مۄکھٕ چُھس خۅد رژھرٕن، کیازِ بہٕ چُھس خدایہِ سُند یقین تھاوان زِ یہِ گژھہِ تِتھۍ پٲٹھۍ یُس مے وَننہٕ آمُت اوس۔\n26. بہرحال اسہِ پزِ اکس مخصوص جزیرس پیٹھ تراونہٕ یُن۔\n27.\\tمگر ییلہ ژۅداہِم رٲژ آیہ، ییلہ اسہِ اڈریاہس منز ہیوٚر بوٚن پکناونہ آو، نصف رٲژ لگ بھگ جہازن باسیوو زِ تم چھہِ کُنہِ ملکس نزدیک۔\n28.\\tتہٕ لٔبِتھ وُہ وُہ پھیُر: تہٕ ییلہ تِم رژھ کھنڈ برونہہ کُن گٔیہِ، تِمو لٔبِتھ بییہ پندہ فیتھم۔\n29.\\tامہ پتہ یہ خوفہ زِ اسہِ ما گژھہِ کنہِ پتھرِ پیٹھ پییہ، تمو ترٲوۍ ژور لنگر تہ دۅہک خواہش۔\n30. تہٕ ییلہ جہازٕ جہازٕ منزٕ نیبر نیرُن اوس تیار، ییلہ تِمو ناو سمندرس منز تراوُن، رنگس تل زن تِمو آسہ جہازٕ منزٕ لنگر ترٲومٕتۍ،\n31.\\tپولس ووٚن سینچورین تہٕ فوجین زِ یِم جہازس منز روزنہٕ یِنہٕ وِزِ ہیکو نہٕ تۅہہ بچٲوِتھ۔\n32.\\tپتہٕ ژٔٹۍ سپاہیو ناوِ ہٕنز رزِ تہٕ ترووُن سُہ پیوٚو۔\n33.\\tییلہ دۅہ یُس دۅہ اوس یِوان، پولس دِژ سارِنٕے سارِنٕے ماز نِنٕچ درخواست تہٕ وونُن زِ یہِ چُھہ ژۄدٲہِم دۅہ یُس تۅہہ روزُن تہٕ روزٕ تھووُکھ نہٕ کیٚنٛہہ تہِ۔\n34. اَمہِ مۄکھٕ چُھس بہٕ ژےٚ دُعا کَران زِ یہِ چُھہ تُہٕندِ صحت خٲطرٕ، تِکیازِ یێلہِ نہٕ تۅہہِ منزٕ کٲنٛسہِ ہٕندِس کَلہٕ سٍتـ̡ مَس پیٚیہِ۔\n35. تہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، تٔمۍ روٚٹ روٹ، تہٕ تِمن سارِنٕے ہٕندِس حٲضِرس منز کوٚرُن خدایہ سُند شُکر ادا کرنہٕ۔\n36.\\tتیلہِ ٲسۍ تِم سارِنٕے خۅش گٔژھمٕتۍ، تہٕ تِمو کھیوٚو {کیٚنٛہہ} ماز تہِ۔\n37.\\tتہٕ أسۍ ٲسۍ جہازس منز زٕ ہتھ تریہ تہٕ شُراہ روح۔\n38.\\tتہٕ ییلہ تِمو سٮ۪ٹھاہ کھیوٚو، تِمو کٔر جہازٕ ہلکہٕ، تہٕ کٕنُک ترٛٲوِن سمندرس مَنٛز۔\n39.\\tتہٕ ییلہ دۅہ اوس، تِمن ٲس نہٕ زمینہٕ زانان، مگر تِمو کوٚر اکھ خاص نالہٕ دریافت، یتھ منز تِم ذہنس منز ٲس، اگر یہ ممکن آسہِ، جہازس منز تراوُن۔\n40. تہٕ ییلہ تِمو لنگر تُل، تِمو کٔر پانَے سمندرس کُن، تہٕ رڈر بینڈ یلہٕ، تہٕ ہوہس کُن تھوٚد تہٕ بٹھس کُن۔ {نِنہٕ...: یا، لنگر ژٹِتھ، تِمو ترٛٲوۍ سمندرس منز}\n41.\\tتہٕ أکِس جایہِ پیوٚو ییتہِ زٕ سمندر رلان ٲسۍ، تِمو لٔگۍ ٲبی جہاز۔ تہٕ برونٹھم حصہٕ اوس تیزی سان رٔٹتھ، تہٕ رود نہٕ حرکت کٔرتھ، مگر پوٚت حصہٕ اوس لہرن ہٕنٛدِ تشددٕ سۭتۍ پھُٹمُت۔\n42. تہٕ فوجین ہُند مشورٕ اوس قٲدِ مارُن، تاکہ یِمو منزٕ کانہہ تہِ ژھانٛٹھ نیرِتھ ژلنہٕ۔\n43.\\tمگر پولس بچاونہٕ خٲطرٕ تیار کورُن تِم تہندِس مقصدس نِش۔ تہٕ دِتُن حُکُم زِ یِم ژھرٛانٛٹ کٔرِتھ ہیکن تِم گۅڈٕ سمندرس منز تراوٕن، تہٕ زمینس پیٹھ واتن:\n44. تہٕ باقی، کینہہ جہازس پیٹھ، تہٕ کینہہ جہازٕ کِس {پھُٹمٕتۍ} ٹُکرس پیٹھ۔ تہٕ یِتھٕ پٲٹھۍ سپد یہِ سپُد، زِ تِم ژٔلِتھ بٔرِتھ زمینس پیٹھ۔","1.\\tتہ ییلہ تم ژٔلۍ، تیلہِ ٲس تمن پتاہ زِ اتھ جزیرس چھہ میلیٹا ونان۔\n2.\\tتہٕ وحشی لُکو ہٲو نہٕ اسہِ کُنہِ کُنہِ تہِ مہربانی، تکیازِ تِمو دِژ نار تہٕ اسہِ سارِنٕے سٍتـ̡ رٔٹِتھ تہٕ سردی کِنـ̡ ۔\n3.\\tییلہ پولسن لورِ ہُند اکھ بنڈل جمع کٔرِتھ نارس پیٹھ تھووُن، تتہِ دراو گرمہِ منزہ اکھ سانپ، تہٕ لوٚگ تٔمۍ سٕندِس اتھس پیٹھ بند۔\n4. تہٕ ییلہ وحشیو وُچھ زہریلہٕ درندٕ أمِس اتھس پیٹھ لٹکان، تِمو ووٚن پانہٕ پانس منز، کانہہ شک چُھ نہٕ یہِ انسان اکھ قاتل، یُس سمندرٕ منزٕ ژٔلِتھ ژٔلِتھ چُھ، مگر انتقام چُھ نہٕ زندٕ روزُن۔\n5.\\tتہٕ تٔمۍ لوٚگ درندہ نارس منز، تہٕ کوٚرُن نہٕ کانہہ نقصان محسوس۔\n6. توتہِ اوس تِمو وُچھان زِ سُہ گژھہِ ورم گومُت، نتہٕ پیوٚو اچانک موٗدمُت: مگر ییلہ تِمو واریاہس کالس وُچھان تہٕ أمِس وُچھُن نہٕ کانہہ نقصان وُچھان، تِمو بدلوو پنُن ارادٕ، تہٕ وونُن زِ سُہ چُھ خدا۔\n7.\\tیتھۍ حلقن منز اوس جزیرہ کس سردار سُند ملکیت، یمۍ سُند ناو پبلیئس اوس۔ یمۍ اسہِ استقبال کٔرۍ، تہٕ تریہ دۅہن رٔٹۍ رٔٹۍ۔\n8.\\tتہٕ سپُد یہِ زِ پبلیوس سُند مول اوس تپھ تہٕ خونریز بہاؤ سٍتـ̡ بیمار گومُت، یٔمِس نِش پولس اژان تہٕ دُعا کٔرٕن تہٕ تٔمِس تھپھ کٔرِتھ کوٚرُن شفا ۔\n9. یێلہِ یێلہِ یہِ کرنہٕ آو باقٕے تہِ، یِمن جزیرس مَنٛز بٮ۪مارِ آسہٕ، آیہِ تہٕ گٔیہِ ٹھیٖک:\n10.\\tیمۍ اسہِ واریاہ اعزاز دِتھ تہِ یزتھ دِژ۔ تہٕ ییلہ أسۍ درٛاو، تِمو دِژ تِتھۍ چیٖز یِم ضروٗری ٲسۍ۔\n11.\\tتہٕ تریہ ریتہٕ پَتہٕ دراو أسۍ اسکندریہ کِس أکِس جہازس منز، یُس جزیرس منز وندٕ اوس گومُت، ییمِچ نشانی کاسٹر تہٕ پولکس ٲس۔\n12.\\tتہٕ سیراکیوزس منز وسِتھ رودۍ أسۍ تریہ دۅہ۔\n13.\\tتہٕ تتہِ پیٹھہ اوٚن اسہِ کمپاس، تہٕ ووت ریجیمس کُن: تہٕ اکہ دۅہہ پَتہٕ ووٚتھ جنوبُک واو تہٕ أسۍ وٲتۍ دوٚیمہِ دۅہہ پُٹیولی کُن۔\n14.\\tییتہِ اسہِ بٲے لٔبۍ، تہٕ یِمن سٍتـ̡ سَتن دۅہن روزُن یژھان، تہٕ یِتھٕ پٲٹھۍ گٔے أسۍ رومس کُن۔\n15.\\tتہٕ تتہِ ییلہ بٲے اسہِ متعلق بوز، تِم آیہِ اسہِ سمکھنہٕ خٲطرٕ اپی فورمس تام، تہٕ تریہ شراب خانہٕ: یُس پولس وُچھ، تٔمۍ کٔر خدایہ سُند شُکر ادا تہٕ ہمت کٔرٕن۔\n16.\\tتہٕ ییلہ أسۍ روم وٲتۍ، سینچورین واتنوو قٲدۍ گارڈ کِس کپتانس نِش، مگر پولس آو أکِس سپاہی سٍتۍ روزُن یُس أمِس تھوو۔\n17. تہٕ سپُد یہِ زِ تریہ دۅہہٕ پَتہٕ بُلوو پولسن یہودین ہٕندِس سردارس یکوٹہٕ، تہٕ ییلہ تِم اَکہٕ وٹہٕ آیہ، تٔمۍ ووٚن تِمن انسانو {تہٕ} بٲے، یودوَے مے چُھہ نہٕ پننین مٲلن ہٕندِس رسمن خلاف کانہہ تہِ کٲم کٔرمٕژ، توتہِ اوسُس بہٕ یروشلم پیٹھٕ قٲد رومین ہٕندِس اتھس منز دِنہٕ آمُت۔\n18.\\tییلہ تمو میہ معائنہ کٔرۍ، تکیازِ میہ منز اوس نہ مرنک کانہہ وجہ۔\n19.\\tمگر ییلہ یہودی اتھ خلاف کتھ کٔر، بہٕ گۆو قیصرس نِش اپیل کرنہٕ خٲطرٕ مجبور۔ یہ چھہ نہ زِ میہ پزِ پننہِ قومس پیٹھ الزام لگاوُن۔\n20. اَمہِ مۅکھہٕ چُھس مے ژے بُلاونہٕ آمُت، تہٕ تۅہہِ سٍتـ̡ کتھ کرنہٕ خٲطرٕ، کیازِ زِ بہٕ چُھس اِسرٲیلٕچ وۅمید خٲطرٕ اتھ زنجیرس سٍتـ̡ بند۔\n21. تہٕ تِمو ووٚن أمِس زِ اسہِ آو نہٕ یہودایہ طرفہٕ تُہٕندِس مُتعلِق چِٹھہِ آمٕژ تہٕ نہ یِمو بٲے یِمو کُنہِ تہِ چِٹھہِ ہٲوِتھ تہٕ تُہٕندِس سٍتـ̡ کُنہِ تہِ بُلاونہٕ آمُت۔\n22.\\tمگر أسۍ چھہِ ژے بوزُن یژھان، تکیازِ اتھ فرقس متعلق چھہِ اسہِ پتاہ زِ ییتہِ تہِ اتھ خلاف کتھ کرنہ یوان چھیہ۔\n23.\\tتہٕ ییلہ تمو أمس اکھ دۅہ مقرر کوٚر، تٔمۍ سٕندِس مکانس منز آیہ واریاہ أمس نِش۔ یٔمِس سٍتـ̡ تٔمۍ حضرت عیسیٰ سٕنزِ بادشاہی ہٕنز وضاحت تہٕ گوٲہی دِژ، تہٕ حضرت عیسیٰ سٕندِس شریعت سٍتـ̡ تہٕ پیغمبرن سٍتـ̡ صبحٲے پیٹھٕ شامس تام قایم کٔرِتھ۔\n24.\\tتہٕ کینہہ ٲسۍ تمن چیزن پیٹھ یقین کران یم وننہ ٲس آمٕتۍ، تہٕ کینژَن اوس نہٕ یقین کران۔\n25.\\tتہٕ ییلہ تِمو پانہٕ پانہٕ پانہٕ متفق گٔیہ، تِمو درٛاو تِمو پَتہٕ پۯاوُن اَکھ لفظ، یِمن ہُند روح القدس اوس سانین آباؤ اجدادن سٍتـ̡ وَننہٕ آمُت،\n26.\\tیہ ونُن، یێمہِ لُکن نِش گژھِو تہٕ ونُن، بوزِو تہٕ سمجُن نہٕ۔ تہٕ وُچھِتھ تہٕ وُچھِو نہٕ وُچھان:\n27.\\tیِمن ہُند دِل چُھ موم گٔژھمُت، تہٕ تِہٕندِس کَن چُھہ بوزنہٕ سٍتـ̡ سٍتـ̡ تہٕ تِمن ہٕنزِ أچھ چھے بند گٔمٕژ۔ تاکہ تِم گژھن {پنٕنۍ} اچھو سٍتۍ وُچھن، تہٕ بوزنہٕ یِن تہٕ {پنٕنۍ} دِلہٕ سٍتۍ سمجُن، تہٕ گژھن تِمن شفا دِنہٕ۔\n28. تێمہِ کِنۍ گژھہِ تۅہہِ معلوم زِ خدایہِ سٕنز نجات چھے غیر قومن خٲطرٕ سوزنہٕ آمٕژ، تہٕ تِم گژھن یہِ بوزنہٕ۔\n29.\\tتہٕ ییلہ تٔمۍ یِم لفظ ووٚن، یہودی دراو تہٕ گٔیہِ پانہٕ وٲنۍ سٮ۪ٹھاہ استدلال۔\n30. تہٕ پولس روٗد پوٗرٕ زٕ ؤری پننِس کرایہ دارس مَنٛز روزان، تہٕ یُس أمِس نِش آو سُہ سورُے حٲصِل کرنہٕ۔\n31.\\tخدایہِ سٕنزِ بادشٲہی ہٕنز تبلیغ کٔرٕن، تہٕ تِمن چیزن ہیچھناوٕنـ̡ یِم خداوند عیسیٰ مسیحس سٍتـ̡ وابستہٕ چھِ، پوٗرٕ اعتبارٕ سٍتـ̡ چُھہ نہٕ کانہہ تہِ انسان أمِس منع کٔرِتھ۔"];
